// Tela Resultados: totais, última corrida e progressão (gráficos).

import React, { useEffect, useMemo, useState } from 'react'
import { ScrollView, StyleSheet, Text, View } from 'react-native'
import { getCorridas, diasTreinados, useStore, type Corrida } from '../state'
import { fmtData } from '../format'
import { Progressao } from '../components/Progressao'
import { Aneis } from '../components/Aneis'
import { CartaoObjetivo } from '../components/CartaoObjetivo'
import { corridasSinteticas } from '../devdata'
import { telemetry } from '../telemetry'
import { theme } from '../theme'

export function Resultados(): React.JSX.Element {
  const versao = useStore()
  const [selecionada, setSelecionada] = useState<Corrida | null>(null)

  useEffect(() => {
    telemetry.resultsViewed()
  }, [])

  // Memo pela versão do store: o array novo a cada render derrubaria o
  // useMemo da Progressao (e a seleção do marcador) ao escolher uma corrida.
  const corridas = useMemo(() => {
    let cs = [...getCorridas()].sort((a, b) => b.inicio.localeCompare(a.inicio))
    // Em desenvolvimento, com poucas corridas reais, usa dados sintéticos
    // (~4 meses) pra experimentar a tela — principalmente a Progressão.
    if (__DEV__ && cs.length < 15) {
      cs = corridasSinteticas().sort((a, b) => b.inicio.localeCompare(a.inicio))
    }
    return cs
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [versao])
  if (corridas.length === 0) {
    return (
      <View style={styles.empty}>
        <Text style={styles.muted}>Nenhuma corrida ainda.</Text>
        <Text style={[styles.muted, styles.center]}>
          Vá em <Text style={styles.strong}>Entradas</Text> e toque em <Text style={styles.italic}>Comecei</Text> quando
          sair pra correr.
        </Text>
      </View>
    )
  }
  const dias = diasTreinados(corridas)
  const n = corridas.length
  const tempoMedio = Math.round(corridas.reduce((s, c) => s + c.duracaoMin, 0) / n)
  const comDist = corridas.filter((c) => c.distanciaKm != null)
  const distMedia = comDist.length
    ? comDist.reduce((s, c) => s + (c.distanciaKm ?? 0), 0) / comDist.length
    : null
  const ult = corridas[0]

  return (
    <ScrollView>
      <View style={styles.statRows}>
        <View style={styles.cards}>
          <View style={[styles.card, styles.stat]}>
            <Text style={styles.big}>{dias}</Text>
            <Text style={styles.statLabel}>dias treinados</Text>
          </View>
          <View style={[styles.card, styles.stat]}>
            <Text style={styles.big}>{n}</Text>
            <Text style={styles.statLabel}>corridas</Text>
          </View>
        </View>
        <View style={styles.cards}>
          <View style={[styles.card, styles.stat]}>
            <Text style={styles.big}>{tempoMedio}</Text>
            <Text style={styles.statLabel}>min médio</Text>
          </View>
          <View style={[styles.card, styles.stat]}>
            <Text style={styles.big}>{distMedia ? distMedia.toFixed(1) : '—'}</Text>
            <Text style={styles.statLabel}>km médio</Text>
          </View>
        </View>
      </View>

      <CartaoObjetivo corridas={corridas} />

      <Text style={styles.section}>Última corrida</Text>
      <View style={styles.card}>
        <View style={styles.lrTop}>
          <Text style={styles.lrDate}>{fmtData(ult.inicio)}</Text>
          <Text style={styles.tag}>{ult.local === 'esteira' ? 'Esteira' : 'Externo'}</Text>
        </View>
        <View style={styles.lrStats}>
          <View style={styles.lrStat}>
            <Text style={styles.big24}>{ult.duracaoMin}</Text>
            <Text style={styles.statLabel}>min</Text>
          </View>
          <View style={styles.lrStat}>
            <Text style={styles.big24}>{ult.distanciaKm ? ult.distanciaKm.toFixed(1) : '—'}</Text>
            <Text style={styles.statLabel}>km</Text>
          </View>
        </View>
      </View>

      <Text style={styles.section}>Análise</Text>
      <View style={styles.analiseHead}>
        <View style={styles.analiseTxt}>
          <Text style={styles.chartTitle}>Frequência</Text>
          <Text style={styles.progHint}>arraste para o lado →</Text>
        </View>
        <Aneis corrida={selecionada} />
      </View>
      <Progressao corridas={corridas} onSelecionar={setSelecionada} />
    </ScrollView>
  )
}

