// Tela Saúde (marcadores): gráfico de evolução (peso / glicemia / pressão),
// botão "Nova medição" e lista com edição e exclusão. O formulário — tanto o
// de nova medição quanto o de edição — abre em tela própria (como a primeira
// medição do onboarding) e volta pra cá ao salvar ou cancelar.
// A nova entrada já vem pré-preenchida com os valores da última medição —
// o usuário muda só o que variou. Glicemia e pressão têm um checkbox
// "registrar", sempre desmarcado de início: marcando, a roda aparece (no
// último valor, se houver) e o campo entra no registro; desmarcando, some
// e é desconsiderado. Sem valor anterior, o campo só entra se o usuário
// girar a roda (pressão exige giro nas duas); com valor anterior, entra
// mesmo sem giro. Na edição, desmarcar limpa um valor já salvo.
// A lista só mostra medições reais — os dados sintéticos de dev servem só
// pra experimentar o gráfico.

import React, { useMemo, useRef, useState } from 'react'
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native'
import {
  type Marcador,
  getMarcadores,
  addMarcador,
  updateMarcador,
  removeMarcador,
  ultimoMarcador,
  uid,
  useStore,
} from '../state'
import { fmtDataHora } from '../format'
import { WheelPicker, type WheelPickerHandle } from '../components/WheelPicker'
import { Checkbox } from '../components/Checkbox'
import { GraficoMarcador, type PontoMarcador } from '../components/GraficoMarcador'
import { marcadoresSinteticos } from '../devdata'
import { telemetry } from '../telemetry'
import { theme } from '../theme'

type GrafSel = 'peso' | 'glicemia' | 'pressao'

export function Marcadores(): React.JSX.Element {
  const versao = useStore()
  const [editando, setEditando] = useState<Marcador | null>(null)
  const [criando, setCriando] = useState(false)
  // Exclusão em dois toques no próprio botão: "Excluir" vira "Confirmar?".
  const [armado, setArmado] = useState<string | null>(null)
  const [graf, setGraf] = useState<GrafSel>('peso')

  if (editando) {
    return <FormEdicao key={editando.id} marcador={editando} onFechar={() => setEditando(null)} />
  }
  if (criando) {
    return <FormNovo onFechar={() => setCriando(false)} />
  }

  const entradas = [...getMarcadores()].sort((a, b) => b.quando.localeCompare(a.quando))

  // Memo pela versão do store (mesmo motivo da tela Resultados). Em dev, com
  // poucas medições reais, o gráfico usa dados sintéticos (~4 meses).
  const grafDados = useMemo((): { pontos: PontoMarcador[]; cores: string[]; unidade: string } => {
    let ms = entradas
    if (__DEV__ && ms.length < 15) {
      ms = marcadoresSinteticos().sort((a, b) => b.quando.localeCompare(a.quando))
    }
    if (graf === 'peso') {
      return {
        pontos: ms.map((m) => ({ id: m.id, quando: m.quando, valores: [m.peso] })),
        cores: [theme.blue],
        unidade: 'kg',
      }
    }
    if (graf === 'glicemia') {
      return {
        pontos: ms
          .filter((m) => m.glicemia != null)
          .map((m) => ({ id: m.id, quando: m.quando, valores: [m.glicemia!] })),
        cores: [theme.blue],
        unidade: 'mg/dL',
      }
    }
    return {
      pontos: ms
        .filter((m) => m.pressaoSis != null || m.pressaoDia != null)
        .map((m) => ({
          id: m.id,
          quando: m.quando,
          valores: [m.pressaoSis ?? null, m.pressaoDia ?? null],
        })),
      cores: [theme.blue, theme.tempo],
      unidade: 'mmHg',
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [versao, graf])

  return (
    // Sem registros, a página é só o botão de nova medição — centralizado.
    <ScrollView
      keyboardShouldPersistTaps="handled"
      contentContainerStyle={entradas.length === 0 ? styles.centrado : undefined}
    >
      {entradas.length > 0 ? (
        <>
          <Text style={styles.section}>Evolução</Text>
          <View style={styles.card}>
            <View style={styles.seg}>
              <Pressable
                style={[styles.segBtn, graf === 'peso' && styles.segBtnOn]}
                onPress={() => setGraf('peso')}
              >
                <Text style={[styles.segTxt, graf === 'peso' && styles.segTxtOn]}>Peso</Text>
              </Pressable>
              <Pressable
                style={[styles.segBtn, graf === 'glicemia' && styles.segBtnOn]}
                onPress={() => setGraf('glicemia')}
              >
                <Text style={[styles.segTxt, graf === 'glicemia' && styles.segTxtOn]}>Glicemia</Text>
              </Pressable>
              <Pressable
                style={[styles.segBtn, graf === 'pressao' && styles.segBtnOn]}
                onPress={() => setGraf('pressao')}
              >
                <Text style={[styles.segTxt, graf === 'pressao' && styles.segTxtOn]}>Pressão</Text>
              </Pressable>
            </View>
            {graf === 'pressao' ? (
              <View style={styles.legenda}>
                <Text style={[styles.legTxt, { color: theme.blue }]}>● sistólica</Text>
                <Text style={[styles.legTxt, { color: theme.tempo }]}>● diastólica</Text>
              </View>
            ) : null}
            <GraficoMarcador pontos={grafDados.pontos} cores={grafDados.cores} unidade={grafDados.unidade} />
          </View>
        </>
      ) : null}

      <View style={styles.novaWrap}>
        <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={() => setCriando(true)}>
          <Text style={styles.primaryTxt}>Nova medição</Text>
        </Pressable>
      </View>

      {entradas.length > 0 ? (
        <>
          <Text style={styles.section}>Registros</Text>
          <View style={styles.lista}>
            {entradas.map((m) => (
              <View key={m.id} style={styles.card}>
                <Text style={styles.lrDate}>{fmtDataHora(m.quando)}</Text>
                <View style={styles.lrStats}>
                  <View style={styles.lrStat}>
                    <Text style={styles.big}>{m.peso}</Text>
                    <Text style={styles.statLabel}>kg</Text>
                  </View>
                  <View style={styles.lrStat}>
                    <Text style={styles.big}>{m.glicemia ?? '—'}</Text>
                    <Text style={styles.statLabel}>mg/dL</Text>
                  </View>
                  <View style={styles.lrStat}>
                    <Text style={styles.big}>
                      {m.pressaoSis != null && m.pressaoDia != null ? `${m.pressaoSis}/${m.pressaoDia}` : '—'}
                    </Text>
                    <Text style={styles.statLabel}>mmHg</Text>
                  </View>
                </View>
                <View style={styles.actions}>
                  <Pressable
                    style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]}
                    onPress={() => setEditando(m)}
                  >
                    <Text style={styles.ghostTxt}>Editar</Text>
                  </Pressable>
                  <Pressable
                    style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]}
                    onPress={() => {
                      if (armado === m.id) {
                        removeMarcador(m.id)
                        setArmado(null)
                        return
                      }
                      setArmado(m.id)
                    }}
                  >
                    <Text style={[styles.ghostTxt, styles.dangerTxt]}>
                      {armado === m.id ? 'Confirmar?' : 'Excluir'}
                    </Text>
                  </Pressable>
                </View>
              </View>
            ))}
          </View>
        </>
      ) : null}
    </ScrollView>
  )
}

// --- Rodas de medição (novo registro e edição) ---
// Glicemia e pressão abrem no 50 (ou no valor da medição-base) e a roda começa
// em 40. Cada uma tem um checkbox "registrar": desmarcado, a roda fica
// escondida e o campo não entra no registro. Com valor na medição-base, a roda
// abre nele e conta mesmo sem giro; sem valor-base, só conta se girar.
function RodasMarcador({
  base,
  pesoRef,
  gliRef,
  sisRef,
  diaRef,
  registrar,
  onToggle,
  onTocado,
}: {
  base: Marcador | null // última medição (prefill) ou o registro em edição
  pesoRef: React.RefObject<WheelPickerHandle | null>
  gliRef: React.RefObject<WheelPickerHandle | null>
  sisRef: React.RefObject<WheelPickerHandle | null>
  diaRef: React.RefObject<WheelPickerHandle | null>
  registrar: { glicemia: boolean; pressao: boolean }
  onToggle: (campo: 'glicemia' | 'pressao') => void
  onTocado: (roda: 'glicemia' | 'sis' | 'dia') => void
}): React.JSX.Element {
  return (
    <>
      <WheelPicker ref={pesoRef} min={30} max={150} step={1} def={base?.peso ?? 70} label="Peso" unit="kg" />
      <View style={styles.field}>
        <View style={styles.fieldHead}>
          <Text style={styles.fieldLabel}>Glicemia</Text>
          <Checkbox rotulo="registrar" marcado={registrar.glicemia} onToggle={() => onToggle('glicemia')} />
        </View>
        {registrar.glicemia ? (
          <WheelPicker
            ref={gliRef}
            min={40}
            max={400}
            step={1}
            def={base?.glicemia ?? 50}
            unit="mg/dL"
            onChange={() => onTocado('glicemia')}
          />
        ) : null}
      </View>
      <View style={styles.field}>
        <View style={styles.fieldHead}>
          <Text style={styles.fieldLabel}>Pressão arterial</Text>
          <Checkbox rotulo="registrar" marcado={registrar.pressao} onToggle={() => onToggle('pressao')} />
        </View>
        {registrar.pressao ? (
          <View style={styles.pickerRow}>
            <View style={styles.pickerCell}>
              <WheelPicker
                ref={sisRef}
                min={40}
                max={250}
                step={1}
                def={base?.pressaoSis ?? 50}
                label="sistólica"
                unit="mmHg"
                onChange={() => onTocado('sis')}
              />
            </View>
            <View style={styles.pickerCell}>
              <WheelPicker
                ref={diaRef}
                min={40}
                max={250}
                step={1}
                def={base?.pressaoDia ?? 50}
                label="diastólica"
                unit="mmHg"
                onChange={() => onTocado('dia')}
              />
            </View>
          </View>
        ) : null}
      </View>
    </>
  )
}

// --- Formulário de nova medição (tela própria, aberta pelo botão "Nova medição") ---
function FormNovo({ onFechar }: { onFechar: () => void }): React.JSX.Element {
  const pesoRef = useRef<WheelPickerHandle>(null)
  const gliRef = useRef<WheelPickerHandle>(null)
  const sisRef = useRef<WheelPickerHandle>(null)
  const diaRef = useRef<WheelPickerHandle>(null)

  const base = ultimoMarcador()
  // Os checkboxes começam desmarcados mesmo com valor na medição-base: o campo
  // só entra no registro se o usuário marcar "registrar". Com valor-base a
  // roda abre nele e conta mesmo sem giro; sem valor-base, só conta se girar.
  const [registrar, setRegistrar] = useState({ glicemia: false, pressao: false })
  const [tocado, setTocado] = useState({ glicemia: false, sis: false, dia: false })
  const toggleRegistrar = (campo: 'glicemia' | 'pressao'): void => {
    setRegistrar((r) => ({ ...r, [campo]: !r[campo] }))
    // Ao desmarcar, o campo sai do registro — o giro anterior é esquecido.
    if (registrar[campo]) {
      setTocado((t) => (campo === 'glicemia' ? { ...t, glicemia: false } : { ...t, sis: false, dia: false }))
    }
  }
  const marcarTocado = (roda: 'glicemia' | 'sis' | 'dia'): void => setTocado((t) => ({ ...t, [roda]: true }))

  const salvar = (): void => {
    const glicemiaOk = registrar.glicemia && (base?.glicemia != null || tocado.glicemia)
    const pressaoOk =
      registrar.pressao &&
      ((base?.pressaoSis != null && base?.pressaoDia != null) || (tocado.sis && tocado.dia))
    addMarcador({
      id: uid(),
      quando: new Date().toISOString(),
      peso: pesoRef.current?.getValue() ?? 70,
      ...(glicemiaOk ? { glicemia: gliRef.current?.getValue() ?? 50 } : {}),
      ...(pressaoOk
        ? { pressaoSis: sisRef.current?.getValue() ?? 50, pressaoDia: diaRef.current?.getValue() ?? 50 }
        : {}),
    })
    telemetry.markerSaved()
    onFechar()
  }

  return (
    <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.centrado}>
      <View style={styles.cardForm}>
        <Text style={styles.muted}>
          O peso já vem com o último valor — mude só se variou. Pra glicemia ou pressão, marque "registrar":
          a roda abre no último valor registrado.
        </Text>
        <RodasMarcador
          base={base}
          pesoRef={pesoRef}
          gliRef={gliRef}
          sisRef={sisRef}
          diaRef={diaRef}
          registrar={registrar}
          onToggle={toggleRegistrar}
          onTocado={marcarTocado}
        />
        <View style={styles.actions}>
          <Pressable style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]} onPress={onFechar}>
            <Text style={styles.ghostTxt}>Cancelar</Text>
          </Pressable>
          <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={salvar}>
            <Text style={styles.primaryTxt}>Salvar</Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  )
}

// --- Edição (a data não é editável: é o momento da medição) ---
function FormEdicao({ marcador: m, onFechar }: { marcador: Marcador; onFechar: () => void }): React.JSX.Element {
  const pesoRef = useRef<WheelPickerHandle>(null)
  const gliRef = useRef<WheelPickerHandle>(null)
  const sisRef = useRef<WheelPickerHandle>(null)
  const diaRef = useRef<WheelPickerHandle>(null)

  // Os checkboxes começam desmarcados mesmo quando o registro tem valor: o
  // campo só é salvo se o usuário marcar "registrar" (desmarcar limpa o valor
  // salvo). Com valor no registro a roda abre nele e conta mesmo sem giro;
  // sem valor, só conta se girar.
  const [registrar, setRegistrar] = useState({ glicemia: false, pressao: false })
  const [tocado, setTocado] = useState({ glicemia: false, sis: false, dia: false })
  const toggleRegistrar = (campo: 'glicemia' | 'pressao'): void => {
    setRegistrar((r) => ({ ...r, [campo]: !r[campo] }))
    // Ao desmarcar, o campo sai do registro — o giro anterior é esquecido.
    if (registrar[campo]) {
      setTocado((t) => (campo === 'glicemia' ? { ...t, glicemia: false } : { ...t, sis: false, dia: false }))
    }
  }
  const marcarTocado = (roda: 'glicemia' | 'sis' | 'dia'): void => setTocado((t) => ({ ...t, [roda]: true }))

  const salvar = (): void => {
    const glicemiaOk = registrar.glicemia && (m.glicemia != null || tocado.glicemia)
    const pressaoOk =
      registrar.pressao && ((m.pressaoSis != null && m.pressaoDia != null) || (tocado.sis && tocado.dia))
    updateMarcador(m.id, {
      peso: pesoRef.current?.getValue() ?? m.peso,
      glicemia: glicemiaOk ? (gliRef.current?.getValue() ?? 50) : undefined,
      pressaoSis: pressaoOk ? (sisRef.current?.getValue() ?? 50) : undefined,
      pressaoDia: pressaoOk ? (diaRef.current?.getValue() ?? 50) : undefined,
    })
    telemetry.markerSaved()
    onFechar()
  }

  return (
    <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.centrado}>
      <View style={styles.cardForm}>
        <View style={styles.row}>
          <Text style={styles.muted}>Quando</Text>
          <Text style={styles.strong}>{fmtDataHora(m.quando)}</Text>
        </View>
        <RodasMarcador
          base={m}
          pesoRef={pesoRef}
          gliRef={gliRef}
          sisRef={sisRef}
          diaRef={diaRef}
          registrar={registrar}
          onToggle={toggleRegistrar}
          onTocado={marcarTocado}
        />
        <View style={styles.actions}>
          <Pressable style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]} onPress={onFechar}>
            <Text style={styles.ghostTxt}>Cancelar</Text>
          </Pressable>
          <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={salvar}>
            <Text style={styles.primaryTxt}>Salvar</Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  )
}

