// Compromissos (milestone 7, set/2026): "Combinamos caminhada hoje às 18h.
// Eu vou estar aqui." O compromisso transforma a prescrição do Autopilot
// numa relação temporal: o sistema propõe um horário concreto, o usuário
// combina, o treinador lembra (notifications.ts) e o desfecho é registrado.
//
// Lógica pura e determinística, como o Decision Engine: a proposta deriva do
// plano vigente e do histórico, e só se persiste quando o usuário combina —
// antes disso ela é recalculada a cada leitura. Quem agenda o lembrete e
// dispara a telemetria é a camada de aplicação (Entradas.tsx / App.tsx).
//
// Adaptação v1: depois de um compromisso perdido, a proposta é a mesma hora
// no dia seguinte — remarcar, não desistir. Duração e atividade já são
// adaptadas pelo Decision Engine a partir dos sinais e do feedback.

import {
  getAvisoTreinador,
  getCorridas,
  getModeloUsuario,
  setAvisoTreinador,
  setModeloUsuario,
  uid,
  type Corrida,
} from './state'
import { type Compromisso, type ModeloUsuario, type StatusCompromisso } from './usuario'
import { ROTULO_ATIVIDADE, type Decisao } from './decisao'
import { agendarLembrete, cancelarLembrete } from './notifications'
import { telemetry } from './telemetry'

/** Sem histórico nenhum, a proposta é fim da tarde. */
const HORA_PADRAO = 18

function mesmoDia(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
}

/** Compromisso vigente, se houver: o mais distante no futuro ainda aberto. */
export function compromissoAtivo(compromissos: Compromisso[]): Compromisso | undefined {
  const abertos = compromissos.filter((c) => c.status === 'proposto' || c.status === 'combinado')
  if (abertos.length === 0) return undefined
  return abertos.reduce((a, b) => (a.quando > b.quando ? a : b))
}

/** Último compromisso fechado, se houver — base da adaptação da proposta. */
export function ultimoCompromisso(compromissos: Compromisso[]): Compromisso | undefined {
  const fechados = compromissos.filter((c) => c.status !== 'proposto' && c.status !== 'combinado')
  if (fechados.length === 0) return undefined
  return fechados.reduce((a, b) => (a.quando > b.quando ? a : b))
}

/** A hora a propor: a do último compromisso; sem ele, a da última sessão;
 *  sem nada, a preferência declarada no onboarding; por fim, 18h.
 *  Reusar a hora combinada mantém a rotina previsível. */
function horaPreferida(modelo: ModeloUsuario, corridas: Corrida[]): { hora: number; minuto: number } {
  const ultimo = modelo.compromissos.reduce<Compromisso | null>(
    (acc, c) => (acc === null || c.quando > acc.quando ? c : acc),
    null,
  )
  const ultimaCorrida = corridas.reduce<string | null>(
    (acc, c) => (acc === null || c.inicio > acc ? c.inicio : acc),
    null,
  )
  const base = ultimo != null ? new Date(ultimo.quando) : ultimaCorrida !== null ? new Date(ultimaCorrida) : null
  if (base !== null) return { hora: base.getHours(), minuto: base.getMinutes() }
  const declarada = modelo.disponibilidade?.horaPreferida
  if (declarada != null) {
    const hora = Math.floor(declarada)
    return { hora, minuto: Math.round((declarada - hora) * 60) }
  }
  return { hora: HORA_PADRAO, minuto: 0 }
}

/** Avança até o próximo dia da semana preferido (o próprio dia, se for um). */
function proximoDiaPreferido(dia: Date, dias: number[]): Date {
  const d = new Date(dia)
  while (!dias.includes(d.getDay())) d.setDate(d.getDate() + 1)
  return d
}

/**
 * Propõe o próximo compromisso a partir da decisão vigente. Regra v1: a hora
 * preferida, hoje se ainda faltar pelo menos uma hora e não houver sessão
 * hoje; senão, amanhã. Com dias preferidos declarados (onboarding), o dia
 * anda até o próximo preferido. Função pura — nada é gravado aqui.
 */
export function proporCompromisso(
  decisao: Decisao,
  modelo: ModeloUsuario,
  corridas: Corrida[],
  agora: Date = new Date(),
): Compromisso {
  const { hora, minuto } = horaPreferida(modelo, corridas)
  let dia = new Date(agora)
  dia.setHours(hora, minuto, 0, 0)
  const treinouHoje = corridas.some((c) => mesmoDia(new Date(c.inicio), agora))
  if (treinouHoje || dia.getTime() - agora.getTime() < 60 * 60 * 1000) {
    dia.setDate(dia.getDate() + 1)
  }
  const dias = modelo.disponibilidade?.diasSemana
  if (dias != null && dias.length > 0) dia = proximoDiaPreferido(dia, dias)
  return {
    id: uid(),
    atividade: ROTULO_ATIVIDADE[decisao.atividade].toLowerCase(),
    quando: dia.toISOString(),
    duracaoMin: decisao.duracaoMin,
    status: 'proposto',
  }
}

export interface DesfechoCompromisso {
  id: string
  status: StatusCompromisso
}

/**
 * Fecha os compromissos abertos contra o histórico: sessão no mesmo dia ⇒
 * 'cumprido'; dia encerrado sem sessão ⇒ 'perdido' (o combinado) ou
 * 'cancelado' (a proposta que nunca foi aceita). Pura: devolve o modelo
 * atualizado e os desfechos (pra telemetria), ou null se nada mudou.
 */
export function resolverCompromissos(
  modelo: ModeloUsuario,
  corridas: Corrida[],
  agora: Date = new Date(),
): { modelo: ModeloUsuario; desfechos: DesfechoCompromisso[] } | null {
  const desfechos: DesfechoCompromisso[] = []
  let mudou = false
  const resolvidos = modelo.compromissos.map((c) => {
    if (c.status !== 'proposto' && c.status !== 'combinado') return c
    const dia = new Date(c.quando)
    if (corridas.some((r) => mesmoDia(new Date(r.inicio), dia))) {
      mudou = true
      desfechos.push({ id: c.id, status: 'cumprido' })
      return { ...c, status: 'cumprido' as const, desfecho: 'sessão registrada no dia' }
    }
    const fimDoDia = new Date(dia)
    fimDoDia.setHours(23, 59, 59, 999)
    if (fimDoDia < agora) {
      mudou = true
      if (c.status === 'combinado') {
        desfechos.push({ id: c.id, status: 'perdido' })
        return { ...c, status: 'perdido' as const, desfecho: 'o dia passou sem sessão' }
      }
      return { ...c, status: 'cancelado' as const, desfecho: 'proposta não aceita' }
    }
    return c
  })
  if (!mudou) return null
  return { modelo: { ...modelo, compromissos: resolvidos }, desfechos }
}

/** Aplica o resolver ao estado persistido, cancela lembretes de compromissos
 *  fechados e registra a telemetria dos desfechos. No boot e ao salvar corrida. */
export function reconciliarCompromissos(): void {
  const atual = getModeloUsuario()
  const r = resolverCompromissos(atual, getCorridas())
  if (r === null) return
  setModeloUsuario(r.modelo)
  for (const d of r.desfechos) {
    const c = atual.compromissos.find((x) => x.id === d.id)
    if (c?.notificacaoId != null) void cancelarLembrete(c.notificacaoId)
    if (d.status === 'cumprido') telemetry.compromissoCumprido()
    else if (d.status === 'perdido') telemetry.compromissoPerdido()
  }
  // O treinador ganha assunto novo: cobrança gentil (perdido) ou reconhecer +
  // propor a próxima (cumprido) — o shell avisa e a conversa abre com o motivo.
  // O aviso 'meta' (subida de nível, gravado no recálculo do Autopilot) tem
  // precedência sobre o 'cumprido' da mesma sessão: a celebração vem primeiro.
  if (r.desfechos.some((d) => d.status === 'perdido')) setAvisoTreinador('perdido')
  else if (r.desfechos.some((d) => d.status === 'cumprido') && getAvisoTreinador() !== 'meta') {
    setAvisoTreinador('cumprido')
  }
}

/** Quantos combinados seguidos foram perdidos, do mais recente pra trás —
 *  alimenta o texto do lembrete ("você não correu nas últimas 3"). Pura. */
function perdidosSeguidos(compromissos: Compromisso[]): number {
  const fechados = compromissos
    .filter((c) => c.status === 'cumprido' || c.status === 'perdido')
    .sort((a, b) => (a.quando < b.quando ? 1 : -1))
  let n = 0
  for (const c of fechados) {
    if (c.status !== 'perdido') break
    n++
  }
  return n
}

/** O usuário aceitou a proposta: vira compromisso combinado, com o lembrete
 *  agendado (quando a plataforma permite — na web o cartão é o lembrete). */
export async function combinar(proposta: Compromisso): Promise<void> {
  const atual = getModeloUsuario()
  const notificacaoId = (await agendarLembrete(proposta, perdidosSeguidos(atual.compromissos))) ?? undefined
  setModeloUsuario({
    ...atual,
    compromissos: [...atual.compromissos, { ...proposta, status: 'combinado', notificacaoId }],
  })
  telemetry.compromissoCombinado(proposta.atividade)
}

/** O usuário pediu para remarcar na conversa (milestone 8): o compromisso
 *  ativo vira 'cancelado' e o lembrete é desagendado. A nova proposta é
 *  recalculada por proporCompromisso — quem decide o horário continua sendo
 *  o algoritmo. */
export async function cancelarCompromissoAtivo(): Promise<void> {
  const atual = getModeloUsuario()
  const ativo = compromissoAtivo(atual.compromissos)
  if (ativo == null) return
  if (ativo.notificacaoId != null) await cancelarLembrete(ativo.notificacaoId)
  setModeloUsuario({
    ...atual,
    compromissos: atual.compromissos.map((c) =>
      c.id === ativo.id ? { ...c, status: 'cancelado' as const, desfecho: 'remarcado na conversa' } : c,
    ),
  })
}
