// Ícone de alto-falante minimalista (traço), par do MicIcon — desenhado em
// SVG para não depender de emoji pesado. A onda aparece quando está tocando.
import React from 'react'
import Svg, { Path } from 'react-native-svg'

export function SpeakerIcon({
  tamanho = 16,
  cor,
  tocando = false,
}: {
  tamanho?: number
  cor: string
  tocando?: boolean
}): React.JSX.Element {
  return (
    <Svg width={tamanho} height={tamanho} viewBox="0 0 24 24" fill="none">
      <Path
        d="M4 9.5v5h3.2l4.3 4.2V5.3L7.2 9.5H4Z"
        stroke={cor}
        strokeWidth="1.8"
        strokeLinejoin="round"
      />
      {tocando ? (
        <Path
          d="M16.5 8.8a5.2 5.2 0 0 1 0 6.4"
          stroke={cor}
          strokeWidth="1.8"
          strokeLinecap="round"
        />
      ) : null}
    </Svg>
  )
}
