// Tela de aviso pré-permissão do GPS — a primeira coisa que o app mostra na
// 1ª abertura, antes inclusive do onboarding. Explica o porquê e deixa o
// usuário decidir: "Permitir" abre o prompt do sistema; "Agora não" não
// volta a perguntar (resta o link "aqui" na tela Entradas). Tela cheia,
// fora do shell, como o Onboarding.

import React from 'react'
import { Pressable, StyleSheet, Text, View } from 'react-native'
import { setGpsDecidido } from '../state'
import { pedirPermissaoGps } from '../gps'
import { theme } from '../theme'

export function PermissaoGps(): React.JSX.Element {
  const permitir = async (): Promise<void> => {
    await pedirPermissaoGps() // mesmo negada, a decisão vale — o link da tela Entradas cobre o resto
    setGpsDecidido() // emite pro store: o App segue pro onboarding/shell
  }

  return (
    <View style={styles.tela}>
      <Text style={styles.icone}>📍</Text>
      <Text style={styles.lead}>Medir a distância?</Text>
      <Text style={styles.muted}>
        Pra estimar a distância das suas corridas ao ar livre, o app usa a localização (GPS) do aparelho — só
        enquanto a corrida está em andamento. Nada sai do seu aparelho.
      </Text>
      <Text style={styles.muted}>A seguir, o sistema vai pedir sua permissão.</Text>
      <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={() => void permitir()}>
        <Text style={styles.primaryTxt}>Permitir</Text>
      </Pressable>
      <Pressable style={({ pressed }) => [styles.ghost, pressed && styles.pressed]} onPress={() => setGpsDecidido()}>
        <Text style={styles.ghostTxt}>Agora não</Text>
      </Pressable>
    </View>
  )
}

const styles = StyleSheet.create({
  tela: {
    flex: 1,
    backgroundColor: theme.bg,
    alignItems: 'center',
    justifyContent: 'center',
    gap: 18,
    paddingHorizontal: 24,
  },
  icone: {
    fontSize: 56,
  },
  lead: {
    fontSize: 19,
    textAlign: 'center',
    color: theme.label,
  },
  muted: {
    fontSize: 15,
    textAlign: 'center',
    color: theme.secondary,
  },
  primary: {
    borderRadius: 14,
    backgroundColor: theme.blue,
    padding: 16,
    alignItems: 'center',
    width: '100%',
    maxWidth: 320,
  },
  primaryTxt: {
    color: '#fff',
    fontSize: 18,
    fontWeight: '600',
  },
  ghost: {
    padding: 14,
    alignItems: 'center',
  },
  ghostTxt: {
    color: theme.blue,
    fontSize: 17,
  },
  pressed: {
    opacity: 0.7,
  },
})
