// Tela Histórico: lista das corridas salvas, com edição e exclusão.
// A edição reutiliza os pickers do formulário pós-corrida (Entradas), já
// posicionados nos valores salvos. Só lista corridas reais — os dados
// sintéticos de dev da tela Resultados não existem no armazenamento.

import React, { useRef, useState } from 'react'
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native'
import { type Corrida, type Local, getCorridas, updateCorrida, removeCorrida, useStore } from '../state'
import { fmtDataHora } from '../format'
import { recalcularAutopilot } from '../autopilot'
import { WheelPicker, type WheelPickerHandle } from '../components/WheelPicker'
import { theme } from '../theme'

export function Historico(): React.JSX.Element {
  useStore()
  const [editando, setEditando] = useState<Corrida | null>(null)
  // Exclusão em dois toques no próprio botão: "Excluir" vira "Confirmar?".
  const [armado, setArmado] = useState<string | null>(null)

  if (editando) {
    return <FormEdicao key={editando.id} corrida={editando} onFechar={() => setEditando(null)} />
  }

  const corridas = [...getCorridas()].sort((a, b) => b.inicio.localeCompare(a.inicio))
  if (corridas.length === 0) {
    return (
      <View style={styles.empty}>
        <Text style={styles.muted}>Nenhuma corrida ainda.</Text>
        <Text style={[styles.muted, styles.center]}>
          Vá em <Text style={styles.strong}>Entradas</Text> e toque em <Text style={styles.italic}>Comecei</Text> quando
          sair pra correr.
        </Text>
      </View>
    )
  }

  return (
    <ScrollView contentContainerStyle={styles.lista}>
      {corridas.map((c) => (
        <View key={c.id} style={styles.card}>
          <View style={styles.lrTop}>
            <Text style={styles.lrDate}>{fmtDataHora(c.inicio)}</Text>
            <Text style={styles.tag}>{c.local === 'esteira' ? 'Esteira' : 'Externo'}</Text>
          </View>
          <View style={styles.lrStats}>
            <View style={styles.lrStat}>
              <Text style={styles.big}>{c.duracaoMin}</Text>
              <Text style={styles.statLabel}>min</Text>
            </View>
            <View style={styles.lrStat}>
              <Text style={styles.big}>{c.distanciaKm ? c.distanciaKm.toFixed(1) : '—'}</Text>
              <Text style={styles.statLabel}>km</Text>
            </View>
          </View>
          <View style={styles.actions}>
            <Pressable
              style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]}
              onPress={() => setEditando(c)}
            >
              <Text style={styles.ghostTxt}>Editar</Text>
            </Pressable>
            <Pressable
              style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]}
              onPress={() => {
                if (armado === c.id) {
                  removeCorrida(c.id)
                  recalcularAutopilot()
                  setArmado(null)
                  return
                }
                setArmado(c.id)
              }}
            >
              <Text style={[styles.ghostTxt, styles.dangerTxt]}>{armado === c.id ? 'Confirmar?' : 'Excluir'}</Text>
            </Pressable>
          </View>
        </View>
      ))}
    </ScrollView>
  )
}

function FormEdicao({ corrida: c, onFechar }: { corrida: Corrida; onFechar: () => void }): React.JSX.Element {
  const km = Math.floor(c.distanciaKm ?? 0)
  const m = Math.round(((c.distanciaKm ?? 0) - km) * 10) * 100 // 0.1 km -> 100 m

  const [formLocal, setFormLocal] = useState<Local>(c.local)
  const minRef = useRef<WheelPickerHandle>(null)
  const kmRef = useRef<WheelPickerHandle>(null)
  const mRef = useRef<WheelPickerHandle>(null)

  const salvar = (): void => {
    const duracaoMin = minRef.current?.getValue() ?? c.duracaoMin
    const dist = (kmRef.current?.getValue() ?? 0) + (mRef.current?.getValue() ?? 0) / 1000
    // Duração muda -> o fim acompanha (início é fixo: é quando a corrida aconteceu).
    const fim = new Date(new Date(c.inicio).getTime() + duracaoMin * 60000).toISOString()
    updateCorrida(c.id, {
      duracaoMin,
      fim,
      local: formLocal,
      distanciaKm: dist > 0 ? Math.round(dist * 10) / 10 : undefined,
    })
    recalcularAutopilot()
    onFechar()
  }

  return (
    <ScrollView keyboardShouldPersistTaps="handled">
      <View style={styles.cardForm}>
        <View style={styles.row}>
          <Text style={styles.muted}>Quando</Text>
          <Text style={styles.strong}>{fmtDataHora(c.inicio)}</Text>
        </View>
        <WheelPicker ref={minRef} min={1} max={60} step={1} def={c.duracaoMin} label="Duração" unit="min" />
        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Distância — 0 km apaga o valor</Text>
          <View style={styles.pickerRow}>
            <View style={styles.pickerCell}>
              <WheelPicker ref={kmRef} min={0} max={30} step={1} def={km} label="km" unit="km" />
            </View>
            <View style={styles.pickerCell}>
              <WheelPicker ref={mRef} min={0} max={900} step={100} def={m} label="metros" unit="m" />
            </View>
          </View>
        </View>
        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Onde</Text>
          <View style={styles.seg}>
            <Pressable
              style={[styles.segBtn, formLocal === 'externo' && styles.segBtnOn]}
              onPress={() => setFormLocal('externo')}
            >
              <Text style={[styles.segTxt, formLocal === 'externo' && styles.segTxtOn]}>Externo</Text>
            </Pressable>
            <Pressable
              style={[styles.segBtn, formLocal === 'esteira' && styles.segBtnOn]}
              onPress={() => setFormLocal('esteira')}
            >
              <Text style={[styles.segTxt, formLocal === 'esteira' && styles.segTxtOn]}>Esteira</Text>
            </Pressable>
          </View>
        </View>
        <View style={styles.actions}>
          <Pressable style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]} onPress={onFechar}>
            <Text style={styles.ghostTxt}>Cancelar</Text>
          </Pressable>
          <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={salvar}>
            <Text style={styles.primaryTxt}>Salvar</Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  )
}

