// Tela Energia: um "rolo" de frases motivacionais, aberto pelo ⚡ da topbar.
// As faces do rolo ficam embaçadas; o botão aplica um torque aleatório, a
// fricção desacelera o giro e o borrão cai junto com a velocidade — primeiro
// de todas as faces, até um piso, e daí em diante só da face sorteada. Parado,
// a frase sorteada fica nítida e desliza da direita para a esquerda em loop.
//
// O tambor é projetado em 2D (translateY/scaleY por face) porque o RN não
// tem preserve-3d: com o borrão por cima, a ilusão de cilindro se mantém.

import React, { useEffect, useRef, useState } from 'react'
import { Pressable, StyleSheet, Text, View } from 'react-native'
import { theme } from '../theme'

const FRASES = [
  'Hoje é um bom dia para (re)começar.',
  'Constância vence intensidade.',
  'Um passo de cada vez.',
  'Seu corpo agradece cada movimento.',
  'Devagar também é progresso.',
  'A energia aparece quando você se move.',
  'Você já venceu só por estar aqui.',
  'Respire. Corra. Sorria.',
  // Famosas, de atletas e pensadores (fontes: Pensador e Atletis).
  'O sucesso não acontece por acaso. — Pelé',
  'Não tenha medo de falhar: é o caminho para o sucesso. — LeBron James',
  'Você perde 100% das oportunidades que não aproveita. — Wayne Gretzky',
  'Não sonhe em vencer, treine para isso! — Mo Farah',
  'O milagre não é ter terminado; é ter tido coragem de começar. — John Bingham',
  'Corra quando puder, caminhe se precisar, mas nunca desista. — Dean Karnazes',
  'Sempre há limites. Eu não conheço os meus. — Usain Bolt',
  'O que parece difícil agora um dia será seu aquecimento.',
]

const N = FRASES.length
const PASSO = 360 / N // graus entre faces
const RAIO_PX = 184 // raio visual do cilindro, em px

// Física do giro
const TORQUE_MIN = 720 // graus/s (2 voltas/s)
const TORQUE_MAX = 1440 // 4 voltas/s
const FRICCAO = 0.9 // decaimento exponencial: v *= e^(-FRICCAO*dt)
const V_ENCAIXE = 24 // abaixo disso, encaixa na face mais próxima
const V_BLUR_CHEIO = 300 // velocidade em que o borrão satura
const BLUR_MAX = 6
const BLUR_FOCO = 3 // piso do borrão das faces não sorteadas
const MARQUEE_PX_S = 60
const MARQUEE_GAP = 40 // respiro entre o fim e o recomeço do texto

type Fase = 'parado' | 'girando' | 'encaixando' | 'rolando'

interface Fis {
  angulo: number
  v: number
  fase: Fase
  marqueeX: number
  alvo: number
  textoW: number
  janelaW: number
}

export function Energia(): React.JSX.Element {
  const fis = useRef<Fis>({
    angulo: 0,
    v: 0,
    fase: 'parado',
    marqueeX: 0,
    alvo: 0,
    textoW: 0,
    janelaW: 0,
  })
  const [, setTick] = useState(0)

  useEffect(() => {
    let raf = 0
    let ultimo = performance.now()
    const tick = (agora: number): void => {
      const dt = Math.min((agora - ultimo) / 1000, 0.05)
      ultimo = agora
      const f = fis.current
      if (f.fase === 'girando') {
        f.v *= Math.exp(-FRICCAO * dt)
        f.angulo += f.v * dt
        if (f.v < V_ENCAIXE) {
          f.fase = 'encaixando'
          f.alvo = Math.round(f.angulo / PASSO) * PASSO
        }
      } else if (f.fase === 'encaixando') {
        const d = f.alvo - f.angulo
        f.angulo += d * Math.min(1, dt * 10)
        if (Math.abs(d) < 0.15) {
          f.angulo = f.alvo
          f.v = 0
          f.fase = 'rolando'
          f.marqueeX = 0
          f.textoW = 0 // força remedição da frase sorteada (onLayout da cópia 0)
        }
      } else if (f.fase === 'rolando' && f.textoW > 0) {
        // Da direita para a esquerda: o texto entra pela borda direita e a
        // volta fecha quando a primeira cópia sai inteira pela esquerda.
        f.marqueeX += MARQUEE_PX_S * dt
        const ciclo = f.textoW + MARQUEE_GAP
        if (f.marqueeX >= f.janelaW + ciclo) f.marqueeX -= ciclo
      }
      if (f.fase !== 'parado') setTick((t) => t + 1) // parado nada muda: poupa re-render
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [])

  const f = fis.current
  const girando = f.fase === 'girando' || f.fase === 'encaixando'
  // Nunca girou: tudo borrado. Girando: borrão proporcional à velocidade,
  // com piso BLUR_FOCO para as não sorteadas; só a sorteada zera o borrão.
  const base = Math.min(BLUR_MAX, (Math.abs(f.v) / V_BLUR_CHEIO) * BLUR_MAX)
  const vencedora = ((Math.round(f.angulo / PASSO) % N) + N) % N
  const blurDaFace = (i: number): number => {
    if (f.fase === 'parado') return BLUR_MAX
    if (f.fase === 'rolando') return i === vencedora ? 0 : BLUR_FOCO
    if (i !== vencedora) return Math.max(base, BLUR_FOCO)
    if (f.fase === 'encaixando') {
      const falta = Math.min(1, Math.abs(f.alvo - f.angulo) / (PASSO / 2))
      return BLUR_FOCO * falta
    }
    return base
  }

  const girar = (): void => {
    f.v = TORQUE_MIN + Math.random() * (TORQUE_MAX - TORQUE_MIN)
    f.fase = 'girando'
  }

  return (
    <View style={styles.centro}>
      <View style={styles.card}>
      <View
        style={styles.janela}
        onLayout={(e) => {
          fis.current.janelaW = e.nativeEvent.layout.width
        }}
      >
        {FRASES.map((frase, i) => {
          const rad = ((i * PASSO - f.angulo) * Math.PI) / 180
          const frente = Math.cos(rad) // 1 = face de frente, -1 = atrás
          const frontal = i === vencedora && f.fase === 'rolando'
          const blur = blurDaFace(i)
          return (
            <View
              key={frase}
              pointerEvents="none"
              style={[
                styles.face,
                {
                  // Face atrás do cilindro: oculta (num cilindro real ela
                  // estaria tapada pelas da frente).
                  opacity: frente <= 0 ? 0 : 0.2 + 0.8 * frente,
                  zIndex: Math.round(frente * 100),
                  transform: [
                    { translateY: RAIO_PX * Math.sin(rad) },
                    { scaleY: Math.max(0.05, frente) },
                  ],
                  // String CSS: o formato array [{ blur }] não é aplicado
                  // pelo react-native-web; a string funciona nas duas.
                  filter: blur > 0.05 ? `blur(${blur.toFixed(1)}px)` : undefined,
                },
              ]}
            >
              {frontal ? (
                <View style={styles.marqueeClip}>
                  <View
                    style={[
                      styles.marqueeRow,
                      { transform: [{ translateX: f.janelaW - f.marqueeX }] },
                    ]}
                  >
                    {Array.from({ length: copias(f.textoW, f.janelaW) }, (_, c) => (
                      <Text
                        key={c}
                        style={[styles.faceTxt, { marginRight: MARQUEE_GAP }]}
                        numberOfLines={1}
                        onLayout={
                          c === 0
                            ? (e) => {
                                fis.current.textoW = e.nativeEvent.layout.width
                              }
                            : undefined
                        }
                      >
                        {frase}
                      </Text>
                    ))}
                  </View>
                </View>
              ) : (
                <Text style={styles.faceTxt} numberOfLines={1}>
                  {frase}
                </Text>
              )}
            </View>
          )
        })}
      </View>
      <Pressable
        style={({ pressed }) => [styles.botao, (pressed || girando) && styles.botaoOff]}
        disabled={girando}
        onPress={girar}
      >
        <Text style={styles.botaoTxt}>Libere a energia da motivação diária!</Text>
      </Pressable>
      </View>
    </View>
  )
}

// Cópias lado a lado para o loop ficar contínuo: bastam para cobrir a janela
// inteira mais uma volta do texto (cada cópia ocupa texto + respiro).
function copias(textoW: number, janelaW: number): number {
  if (textoW <= 0) return 3
  const ciclo = textoW + MARQUEE_GAP
  return Math.max(2, Math.ceil((janelaW + ciclo) / ciclo))
}

const styles = StyleSheet.create({
  centro: {
    flex: 1,
    justifyContent: 'center',
  },
  card: {
    backgroundColor: theme.card,
    borderRadius: 14,
    padding: 16,
    gap: 16,
  },
  janela: {
    height: RAIO_PX * 2 + 48,
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
    borderRadius: 12,
    backgroundColor: 'rgba(255, 204, 0, 0.08)',
  },
  face: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 44,
    alignItems: 'center',
    justifyContent: 'center',
  },
  faceTxt: {
    fontSize: 20,
    fontWeight: '600',
    color: theme.label,
  },
  marqueeClip: {
    position: 'absolute',
    top: 0,
    bottom: 0,
    left: 0,
    right: 0,
    overflow: 'hidden',
    justifyContent: 'center',
  },
  marqueeRow: {
    flexDirection: 'row',
    alignItems: 'center',
    alignSelf: 'flex-start',
  },
  botao: {
    backgroundColor: theme.blue,
    borderRadius: 999,
    paddingVertical: 16,
    alignItems: 'center',
  },
  botaoOff: {
    opacity: 0.6,
  },
  botaoTxt: {
    color: '#fff',
    fontSize: 17,
    fontWeight: '600',
  },
})
