// Barra de status do modelo local (parte baixa do shell, acima da tabbar):
// mostra o andamento do download e da carga do Gemma. Some quando o modelo
// fica pronto — o resto do app não precisa saber de onde a resposta veio.

import React, { useSyncExternalStore } from 'react'
import { StyleSheet, Text, View } from 'react-native'
import { estadoModeloLocal, subscreverModeloLocal } from '../modelo_local'
import { theme } from '../theme'

export function BarraModelo(): React.JSX.Element | null {
  useSyncExternalStore(subscreverModeloLocal, estadoModeloLocal)
  const { fase, progresso, erro } = estadoModeloLocal()

  const texto =
    fase === 'baixando'
      ? `Baixando modelo local do treinador (pode continuar usando)… ${Math.round(progresso * 100)}%`
      : fase === 'carregando'
        ? 'Preparando modelo local do treinador…'
        : fase === 'aguardando_wifi'
          ? 'Aguardando Wi-Fi para baixar o modelo local do treinador…'
          : fase === 'bloqueado'
            ? 'Modelo local bloqueado neste aparelho (o sistema interrompeu uma tentativa anterior)'
            : erro != null
              ? `Modelo local: ${erro}`
              : null

  if (texto == null) return null

  return (
    <View style={styles.barra}>
      <Text style={styles.texto}>{texto}</Text>
      <View
        style={[
          styles.trilha,
          {
            width:
              fase === 'carregando'
                ? '100%'
                : fase === 'baixando'
                  ? `${Math.max(4, Math.round(progresso * 100))}%`
                  : 0,
          },
        ]}
      />
    </View>
  )
}

const styles = StyleSheet.create({
  barra: {
    overflow: 'hidden',
    marginHorizontal: 16,
    marginBottom: 6,
    paddingVertical: 6,
    paddingHorizontal: 12,
    borderRadius: 10,
    backgroundColor: 'rgba(0, 122, 255, 0.1)',
  },
  texto: {
    fontSize: 12,
    color: theme.label,
  },
  trilha: {
    position: 'absolute',
    bottom: 0,
    left: 0,
    height: 2,
    backgroundColor: theme.blue,
  },
})
