// GPS da corrida em curso: as posições chegam a cada ~5 m percorridos
// (distanceInterval) e a distância é a soma dos segmentos (haversine),
// então curvas e voltas contam corretamente. Filtros de qualidade:
// descarta pontos com incerteza > 25 m e "saltos" cuja velocidade implicada
// supere o dobro da média das tomadas anteriores — com piso (pra não travar
// com média ~0 no início) e reset por sequência de descartes (pra acompanhar
// quando o ritmo muda de verdade, ex.: caminhada → corrida).
//
// A distância acumulada é gravada na corrida em curso (cl_em_curso) a cada
// ponto aceito: fechar o app não perde o percurso — na retomada a contagem
// continua de onde parou (iniciarGps recebe a distância salva).
//
// Background (nativo, fora do Expo Go): a medição roda na task TASK_GPS
// (expo-task-manager) e continua com a tela apagada ou o app em 2º plano.
// Basta a permissão "Durante o uso": a task sobe com o app aberto (toque no
// Comecei ou retomada); o expo-location só exige "Sempre" pra iniciá-la com o
// app já em 2º plano. Se o usuário matar o app, o sistema encerra a task — o
// trecho não é medido e a retomada acontece na próxima abertura. No Expo Go
// (sem background) e na web, cai no watchPosition de foreground.
//
// Permissão: este módulo NUNCA abre o prompt do sistema — quem pede é a tela
// PermissaoGps (1ª abertura do app), o link "aqui" da tela Entradas ou o
// botão Comecei (background), via pedirPermissaoGps/pedirPermissaoGpsBackground.
// iniciarGps só consulta; sem permissão, não mede.

import { Platform } from 'react-native'
import * as Location from 'expo-location'
import * as TaskManager from 'expo-task-manager'
import { getCorridaEmCurso, setCorridaEmCurso } from './state'

/** Amostragem por deslocamento: um ponto novo a cada ~5 m. */
const DIST_INTERVAL_M = 5
/** Descarta pontos cuja incerteza (raio) supere isto. */
const ACCURACY_MAX_M = 25
/** Piso do limiar de velocidade (km/h): evita travar com média ~0 no início. */
const VEL_PISO_KMH = 3
/** Descartes seguidos que indicam mudança real de ritmo → reseta a média. */
const MAX_DESCARTES = 5

/** Nome da task de localização em background (expo-task-manager). */
const TASK_GPS = 'cl-gps-corrida'

interface Ponto {
  lat: number
  lon: number
  t: number // ms (epoch)
}

let watcher: Location.LocationSubscription | null = null
let ultima: Ponto | null = null
let metros = 0
let velocidades: number[] = [] // km/h das tomadas aceitas
let descartes = 0
let disponivel = false // true a partir da primeira posição recebida

/** Distância em metros entre dois pontos (fórmula de haversine). */
function haversine(a: Ponto, b: Ponto): number {
  const R = 6371000 // raio médio da Terra, em metros
  const dLat = ((b.lat - a.lat) * Math.PI) / 180
  const dLon = ((b.lon - a.lon) * Math.PI) / 180
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((a.lat * Math.PI) / 180) * Math.cos((b.lat * Math.PI) / 180) * Math.sin(dLon / 2) ** 2
  return 2 * R * Math.asin(Math.sqrt(h))
}

/** Grava a distância acumulada na corrida em curso: fechar o app no meio da
 *  corrida não perde o percurso já medido. */
function persistirDistancia(): void {
  const emCurso = getCorridaEmCurso()
  if (!emCurso) return
  setCorridaEmCurso({ ...emCurso, distanciaKm: Math.round(metros) / 1000 })
}

function aoReceber(pos: Location.LocationObject): void {
  const { latitude, longitude, accuracy } = pos.coords
  if (accuracy !== null && accuracy > ACCURACY_MAX_M) return
  const p: Ponto = { lat: latitude, lon: longitude, t: pos.timestamp }
  if (ultima) {
    const d = haversine(ultima, p)
    const dt = (p.t - ultima.t) / 1000
    if (dt <= 0) return
    const v = (d / dt) * 3.6 // km/h
    if (velocidades.length > 0) {
      const media = velocidades.reduce((a, b) => a + b, 0) / velocidades.length
      if (v > Math.max(2 * media, VEL_PISO_KMH)) {
        descartes += 1
        if (descartes < MAX_DESCARTES) return // salto: ignora o ponto
        // ritmo mudou de verdade — aceita e recomeça a média
        velocidades = []
        descartes = 0
      } else {
        descartes = 0
      }
    }
    velocidades.push(v)
    metros += d
    persistirDistancia()
  }
  ultima = p
  disponivel = true
}

// Task de background: definida no escopo global do bundle, como a doc do
// expo-task-manager exige (quando o sistema acorda o app em 2º plano, nenhuma
// view está montada). Recebe os mesmos pontos do watchPosition e passa pelo
// mesmo filtro. Na web o TaskManager não existe — o defineTask nem é chamado.
if (Platform.OS !== 'web') {
  TaskManager.defineTask<{ locations: Location.LocationObject[] }>(TASK_GPS, async ({ data, error }) => {
    if (error) return
    // Sem corrida em curso a task não deveria estar viva: encerra sozinha.
    if (!getCorridaEmCurso()) {
      await Location.stopLocationUpdatesAsync(TASK_GPS).catch(() => {})
      return
    }
    for (const pos of data.locations) aoReceber(pos)
  })
}

/** Só consulta a permissão de foreground (nunca abre o prompt do sistema). */
export async function consultarPermissaoGps(): Promise<boolean> {
  try {
    const { status } = await Location.getForegroundPermissionsAsync()
    return status === 'granted'
  } catch {
    return false // navegador antigo sem navigator.permissions, ou sem geolocalização
  }
}

/** Abre o prompt do sistema de foreground. 'denied' = já negado antes — o
 *  sistema não reexibe o prompt, e a UI deve orientar o usuário a ir nas
 *  configurações. */
export async function pedirPermissaoGps(): Promise<'granted' | 'denied' | 'erro'> {
  try {
    const { status } = await Location.requestForegroundPermissionsAsync()
    return status === 'granted' ? 'granted' : 'denied'
  } catch {
    return 'erro'
  }
}

/** Abre o prompt de background ("Sempre", no iOS). Só faz sentido com a de
 *  foreground já concedida; chamar a partir de um gesto do usuário. */
export async function pedirPermissaoGpsBackground(): Promise<'granted' | 'denied' | 'erro'> {
  try {
    const { status } = await Location.requestBackgroundPermissionsAsync()
    return status === 'granted' ? 'granted' : 'denied'
  } catch {
    return 'erro'
  }
}

/** Nativo: sobe a task de background (basta "Durante o uso" — ver o cabeçalho).
 *  Exigir "Sempre" aqui fazia cair no watchPosition, que para ao apagar a tela:
 *  a corrida de 3 km media ~1 km. No Expo Go (sem background) a task falha e
 *  cai no watchPosition de foreground. */
async function iniciarNativo(): Promise<void> {
  try {
    if (!(await Location.hasStartedLocationUpdatesAsync(TASK_GPS))) {
      await Location.startLocationUpdatesAsync(TASK_GPS, {
        accuracy: Location.Accuracy.High,
        distanceInterval: DIST_INTERVAL_M,
        // iOS: faixa azul na status bar enquanto mede em 2º plano; ritmo de
        // corrida não deve pausar as atualizações automaticamente.
        showsBackgroundLocationIndicator: true,
        pausesUpdatesAutomatically: false,
        activityType: Location.ActivityType.Fitness,
        // Android: o serviço de 1º plano exige notificação visível.
        foregroundService: {
          notificationTitle: 'Corrida Leve',
          notificationBody: 'Medindo a distância da sua corrida.',
        },
      })
    }
    return
  } catch {
    // Expo Go / build sem a capability: cai no foreground abaixo
  }
  watcher = await Location.watchPositionAsync(
    { accuracy: Location.Accuracy.High, distanceInterval: DIST_INTERVAL_M },
    aoReceber,
  )
}

/** Começa a medir: se a permissão já estiver concedida (decidida na abertura
 *  do app ou no link da tela Entradas), assina as atualizações de posição.
 *  Sem permissão, não mede — e nunca abre o prompt do sistema aqui.
 *  `distanciaInicialKm` restaura a distância persistida numa retomada (o app
 *  foi fechado no meio da corrida). */
export async function iniciarGps(distanciaInicialKm?: number): Promise<void> {
  watcher?.remove()
  watcher = null
  ultima = null
  metros = (distanciaInicialKm ?? 0) * 1000
  velocidades = []
  descartes = 0
  disponivel = false
  try {
    if (!(await consultarPermissaoGps())) return
    // Na web o expo-location repassa as opções cruas pro
    // navigator.geolocation.watchPosition, que ignora accuracy/distanceInterval
    // e usa enableHighAccuracy: false por padrão — posições grosseiras demais,
    // todas descartadas pelo filtro de incerteza. Daí o enableHighAccuracy.
    if (Platform.OS === 'web') {
      watcher = await Location.watchPositionAsync(
        { enableHighAccuracy: true } as Location.LocationOptions,
        aoReceber,
      )
      return
    }
    await iniciarNativo()
  } catch {
    // web/navegador sem geolocalização
  }
}

/** Distância acumulada até agora (km), ou null se o GPS não está disponível
 *  e não há distância restaurada de uma sessão anterior. */
export function distanciaEmCurso(): number | null {
  return disponivel || metros > 0 ? metros / 1000 : null
}

/** Encerra a medição (foreground e background) e devolve a distância total
 *  em km, ou null se nada foi medido. */
export async function pararGps(): Promise<number | null> {
  watcher?.remove()
  watcher = null
  if (Platform.OS !== 'web') {
    try {
      if (await Location.hasStartedLocationUpdatesAsync(TASK_GPS)) {
        await Location.stopLocationUpdatesAsync(TASK_GPS)
      }
    } catch {
      // sem a capability neste build
    }
  }
  return disponivel || metros > 0 ? metros / 1000 : null
}
