// Caixa de seleção simples (o RN não tem checkbox nativo): quadrado com
// preenchimento azul + ✓ quando marcado, rótulo ao lado. Usada nos
// formulários de medição (onboarding e aba Saúde) como "registrar".

import React from 'react'
import { Pressable, StyleSheet, Text, View } from 'react-native'
import { theme } from '../theme'

export function Checkbox({
  rotulo,
  marcado,
  onToggle,
}: {
  rotulo: string
  marcado: boolean
  onToggle: () => void
}): React.JSX.Element {
  return (
    <Pressable
      style={({ pressed }) => [styles.linha, pressed && styles.pressed]}
      onPress={onToggle}
      accessibilityRole="checkbox"
      accessibilityState={{ checked: marcado }}
    >
      <View style={[styles.caixa, marcado && styles.caixaOn]}>{marcado ? <Text style={styles.check}>✓</Text> : null}</View>
      <Text style={styles.rotulo}>{rotulo}</Text>
    </Pressable>
  )
}

const styles = StyleSheet.create({
  linha: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 6,
  },
  caixa: {
    width: 20,
    height: 20,
    borderRadius: 6,
    borderWidth: 1.5,
    borderColor: theme.separator,
    backgroundColor: theme.bg,
    alignItems: 'center',
    justifyContent: 'center',
  },
  caixaOn: {
    backgroundColor: theme.blue,
    borderColor: theme.blue,
  },
  check: {
    color: '#fff',
    fontSize: 13,
    fontWeight: '700',
    lineHeight: 15,
  },
  rotulo: {
    fontSize: 14,
    color: theme.secondary,
  },
  pressed: {
    opacity: 0.6,
  },
})
