// Autopilot State (milestone 4, set/2026): a fotografia persistida do ciclo
// de decisão (`cl_autopilot`, via state.ts). Até o milestone 3, nível e
// decisão eram recalculados sob demanda a cada leitura; aqui passam a ter
// um lugar no estado para que o plano vigente seja estável entre telas e
// reaberturas do app — é desta fotografia que o "Hoje" (milestone 5) vai ler.
//
// O que fica aqui: nível atual, próximo nível, próxima atividade, plano da
// semana e o progresso observado no momento do cálculo. Compromissos e
// histórico de feedback já moram na parte declarada do User Model
// (`cl_modelo_usuario`) — o Autopilot os lê de lá, sem duplicar.
//
// Quem recalcula: o boot do app e cada mutação que muda a decisão (corrida
// registrada/editada/removida, User Model salvo). A escrita só acontece
// quando o conteúdo muda, para não notificar o store à toa.

import { getAutopilot, setAvisoTreinador, setAutopilot } from './state'
import { type SinaisObservados, montarModeloCompleto, ultimoFeedback } from './usuario'
import { type Nivel, avaliarNivel } from './niveis'
import { type Decisao, type TipoAtividade, decidir } from './decisao'

/** Uma sessão prescrita para a semana vigente. */
export interface SessaoPlanejada {
  atividade: TipoAtividade
  duracaoMin: number
  intensidade: string
}

/** Fotografia do ciclo de decisão vigente do Autopilot. */
export interface EstadoAutopilot {
  nivel: Nivel
  proximo: Nivel | null // null no topo da escala
  motivo: string // o porquê do posicionamento (da avaliação de nível)
  bloqueado: boolean // true = o plano mantém sem progredir
  proximaAtividade: Decisao
  planoSemana: SessaoPlanejada[]
  progressoObservado: SinaisObservados
  atualizadoEm: string // ISO
}

/** Calcula o estado a partir do User Model completo. Função pura (não grava). */
export function calcularAutopilot(): EstadoAutopilot {
  const modelo = montarModeloCompleto()
  const avaliacao = avaliarNivel(modelo.sinais, ultimoFeedback(modelo), modelo.situacaoDeclarada)
  const proximaAtividade = decidir(modelo, avaliacao)
  // Plano da semana v1: sessões uniformes — a prescrição repetida na
  // frequência semanal. Distribuir dias e horários é do milestone 7.
  const sessao: SessaoPlanejada = {
    atividade: proximaAtividade.atividade,
    duracaoMin: proximaAtividade.duracaoMin,
    intensidade: proximaAtividade.intensidade,
  }
  return {
    nivel: avaliacao.nivel,
    proximo: avaliacao.proximo,
    motivo: avaliacao.motivo,
    bloqueado: avaliacao.bloqueado,
    proximaAtividade,
    planoSemana: Array.from({ length: proximaAtividade.frequenciaSemanal }, () => ({ ...sessao })),
    progressoObservado: modelo.sinais,
    atualizadoEm: new Date().toISOString(),
  }
}

/**
 * Recalcula e grava o estado do Autopilot — mas só escreve quando o conteúdo
 * muda (a comparação ignora `atualizadoEm`), para não notificar o store à toa.
 * Subida de nível marca o aviso 'meta' (o treinador celebra e define a próxima
 * linha de chegada); outra mudança material da prescrição (atividade, duração
 * ou frequência — inclui regressão de nível) marca 'plano'.
 */
export function recalcularAutopilot(): EstadoAutopilot {
  const atual = calcularAutopilot()
  const anterior = getAutopilot()
  const semData = ({ atualizadoEm: _, ...resto }: EstadoAutopilot): unknown => resto
  if (anterior == null || JSON.stringify(semData(anterior)) !== JSON.stringify(semData(atual))) {
    if (anterior != null) {
      if (atual.nivel > anterior.nivel) {
        setAvisoTreinador('meta')
      } else if (
        anterior.nivel !== atual.nivel ||
        anterior.proximaAtividade.atividade !== atual.proximaAtividade.atividade ||
        anterior.proximaAtividade.duracaoMin !== atual.proximaAtividade.duracaoMin ||
        anterior.proximaAtividade.frequenciaSemanal !== atual.proximaAtividade.frequenciaSemanal
      ) {
        setAvisoTreinador('plano')
      }
    }
    setAutopilot(atual)
  }
  return atual
}
