// Cartão do objetivo do plano (3 km em 20 min — state.ts: OBJETIVO): mostra
// onde o usuário está no caminho até a linha de chegada.
//
//   etapa 1 — sustentar os 20 min de atividade;
//   etapa 2 — dentro dos 20 min, ir controlando a distância até chegar aos
//             3 km (barra com a melhor marca até agora).
//
// Quando uma sessão fecha os 3 km em 20 min, o cartão vira a celebração com a
// data da conquista. Quem calcula é state.ts (atingiuObjetivo /
// progressoObjetivo); aqui só se desenha o resultado.

import React from 'react'
import { StyleSheet, Text, View } from 'react-native'
import { type Corrida, OBJETIVO, atingiuObjetivo, progressoObjetivo } from '../state'
import { fmtData } from '../format'
import { theme } from '../theme'

export function CartaoObjetivo({ corridas }: { corridas: Corrida[] }): React.JSX.Element {
  const conquista = atingiuObjetivo(corridas)
  const { sustenta20Min, melhorKm } = progressoObjetivo(corridas)
  const fracao = melhorKm != null ? Math.min(1, melhorKm / OBJETIVO.distanciaKm) : 0
  const pct = Math.round(fracao * 100)

  return (
    <View style={styles.card}>
      <Text style={styles.titulo}>
        Objetivo: {OBJETIVO.distanciaKm} km em {OBJETIVO.duracaoMin} min
      </Text>
      {conquista != null ? (
        <>
          <Text style={styles.conquista}>🏁 Objetivo atingido!</Text>
          <Text style={styles.muted}>
            Você percorreu {conquista.distanciaKm} km em {conquista.duracaoMin} min em{' '}
            {fmtData(conquista.inicio)}.
          </Text>
        </>
      ) : (
        <>
          <Text style={styles.muted}>
            {sustenta20Min
              ? `✓ Etapa 1: você já sustenta ${OBJETIVO.duracaoMin} min de atividade.`
              : `Etapa 1: chegar aos ${OBJETIVO.duracaoMin} min de atividade.`}
          </Text>
          <Text style={styles.muted}>
            Etapa 2: dentro dos {OBJETIVO.duracaoMin} min, percorrer {OBJETIVO.distanciaKm} km.
          </Text>
          {melhorKm != null ? (
            <>
              <View style={styles.trilho}>
                <View style={[styles.preenchimento, { width: `${pct}%` }]} />
              </View>
              <Text style={styles.muted}>
                Seu melhor: <Text style={styles.destaque}>{melhorKm.toFixed(1)} km</Text> de{' '}
                {OBJETIVO.distanciaKm} km ({pct}%)
              </Text>
            </>
          ) : (
            <Text style={styles.muted}>Registre a distância das suas sessões pra acompanhar.</Text>
          )}
        </>
      )}
    </View>
  )
}

const styles = StyleSheet.create({
  card: {
    backgroundColor: theme.card,
    borderRadius: 14,
    padding: 16,
    gap: 6,
  },
  titulo: {
    fontSize: 15,
    fontWeight: '700',
    color: theme.label,
  },
  conquista: {
    fontSize: 17,
    fontWeight: '600',
    color: theme.label,
  },
  destaque: {
    fontWeight: '600',
    color: theme.label,
  },
  muted: {
    fontSize: 15,
    color: theme.secondary,
  },
  trilho: {
    height: 8,
    borderRadius: 4,
    backgroundColor: 'rgba(60, 60, 67, 0.1)',
    overflow: 'hidden',
    marginVertical: 4,
  },
  preenchimento: {
    height: 8,
    borderRadius: 4,
    backgroundColor: theme.dist,
  },
})
