// User Model (milestone 1, set/2026): representa a relação da pessoa com a
// atividade física — capacidade e consistência, não performance. É a base do
// Autopilot: o Decision Engine (milestone 3) decide a partir daqui.
//
// O modelo tem duas partes:
//
//   declarada — o que a pessoa contou sobre si (persistida em
//               `cl_modelo_usuario`, via state.ts). É uma hipótese inicial;
//               as atividades realizadas permitem refiná-la.
//   derivada  — sinais observados nas corridas registradas, recalculados
//               sob demanda (não se persistem: derivam do histórico).
//
// Tipos definidos aqui antes dos próprios mecanismos: a coleta de feedback
// pós-sessão (milestone 6) vive em Entradas.tsx e a gestão de compromissos
// (milestone 7) em compromissos.ts.

import { type Corrida, OBJETIVO, diasTreinados, getCorridas, getModeloUsuario } from './state'

export type SituacaoAtual =
  | 'sedentario'
  | 'caminha_as_vezes'
  | 'caminha_regularmente'
  | 'corre_as_vezes'
  | 'corre_regularmente'

export const SITUACOES: { valor: SituacaoAtual; rotulo: string }[] = [
  { valor: 'sedentario', rotulo: 'Sedentário' },
  { valor: 'caminha_as_vezes', rotulo: 'Caminho às vezes' },
  { valor: 'caminha_regularmente', rotulo: 'Caminho regularmente' },
  { valor: 'corre_as_vezes', rotulo: 'Corro às vezes' },
  { valor: 'corre_regularmente', rotulo: 'Corro regularmente' },
]

/** Resposta subjetiva a uma sessão — o que os sensores não captam. */
export type FeedbackSessao = 'leve' | 'normal' | 'dificil'

export interface FeedbackRegistrado {
  corridaId: string
  feedback: FeedbackSessao
  quando: string // ISO
}

/** Quanto tempo e com que frequência a pessoa consegue treinar. */
export interface Disponibilidade {
  sessoesPorSemana: number
  minutosPorSessao: number
  diasSemana?: number[] // 0=domingo…6=sábado; [] ou ausente = sem preferência
  horaPreferida?: number // 0–23 (fração = minutos); ausente = sem preferência
}

export type StatusCompromisso = 'proposto' | 'combinado' | 'cumprido' | 'perdido' | 'cancelado'

/** Compromisso com o treinador: "combinamos caminhada quinta às 18h". */
export interface Compromisso {
  id: string
  atividade: string // 'caminhada', 'caminhada rápida', 'corrida/caminhada', 'corrida', 'esteira'
  quando: string // ISO com a data e a hora combinadas
  duracaoMin: number
  status: StatusCompromisso
  desfecho?: string // o que aconteceu (ex.: cumprido parcialmente)
  notificacaoId?: string // lembrete agendado no sistema (milestone 7), pra cancelar depois
}

/** Parte declarada/persistida do User Model. */
export interface ModeloUsuario {
  situacaoDeclarada?: SituacaoAtual
  objetivo?: string // intenção em texto livre (ex.: "voltar a me exercitar")
  disponibilidade?: Disponibilidade
  feedbacks: FeedbackRegistrado[]
  compromissos: Compromisso[]
}

/** Sinais observados no histórico recente de corridas (últimas 4 semanas). */
export interface SinaisObservados {
  sessoesPorSemana: number // dias distintos treinados por semana (média da janela)
  maiorDuracaoMin: number // duração tolerada: a maior sessão da janela
  duracaoMedianaMin: number
  semanasConsistentes: number // das últimas 4, quantas tiveram ≥ 2 dias treinados
  diasSemAtividade: number | null // null = nenhuma corrida registrada
  paceMedioMinKm?: number // só quando há distância registrada
  completouObjetivo: boolean // uma sessão de ≥ 3 km em ≤ 20 min na janela (linha de chegada, nível 4)
}

export const MODELO_USUARIO_VAZIO: ModeloUsuario = { feedbacks: [], compromissos: [] }

const JANELA_DIAS = 28

function mediana(valores: number[]): number {
  if (valores.length === 0) return 0
  const ord = [...valores].sort((a, b) => a - b)
  const meio = Math.floor(ord.length / 2)
  return ord.length % 2 ? ord[meio] : (ord[meio - 1] + ord[meio]) / 2
}

/** Deriva os sinais observados a partir do histórico de corridas. Função pura. */
export function derivarSinais(corridas: Corrida[], hoje: Date = new Date()): SinaisObservados {
  const limite = new Date(hoje)
  limite.setDate(limite.getDate() - JANELA_DIAS)
  const recentes = corridas.filter((c) => new Date(c.inicio) >= limite)

  const ultima = corridas.reduce<string | null>(
    (acc, c) => (acc === null || c.inicio > acc ? c.inicio : acc),
    null,
  )
  const diasSemAtividade =
    ultima === null
      ? null
      : Math.floor((hoje.getTime() - new Date(ultima).getTime()) / 86_400_000)

  const duracoes = recentes.map((c) => c.duracaoMin)

  // Semanas consistentes: para cada uma das últimas 4 semanas, ≥ 2 dias treinados.
  let semanasConsistentes = 0
  for (let s = 0; s < 4; s++) {
    const ini = new Date(hoje)
    ini.setDate(ini.getDate() - 7 * (s + 1))
    const fim = new Date(hoje)
    fim.setDate(fim.getDate() - 7 * s)
    const naSemana = recentes.filter((c) => {
      const d = new Date(c.inicio)
      return d >= ini && d < fim
    })
    if (diasTreinados(naSemana) >= 2) semanasConsistentes++
  }

  const comDistancia = recentes.filter((c) => c.distanciaKm != null && c.distanciaKm > 0)
  const paceMedioMinKm =
    comDistancia.length > 0
      ? comDistancia.reduce((acc, c) => acc + c.duracaoMin / c.distanciaKm!, 0) / comDistancia.length
      : undefined

  return {
    sessoesPorSemana: diasTreinados(recentes) / (JANELA_DIAS / 7),
    maiorDuracaoMin: duracoes.length > 0 ? Math.max(...duracoes) : 0,
    duracaoMedianaMin: mediana(duracoes),
    semanasConsistentes,
    diasSemAtividade,
    paceMedioMinKm,
    completouObjetivo: recentes.some(
      (c) => (c.distanciaKm ?? 0) >= OBJETIVO.distanciaKm && c.duracaoMin <= OBJETIVO.duracaoMin,
    ),
  }
}

/** Modelo completo: parte declarada (store) + sinais derivados do histórico. */
export function montarModeloCompleto(): ModeloUsuario & { sinais: SinaisObservados } {
  return { ...getModeloUsuario(), sinais: derivarSinais(getCorridas()) }
}

/** Feedback mais recente, se houver — entrada das regras de progressão. */
export function ultimoFeedback(m: ModeloUsuario): FeedbackSessao | undefined {
  if (m.feedbacks.length === 0) return undefined
  return m.feedbacks.reduce((a, b) => (a.quando > b.quando ? a : b)).feedback
}
