// Corrida Leve — app de auto-registro de corrida para iniciantes.
// Shell: topbar + tabbar + tela da aba corrente. Espelha o shell.ts do PWA:
// gate de onboarding, e navegação travada enquanto houver corrida em andamento.
// Antes de tudo (1ª abertura): gate do aviso pré-permissão do GPS.
// A topbar tem três toggles redondos: 👤 (Perfil, à esquerda) e ⚡ (Energia)
// e ? (Ajuda), à direita.
// Se o perfil tiver foto, ela substitui o 👤; a foto do pet aparece ao lado,
// com um 🤍 entre as duas.

import React, { useEffect, useRef, useState } from 'react'
import { Alert, AppState, Image, Pressable, StyleSheet, Text, View } from 'react-native'
import { StatusBar } from 'expo-status-bar'
import { SafeAreaProvider, SafeAreaView } from 'react-native-safe-area-context'
import { useFonts } from 'expo-font'

import {
  type AvisoTreinador,
  hydrate,
  isOnboarded,
  getAvisoTreinador,
  getPerfil,
  getGpsDecidido,
  setGpsDecidido,
  useStore,
} from './src/state'
import { recalcularAutopilot } from './src/autopilot'
import { reconciliarCompromissos } from './src/compromissos'
import { setupNotificacoes, reagendarReengajamento } from './src/notifications'
import { consultarPermissaoGps } from './src/gps'
import { type Nav, type Tab } from './src/nav'
import { telemetry } from './src/telemetry'
import { theme } from './src/theme'
import { PermissaoGps } from './src/screens/PermissaoGps'
import { Onboarding } from './src/screens/Onboarding'
import { Entradas, checarLimite, isRunning } from './src/screens/Entradas'
import { Treinador } from './src/screens/Treinador'
import { Resultados } from './src/screens/Resultados'
import { Historico } from './src/screens/Historico'
import { Marcadores } from './src/screens/Marcadores'
import { Ajuda } from './src/screens/Ajuda'
import { Energia } from './src/screens/Energia'
import { Perfil } from './src/screens/Perfil'
import { BarraModelo } from './src/components/BarraModelo'
import { iniciarModeloLocal } from './src/modelo_local'

function titulo(t: Tab): string {
  return ({
    entradas: 'Entradas',
    treinador: 'Treinador',
    resultados: 'Resultados',
    historico: 'Histórico',
    marcadores: 'Saúde',
    ajuda: 'Ajuda',
    perfil: 'Perfil',
    energia: 'Energia',
  } as const)[t]
}

const ABAS: { id: Tab; ico: string; label: string }[] = [
  { id: 'entradas', ico: '👟', label: 'Entradas' },
  { id: 'treinador', ico: '💬', label: 'Treinador' },
  { id: 'resultados', ico: '📊', label: 'Resultados' },
  { id: 'historico', ico: '📝', label: 'Histórico' },
  { id: 'marcadores', ico: '❤️', label: 'Saúde' },
]

export default function App(): React.JSX.Element | null {
  useStore() // re-renderiza o shell a cada mudança de estado
  const [ready, setReady] = useState(false)
  const [tab, setTab] = useState<Tab>('entradas')
  const [fontsLoaded] = useFonts({
    DancingScript: require('./assets/fonts/DancingScript-Bold.ttf'),
  })

  useEffect(() => {
    hydrate().then(async () => {
      // A corrida retomada pode já ter estourado os 20 min enquanto o app
      // estava fechado — nesse caso ela já vem encerrada.
      checarLimite()
      recalcularAutopilot() // fotografia do Autopilot fresca a cada abertura
      telemetry.init()
      telemetry.appOpened()
      reconciliarCompromissos() // fecha compromissos cujo dia virou (depois do init, pra telemetria pegar)
      void setupNotificacoes() // handler + canal Android dos lembretes de compromisso
      void reagendarReengajamento() // "senti sua falta" em 3 dias; reagendado a cada abertura
      // Modelo local do treinador (Gemma): download em Wi-Fi e carga rodam de
      // fundo; enquanto isso a conversa usa o DeepSeek remoto (modelo_local.ts).
      iniciarModeloLocal()
      // Permissão de GPS já concedida antes (ex.: quem permitiu numa versão
      // anterior): marca decidido e o aviso pré-permissão nunca aparece.
      if (!getGpsDecidido() && (await consultarPermissaoGps())) setGpsDecidido()
      setReady(true)
    })
  }, [])

  // Voltar ao app (segundo plano congela o setInterval): se passou dos 20 min,
  // cai no formulário. O cronômetro se reidrata sozinho pelo relógio real.
  useEffect(() => {
    const sub = AppState.addEventListener('change', (s) => {
      if (s === 'active') checarLimite()
    })
    return () => sub.remove()
  }, [])

  // Fim do onboarding: cai direto na aba Treinador, que consome o aviso
  // 'inicio' e abre a conversa propondo o primeiro combinado.
  const onboarded = isOnboarded()
  const eraOnboarded = useRef<boolean | null>(null)
  useEffect(() => {
    if (!ready) return
    if (eraOnboarded.current === false && onboarded) setTab('treinador')
    eraOnboarded.current = onboarded
  }, [ready, onboarded])

  // Aviso do treinador (compromisso perdido/cumprido, plano mudou): diálogo
  // uma vez por aviso por sessão; o OK leva à conversa, que consome o aviso.
  // Não interrompe corrida em andamento nem aparece sobre a própria aba.
  const aviso = getAvisoTreinador()
  const [avisoVisto, setAvisoVisto] = useState<AvisoTreinador | null>(null)
  useEffect(() => {
    if (!ready || !onboarded || aviso == null || aviso === avisoVisto) return
    if (tab === 'treinador' || isRunning()) return
    setAvisoVisto(aviso)
    Alert.alert('Treinador', 'Você tem uma nova mensagem do seu treinador.', [
      { text: 'OK', onPress: () => setTab('treinador') },
    ])
  }, [ready, onboarded, aviso, avisoVisto, tab])

  const nav: Nav = { go: setTab }

  if (!ready || !fontsLoaded) return null // splash nativo continua visível

  // Aviso pré-permissão do GPS: a primeira coisa que o app mostra — antes até
  // do onboarding. Só aparece uma vez; "Agora não" não volta a perguntar.
  if (!getGpsDecidido()) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.tela} edges={['top', 'bottom']}>
          <StatusBar style="dark" />
          <PermissaoGps />
        </SafeAreaView>
      </SafeAreaProvider>
    )
  }

  if (!isOnboarded()) {
    return (
      <SafeAreaProvider>
        <SafeAreaView style={styles.tela} edges={['top', 'bottom']}>
          <StatusBar style="dark" />
          <Onboarding fonteMarca="DancingScript" />
          {/* o download do modelo começa no boot — a barra tem que existir
              também durante o onboarding, antes do shell existir */}
          <BarraModelo />
        </SafeAreaView>
      </SafeAreaProvider>
    )
  }

  // Corrida em andamento: só o botão "Parei" responde — abas e "?" ficam travados.
  const travado = isRunning()
  const perfil = getPerfil()

  return (
    <SafeAreaProvider>
      <SafeAreaView style={styles.tela} edges={['top', 'bottom']}>
        <StatusBar style="dark" />
        <View style={styles.topbar}>
          <View style={styles.topbarLado}>
            <Pressable
              style={[styles.topbarFotos, travado && styles.off]}
              disabled={travado}
              onPress={() => nav.go(tab === 'perfil' ? 'entradas' : 'perfil')}
              accessibilityLabel="Perfil"
            >
              <View style={[styles.iconbtn, tab === 'perfil' && styles.iconbtnOn]}>
                {perfil?.foto ? (
                  <Image source={{ uri: perfil.foto }} style={styles.iconbtnImg} />
                ) : (
                  <Text style={styles.iconbtnTxt}>👤</Text>
                )}
              </View>
              {perfil?.fotoPet ? (
                <>
                  <Image source={{ uri: perfil.fotoPet }} style={styles.iconbtnImg} />
                  {/* Sobreposto: flutua no centro do par de fotos */}
                  <View pointerEvents="none" style={styles.topbarCoracaoBox}>
                    <Text style={styles.topbarCoracao}>🤍</Text>
                  </View>
                </>
              ) : null}
            </Pressable>
          </View>
          <Text style={styles.titulo}>{titulo(tab)}</Text>
          <View style={[styles.topbarLado, styles.topbarDir]}>
            <Pressable
              style={[styles.iconbtn, tab === 'energia' && styles.iconbtnOn, travado && styles.off]}
              disabled={travado}
              onPress={() => nav.go(tab === 'energia' ? 'entradas' : 'energia')}
              accessibilityLabel="Energia"
            >
              <Text style={styles.iconbtnTxt}>⚡</Text>
            </Pressable>
            <Pressable
              style={[styles.iconbtn, tab === 'ajuda' && styles.iconbtnOn, travado && styles.off]}
              disabled={travado}
              onPress={() => nav.go(tab === 'ajuda' ? 'entradas' : 'ajuda')}
              accessibilityLabel="Ajuda"
            >
              <Text style={styles.iconbtnTxt}>?</Text>
            </Pressable>
          </View>
        </View>

        <View style={styles.view}>
          {tab === 'entradas' ? (
            <Entradas nav={nav} />
          ) : tab === 'treinador' ? (
            <Treinador />
          ) : tab === 'resultados' ? (
            <Resultados />
          ) : tab === 'historico' ? (
            <Historico />
          ) : tab === 'perfil' ? (
            <Perfil nav={nav} />
          ) : tab === 'marcadores' ? (
            <Marcadores />
          ) : tab === 'energia' ? (
            <Energia />
          ) : (
            <Ajuda nav={nav} />
          )}
        </View>

        <BarraModelo />

        <View style={styles.tabbar}>
          {ABAS.map((a) => (
            <Pressable
              key={a.id}
              style={[styles.tabBtn, tab === a.id && styles.tabBtnOn, travado && styles.off]}
              disabled={travado}
              onPress={() => nav.go(a.id)}
            >
              <Text style={styles.tabIco}>{a.ico}</Text>
              <Text style={[styles.tabLbl, tab === a.id && styles.tabLblOn]}>{a.label}</Text>
            </Pressable>
          ))}
        </View>
      </SafeAreaView>
    </SafeAreaProvider>
  )
}

