// Dados sintéticos para desenvolvimento: ~4 meses de corridas (~3x/semana,
// horários e locais variados), pra experimentar a Progressão sem inserir
// meses de corridas reais. Usado só em `__DEV__`.
//
// Simula um iniciante progredindo rumo à meta (3 km em 20 min): duração,
// distância e ritmo começam baixos e sobem ao longo dos meses, sem nunca
// atingir a meta — quem chega lá "se formou" no programa.

import { type Corrida, type Local, type Marcador, uid } from './state'

const SPAN_DIAS = 120 // ~4 meses

export function corridasSinteticas(): Corrida[] {
  const out: Corrida[] = []
  const hoje = new Date()
  const dia = new Date(hoje)
  dia.setDate(dia.getDate() - SPAN_DIAS)
  for (let i = 0; dia <= hoje; i++, dia.setDate(dia.getDate() + 1)) {
    if (Math.random() >= 3 / 7) continue // ~3x por semana
    const prog = i / SPAN_DIAS // 0 → 1 ao longo dos 4 meses
    const inicio = new Date(dia)
    inicio.setHours(6 + Math.floor(Math.random() * 14), Math.floor(Math.random() * 60), 0, 0)
    // duração sobe de ~5 min até ~19 min (sempre abaixo dos 20 da meta)
    const duracaoMin = Math.min(19, Math.round(5 + prog * 14 + (Math.random() * 2 - 1)))
    // ritmo melhora de ~9.5 para ~7 min/km
    const ritmo = 9.5 - prog * 2.5 + (Math.random() * 0.6 - 0.3)
    // distância sobe de ~0.5 km até ~2.7 km (sempre abaixo dos 3 da meta)
    const distanciaKm = Math.min(2.9, +(duracaoMin / ritmo).toFixed(1))
    const fim = new Date(inicio.getTime() + duracaoMin * 60000)
    const local: Local = Math.random() < 0.3 ? 'esteira' : 'externo'
    out.push({
      id: uid(),
      inicio: inicio.toISOString(),
      fim: fim.toISOString(),
      duracaoMin,
      distanciaKm,
      peso: 70,
      local,
    })
  }
  return out
}

/** ~3 medições/semana por ~4 meses: peso caindo aos poucos, glicemia e
 *  pressão melhorando com a constância dos treinos. Só em `__DEV__`. */
export function marcadoresSinteticos(): Marcador[] {
  const out: Marcador[] = []
  const hoje = new Date()
  const dia = new Date(hoje)
  dia.setDate(dia.getDate() - SPAN_DIAS)
  for (let i = 0; dia <= hoje; i++, dia.setDate(dia.getDate() + 1)) {
    if (Math.random() >= 3 / 7) continue // ~3x por semana
    const prog = i / SPAN_DIAS // 0 → 1 ao longo dos 4 meses
    const quando = new Date(dia)
    quando.setHours(6 + Math.floor(Math.random() * 14), Math.floor(Math.random() * 60), 0, 0)
    out.push({
      id: uid(),
      quando: quando.toISOString(),
      // peso cai de ~82 kg para ~79 kg
      peso: Math.round(82 - prog * 3 + (Math.random() * 0.8 - 0.4)),
      glicemia: Math.round(115 - prog * 15 + (Math.random() * 30 - 15)),
      // PA melhora de ~126/83 para ~118/78 mmHg
      pressaoSis: Math.round(126 - prog * 8 + (Math.random() * 6 - 3)),
      pressaoDia: Math.round(83 - prog * 5 + (Math.random() * 4 - 2)),
    })
  }
  return out
}
