import { theme } from '../theme'

/** Teto de segurança do cronômetro quando não há duração prescrita (corrida em
 *  curso gravada antes do milestone 5). */
const LIMITE_FALLBACK_MIN = 20

/** Teto do cronômetro: a sessão encerra sozinha ao completar a duração
 *  prescrita pelo Autopilot (gravada na corrida em curso), como se o usuário
 *  tivesse tocado em "Parei". */
function limiteMs(): number {
  return (getCorridaEmCurso()?.duracaoAlvoMin ?? LIMITE_FALLBACK_MIN) * 60 * 1000
}

// A corrida em andamento e o rascunho vivem no armazenamento: fechar e reabrir
// o app retoma o cronômetro do mesmo instante de início (e o teto da duração
// prescrita continua valendo); sair antes de salvar não descarta a corrida.
// A inicialização é preguiçosa (ensureInit): o módulo é importado antes da
// hidratação do estado, então ler o cache aqui no topo daria sempre vazio.
let initialized = false
let runStart: number | null = null
let draft: Partial<Corrida> | null = null

function ensureInit(): void {
  if (initialized) return
  initialized = true
  const emCurso = getCorridaEmCurso()
  runStart = emCurso?.inicio ?? null
  draft = getRascunho()
  // Retomada com corrida em curso: religa a medição já com a distância
  // persistida — o percurso medido antes de fechar o app não se perde.
  if (runStart !== null) void iniciarGps(emCurso?.distanciaKm)
}

/** Corrida em andamento: o App trava a navegação enquanto for verdadeiro. */
export function isRunning(): boolean {
  ensureInit()
  return runStart !== null
}

/** Encerra a corrida que já passou da duração prescrita, antes de qualquer
 *  render. Cobre o app fechado/suspenso e reaberto depois do teto: volta
 *  direto no formulário. */
export function checarLimite(): void {
  ensureInit()
  if (runStart !== null && Date.now() - runStart >= limiteMs()) finalizar(runStart + limiteMs())
}

/** Zera o estado de módulo: o "Apagar tudo" da Ajuda limpa o armazenamento,
 *  mas a corrida em curso / o rascunho sobreviviam aqui na memória. */
export function resetarModulo(): void {
  runStart = null
  draft = null
  void pararGps()
}

/** Fecha a corrida e monta o rascunho do formulário. Assíncrona por causa do
 *  fix final de GPS; a trava `finalizando` impede dois encerramentos
 *  simultâneos (toque duplo no "Parei" + tick do cronômetro no limite). */
let finalizando = false
async function finalizar(fim: number): Promise<void> {
  if (finalizando) return
  finalizando = true
  const inicio = runStart!
  const metaSessao = getCorridaEmCurso()?.metaSessao
  const distGps = await pararGps()
  runStart = null
  clearCorridaEmCurso()
  draft = {
    id: uid(),
    inicio: new Date(inicio).toISOString(),
    fim: new Date(fim).toISOString(),
    duracaoMin: Math.max(1, Math.round((fim - inicio) / 60000)),
    local: 'externo',
    ...(distGps !== null ? { distanciaKm: Math.round(distGps * 100) / 100 } : {}),
    ...(metaSessao != null ? { meta: metaSessao } : {}),
  }
  setRascunho(draft)
  finalizando = false

  telemetry.runFinished(draft.duracaoMin! * 60)
}

export function Entradas({ nav }: { nav: Nav }): React.JSX.Element {
  ensureInit()
  useStore() // re-renderiza quando corrida em curso / rascunho / corridas mudam
  const [confirmacao, setConfirmacao] = useState<Corrida | null>(null)

  if (confirmacao) {
    return <Confirmacao corrida={confirmacao} onVoltar={() => setConfirmacao(null)} />
  }
  if (draft) {
    return <FormRascunho key={draft.id} draft={draft} onSalvo={setConfirmacao} />
  }
  if (runStart !== null) {
    return <Correndo inicio={runStart} alvoMin={getCorridaEmCurso()?.duracaoAlvoMin ?? LIMITE_FALLBACK_MIN} />
  }
  return <Hoje nav={nav} />
}

// --- "Hoje": a sessão prescrita pelo Autopilot + botão Comecei ---

/** Rótulo da meta da sessão: "tentar 20 min de atividade" / "tentar percorrer 3 km". */
function rotuloMeta(meta: 'tempo' | 'distancia'): string {
  return meta === 'distancia'
    ? `tentar percorrer ${OBJETIVO.distanciaKm} km`
    : `tentar ${OBJETIVO.duracaoMin} min de atividade`
}

function Hoje({ nav }: { nav: Nav }): React.JSX.Element {
  // Fotografia persistida; o cálculo puro é o fallback de quando ainda não
  // houve recálculo (ex.: estado recém-limpo) — mesmo padrão do CartaoNivel.
  const estado = getAutopilot() ?? calcularAutopilot()
  const decisao = estado.proximaAtividade
  const ultimas = getCorridas().slice(-3).reverse()
  // Permissão do GPS: null = ainda verificando (não pisca o aviso). Quem tocou
  // "Agora não" na abertura do app não é perguntado de novo — resta o link.
  const [gpsOk, setGpsOk] = useState<boolean | null>(null)
  useEffect(() => {
    void consultarPermissaoGps().then(setGpsOk)
  }, [])

  const permitirGps = async (): Promise<void> => {
    const r = await pedirPermissaoGps() // toque do usuário: o prompt do sistema é esperado aqui
    if (r === 'granted') {
      setGpsOk(true)
    } else if (r === 'denied') {
      // Já negado antes: o sistema não reexibe o prompt — só pelas configurações.
      Alert.alert(
        'Permissão negada',
        'Pra medir a distância, libere a localização do Corrida Leve nas configurações do navegador ou do aparelho.'
      )
    }
  }

  const comecar = (): void => {
    runStart = Date.now()
    setCorridaEmCurso({ inicio: runStart, duracaoAlvoMin: decisao.duracaoMin, metaSessao: decisao.metaSessao })
    // Toque do usuário: momento de contexto pra pedir a localização "Sempre"
    // (medir com a tela apagada). Negada, a medição segue em foreground.
    void pedirPermissaoGpsBackground()
    void iniciarGps() // mede a distância durante a corrida, se disponível

    telemetry.runStarted(decisao.atividade, decisao.duracaoMin)
    // setCorridaEmCurso emite pro store: o App re-renderiza, trava as abas
    // e esta tela cai em <Correndo>.
  }

  return (
    <ScrollView contentContainerStyle={styles.hoje}>
      <View style={styles.cardHoje}>
        <Text style={styles.fieldLabel}>{decisao.quandoRotulo}</Text>
        <Text style={styles.prescricao}>
          {ROTULO_ATIVIDADE[decisao.atividade]} · {decisao.duracaoMin} min
        </Text>
        <Text style={styles.muted}>Intensidade {decisao.intensidade}</Text>
        <Text style={styles.muted}>
          Meta da sessão: {rotuloMeta(decisao.metaSessao)} — um alvo pra tentar, não uma obrigação.
        </Text>
      </View>

      <View style={styles.cardHoje}>
        <Text style={styles.fieldLabel}>Por que isso</Text>
        <Text style={styles.muted}>{decisao.porQue}</Text>
      </View>

      <CartaoCombinado decisao={decisao} nav={nav} />

      <View style={styles.cardHoje}>
        <Text style={styles.fieldLabel}>Últimas sessões</Text>
        {ultimas.length === 0 ? (
          <Text style={styles.muted}>Nenhuma sessão registrada ainda.</Text>
        ) : (
          ultimas.map((c) => (
            <View key={c.id} style={styles.row}>
              <Text style={styles.muted}>{fmtDataHora(c.inicio)}</Text>
              <Text style={styles.strong}>
                {c.duracaoMin} min{c.distanciaKm ? ` · ${c.distanciaKm} km` : ''}
              </Text>
            </View>
          ))
        )}
      </View>

      <CartaoObjetivo corridas={getCorridas()} />

      <Text style={[styles.muted, styles.center]}>Toque quando começar. A gente anota o horário pra você.</Text>
      <Pressable
        style={({ pressed }) => [styles.primaryBig, pressed && styles.pressed]}
        onPress={comecar}
      >
        <Text style={styles.primaryBigTxt}>Comecei</Text>
      </Pressable>
      {gpsOk === false ? (
        <Text style={[styles.muted, styles.center]}>
          O GPS não está disponível — a distância da corrida não será medida. Você pode permitir o uso{' '}
          <Text style={styles.link} onPress={() => void permitirGps()}>
            aqui
          </Text>
          .
        </Text>
      ) : null}
    </ScrollView>
  )
}

// --- Combinado (milestone 7): a negociação do horário mora na conversa com o
// treinador (aba Treinador — o write é o combinar() de compromissos.ts). Aqui
// o combinado ativo aparece somente-leitura; sem combinado, o link leva à
// conversa. O desfecho (cumprido/perdido) é resolvido pelo
// reconciliarCompromissos no boot e ao salvar a sessão.
function CartaoCombinado({ decisao, nav }: { decisao: Decisao; nav: Nav }): React.JSX.Element {
  const ativo = compromissoAtivo(getModeloUsuario().compromissos)

  return (
    <View style={styles.cardHoje}>
      <Text style={styles.fieldLabel}>Combinado</Text>
      {ativo != null ? (
        <>
          <Text style={styles.strong}>
            {ativo.atividade} · {fmtCompromisso(ativo.quando)}
          </Text>
          <Text style={styles.muted}>Combinado com o treinador — eu vou estar aqui.</Text>
        </>
      ) : (
        <>
          <Text style={styles.muted}>Nenhum horário combinado.</Text>
          <Pressable style={({ pressed }) => pressed && styles.pressed} onPress={() => nav.go('treinador')}>
            <Text style={styles.link}>Falar com o treinador</Text>
          </Pressable>
        </>
      )}
      <Text style={styles.muted}>Seu plano de caminhada/corrida: {decisao.frequenciaSemanal}x por semana.</Text>
    </View>
  )
}

// --- Cronômetro ---
function Correndo({ inicio, alvoMin }: { inicio: number; alvoMin: number }): React.JSX.Element {
  // Já pinta o tempo corrente: numa retomada o cronômetro não pode piscar 00:00.
  const [elapsed, setElapsed] = useState(() => fmtElapsed(Date.now() - inicio))
  // Distância GPS até agora (null = indisponível); atualiza no tick do cronômetro.
  const [dist, setDist] = useState<number | null>(() => distanciaEmCurso())

  useEffect(() => {
    const id = setInterval(() => {
      if (!runStart) return
      const decorrido = Date.now() - runStart
      if (decorrido >= limiteMs()) {
        void finalizar(runStart + limiteMs()) // emite pro store → cai no formulário
        return
      }
      setElapsed(fmtElapsed(decorrido))
      setDist(distanciaEmCurso())
    }, 1000)
    return () => clearInterval(id)
  }, [])

  return (
    <View style={styles.hero}>
      <Text style={styles.timer}>{elapsed}</Text>
      {dist !== null ? <Text style={styles.dist}>📍 {dist.toFixed(2)} km</Text> : null}
      {dist !== null ? (
        <Text style={[styles.muted, styles.center]}>
          {dist >= OBJETIVO.distanciaKm
            ? `Distância do objetivo cumprida 🎉 — agora é fechar os ${OBJETIVO.duracaoMin} min.`
            : `Faltam ${(OBJETIVO.distanciaKm - dist).toFixed(2)} km pro objetivo.`}
        </Text>
      ) : null}
      <Text style={[styles.muted, styles.center]}>
        {getCorridaEmCurso()?.metaSessao === 'distancia'
          ? `Meta da sessão: percorrer ${OBJETIVO.distanciaKm} km`
          : `Sessão de ${alvoMin} min`}{' '}
        — vá no seu ritmo.
      </Text>
      <Pressable
        style={({ pressed }) => [styles.primaryBig, styles.danger, pressed && styles.pressed]}
        onPress={() => finalizar(Date.now())}
      >
        <Text style={styles.primaryBigTxt}>Parei</Text>
      </Pressable>
    </View>
  )
}

// --- Formulário pós-corrida ---
function FormRascunho({
  draft: d,
  onSalvo,
}: {
  draft: Partial<Corrida>
  onSalvo: (corrida: Corrida) => void
}): React.JSX.Element {
  const [formLocal, setFormLocal] = useState<Local>('externo')
  // Distância medida pelo GPS durante a corrida (veio no rascunho). Na
  // esteira ela não faz sentido — volta a entrar a distância manual.
  const distGps = formLocal === 'externo' ? (d.distanciaKm ?? null) : null
  const kmRef = useRef<WheelPickerHandle>(null)
  const mRef = useRef<WheelPickerHandle>(null)

  const salvar = (): void => {
    const dist =
      distGps ?? (kmRef.current?.getValue() ?? 0) + (mRef.current?.getValue() ?? 0) / 1000
    const corrida: Corrida = {
      id: d.id!,
      inicio: d.inicio!,
      fim: d.fim!,
      duracaoMin: d.duracaoMin!,
      local: formLocal,
      ...(dist > 0 ? { distanciaKm: Math.round(dist * 10) / 10 } : {}),
      ...(d.meta != null ? { meta: d.meta } : {}),
    }
    addCorrida(corrida)
    recalcularAutopilot() // a nova sessão muda os sinais observados
    reconciliarCompromissos() // sessão no dia do compromisso ⇒ cumprido

    telemetry.runSaved()

    draft = null
    clearRascunho()
    onSalvo(corrida)
  }

  const descartar = (): void => {
    draft = null
    clearRascunho() // emite pro store → volta pra tela inicial
  }

  return (
    <ScrollView keyboardShouldPersistTaps="handled">
      <View style={styles.cardForm}>
        <View style={styles.row}>
          <Text style={styles.muted}>Duração</Text>
          <Text style={styles.strong}>{d.duracaoMin} min</Text>
        </View>
        <View style={styles.row}>
          <Text style={styles.muted}>Quando</Text>
          <Text style={styles.strong}>{fmtDataHora(d.inicio!)}</Text>
        </View>
        {distGps !== null ? (
          <View style={styles.row}>
            <Text style={styles.muted}>Distância (GPS)</Text>
            <Text style={styles.strong}>{distGps.toFixed(2)} km</Text>
          </View>
        ) : (
          <View style={styles.field}>
            <Text style={styles.fieldLabel}>Distância — opcional</Text>
            <View style={styles.pickerRow}>
              <View style={styles.pickerCell}>
                <WheelPicker ref={kmRef} min={0} max={30} step={1} def={0} label="km" unit="km" />
              </View>
              <View style={styles.pickerCell}>
                <WheelPicker ref={mRef} min={0} max={900} step={100} def={0} label="metros" unit="m" />
              </View>
            </View>
          </View>
        )}
        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Onde</Text>
          <View style={styles.seg}>
            <Pressable
              style={[styles.segBtn, formLocal === 'externo' && styles.segBtnOn]}
              onPress={() => setFormLocal('externo')}
            >
              <Text style={[styles.segTxt, formLocal === 'externo' && styles.segTxtOn]}>Externo</Text>
            </Pressable>
            <Pressable
              style={[styles.segBtn, formLocal === 'esteira' && styles.segBtnOn]}
              onPress={() => setFormLocal('esteira')}
            >
              <Text style={[styles.segTxt, formLocal === 'esteira' && styles.segTxtOn]}>Esteira</Text>
            </Pressable>
          </View>
        </View>
        <View style={styles.actions}>
          <Pressable style={({ pressed }) => [styles.ghost, pressed && styles.pressed]} onPress={descartar}>
            <Text style={styles.ghostTxt}>Descartar</Text>
          </Pressable>
          <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={salvar}>
            <Text style={styles.primaryTxt}>Salvar</Text>
          </Pressable>
        </View>
      </View>
    </ScrollView>
  )
}

// --- Confirmação ---
const FEEDBACKS: { valor: FeedbackSessao; rotulo: string }[] = [
  { valor: 'leve', rotulo: 'Leve' },
  { valor: 'normal', rotulo: 'Normal' },
  { valor: 'dificil', rotulo: 'Difícil' },
]

function Confirmacao({ corrida, onVoltar }: { corrida: Corrida; onVoltar: () => void }): React.JSX.Element {
  // Feedback pós-sessão (milestone 6): entra no User Model e o Decision
  // Engine já o usa na decisão seguinte. Trocar a escolha substitui o
  // registro da mesma corrida (mesmo corridaId), sem duplicar.
  const [feedback, setFeedback] = useState<FeedbackSessao | null>(
    () => getModeloUsuario().feedbacks.find((f) => f.corridaId === corrida.id)?.feedback ?? null,
  )

  // A meta da sessão é um alvo aspiracional (visão §6): cumpri-la merece
  // celebração; não cumprir não é falha.
  const metaCumprida =
    corrida.meta === 'tempo'
      ? corrida.duracaoMin >= OBJETIVO.duracaoMin
      : corrida.meta === 'distancia'
        ? (corrida.distanciaKm ?? 0) >= OBJETIVO.distanciaKm
        : false

  // Objetivo do plano (3 km em 20 min): se a primeira sessão da história que
  // o fecha é esta, a conquista é o destaque da confirmação.
  const objetivoAtingido = atingiuObjetivo(getCorridas())?.id === corrida.id

  const registrar = (f: FeedbackSessao): void => {
    const atual = getModeloUsuario()
    setModeloUsuario({
      ...atual,
      feedbacks: [
        ...atual.feedbacks.filter((x) => x.corridaId !== corrida.id),
        { corridaId: corrida.id, feedback: f, quando: new Date().toISOString() },
      ],
    })
    recalcularAutopilot()
    setFeedback(f)

    telemetry.feedbackRecorded(f)
  }

  return (
    <View style={styles.hero}>
      <Text style={styles.ok}>✅</Text>
      <Text style={styles.h2}>Corrida registrada!</Text>
      <Text style={[styles.muted, styles.center]}>
        {corrida.duracaoMin} min{corrida.distanciaKm ? ` · ${corrida.distanciaKm} km` : ''}
      </Text>
      {objetivoAtingido ? (
        <Text style={[styles.h2, styles.center]}>
          🏁 Objetivo atingido: {OBJETIVO.distanciaKm} km em {OBJETIVO.duracaoMin} minutos!
        </Text>
      ) : null}
      {metaCumprida ? <Text style={[styles.strong, styles.center]}>Meta da sessão cumprida! 🎉</Text> : null}
      <View style={styles.feedbackBox}>
        <Text style={[styles.fieldLabel, styles.center]}>Como foi essa sessão?</Text>
        <View style={styles.seg}>
          {FEEDBACKS.map((f) => (
            <Pressable
              key={f.valor}
              style={[styles.segBtn, feedback === f.valor && styles.segBtnOn]}
              onPress={() => registrar(f.valor)}
            >
              <Text style={[styles.segTxt, feedback === f.valor && styles.segTxtOn]}>{f.rotulo}</Text>
            </Pressable>
          ))}
        </View>
      </View>
      <Pressable style={({ pressed }) => [styles.primary, styles.voltar, pressed && styles.pressed]} onPress={onVoltar}>
        <Text style={styles.primaryTxt}>Voltar</Text>
      </Pressable>
    </View>
  )
}

