// Painel de anéis: duas faixas circulares concêntricas que mostram, para a
// corrida selecionada no gráfico de Frequência, o quanto ela cobre da meta.
//
//   faixa externa — tempo:     0 min → 0°, OBJETIVO.duracaoMin  → 360° (volta inteira)
//   faixa interna — distância: 0 km  → 0°, OBJETIVO.distanciaKm → 360°
//
// Quem escolhe a corrida é o gráfico (a que está sob o marcador da rolagem);
// aqui só se desenha o valor recebido.

import React from 'react'
import { StyleSheet, Text, View } from 'react-native'
import Svg, { Circle, G } from 'react-native-svg'
import { OBJETIVO, type Corrida } from '../state'
import { fmtData } from '../format'
import { theme } from '../theme'

const SIZE = 108
const C = SIZE / 2
const R_TEMPO = 45
const R_DIST = 31
const L_TEMPO = 2 * Math.PI * R_TEMPO
const L_DIST = 2 * Math.PI * R_DIST
const TRILHO = 'rgba(60, 60, 67, 0.1)'

// Volta completa no máximo: uma corrida acima da meta enche o anel e para.
function fracao(valor: number | undefined, meta: number): number {
  if (!valor || valor <= 0) return 0
  return Math.min(1, valor / meta)
}

export function Aneis({ corrida }: { corrida: Corrida | null }): React.JSX.Element {
  const c = corrida
  const fT = fracao(c?.duracaoMin, OBJETIVO.duracaoMin)
  const fD = fracao(c?.distanciaKm, OBJETIVO.distanciaKm)
  return (
    <View style={styles.card}>
      <Text style={styles.dia}>{c ? fmtData(c.inicio) : '—'}</Text>
      <View style={styles.wrap}>
        <Svg width={SIZE} height={SIZE} viewBox={`0 0 ${SIZE} ${SIZE}`}>
          <G rotation="-90" origin={`${C}, ${C}`}>
            <Circle cx={C} cy={C} r={R_TEMPO} stroke={TRILHO} strokeWidth={11} fill="none" />
            <Circle
              cx={C}
              cy={C}
              r={R_TEMPO}
              stroke={theme.tempo}
              strokeWidth={11}
              strokeLinecap="round"
              fill="none"
              strokeDasharray={L_TEMPO}
              strokeDashoffset={L_TEMPO * (1 - fT)}
            />
            <Circle cx={C} cy={C} r={R_DIST} stroke={TRILHO} strokeWidth={11} fill="none" />
            <Circle
              cx={C}
              cy={C}
              r={R_DIST}
              stroke={theme.dist}
              strokeWidth={11}
              strokeLinecap="round"
              fill="none"
              strokeDasharray={L_DIST}
              strokeDashoffset={L_DIST * (1 - fD)}
            />
          </G>
        </Svg>
        <View pointerEvents="none" style={styles.val}>
          <Text style={styles.linha}>
            <Text style={[styles.num, { color: theme.tempo }]}>{c ? String(c.duracaoMin) : '—'}</Text>
            <Text style={styles.un}> min</Text>
          </Text>
          <Text style={styles.linha}>
            <Text style={[styles.num, { color: theme.dist }]}>
              {c?.distanciaKm ? c.distanciaKm.toFixed(1) : '—'}
            </Text>
            <Text style={styles.un}> km</Text>
          </Text>
        </View>
      </View>
    </View>
  )
}

const styles = StyleSheet.create({
  card: {
    backgroundColor: theme.card,
    borderRadius: 14,
    paddingTop: 8,
    paddingHorizontal: 10,
    paddingBottom: 10,
    alignItems: 'center',
  },
  dia: {
    fontSize: 11,
    fontWeight: '600',
    color: theme.secondaryStrong,
    marginBottom: 4,
  },
  wrap: {
    width: SIZE,
    height: SIZE,
  },
  val: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    justifyContent: 'center',
    alignItems: 'center',
    gap: 1,
  },
  linha: {
    lineHeight: 16,
  },
  num: {
    fontSize: 14,
    fontWeight: '700',
  },
  un: {
    fontSize: 9,
    color: theme.secondary,
  },
})
