// Lembretes de compromisso (milestone 7, set/2026): notificações locais
// agendadas — chegam mesmo com o app fechado, como o "eu vou estar aqui" de
// um treinador. expo-notifications não existe na web: lá tudo vira no-op e o
// lembrete aparece só no cartão "Quando combinamos".
//
// Notificação nenhuma pode derrubar o app: toda falha vira null/catch,
// no mesmo espírito do telemetry.ts.

import { Platform } from 'react-native'
import * as Notifications from 'expo-notifications'
import { type Compromisso } from './usuario'
import { isOnboarded } from './state'

const CANAL = 'compromissos'
const nativo = Platform.OS === 'android' || Platform.OS === 'ios'

/** A partir de quantos combinados perdidos seguidos o lembrete vira recomeço
 *  ("você não correu nas últimas 3") — decisão de 13/out/2026 (D18). */
const PERDIDOS_RECOMECO = 3

const REENGAJE_DIAS = 3
const TIPO_REENGAJE = 'reengajamento'

/** Handler (mostra o lembrete mesmo com o app aberto) + canal Android. No boot. */
export async function setupNotificacoes(): Promise<void> {
  if (!nativo) return
  Notifications.setNotificationHandler({
    handleNotification: async () => ({
      shouldPlaySound: false,
      shouldSetBadge: false,
      shouldShowBanner: true,
      shouldShowList: true,
    }),
  })
  if (Platform.OS === 'android') {
    await Notifications.setNotificationChannelAsync(CANAL, {
      name: 'Compromissos',
      importance: Notifications.AndroidImportance.DEFAULT,
    }).catch(() => {})
  }
}

async function permissoesOk(): Promise<boolean> {
  const atual = await Notifications.getPermissionsAsync()
  if (atual.granted) return true
  // Pedida no gesto de "Combinar": o prompt do sistema é esperado ali.
  const pedida = await Notifications.requestPermissionsAsync()
  return pedida.granted
}

/** O texto é decidido na hora de agendar, quando o histórico é conhecido: com
 *  vários combinados perdidos seguidos, o lembrete acolhe o recomeço em vez de
 *  fingir que nada aconteceu. */
function corpoLembrete(c: Compromisso, perdidosSeguidos: number): string {
  if (perdidosSeguidos >= PERDIDOS_RECOMECO) {
    return `Você faltou aos últimos ${perdidosSeguidos} combinados — sem peso: ${c.atividade} de agora é um recomeço. Eu estou aqui.`
  }
  return `Combinamos ${c.atividade} agora — eu estou aqui.`
}

/** Agenda o lembrete pra hora combinada. Devolve o identificador (gravado no
 *  compromisso pra cancelamento) ou null quando não deu: web, permissão
 *  negada, horário já passado ou falha qualquer — o compromisso vale mesmo
 *  sem lembrete. */
export async function agendarLembrete(c: Compromisso, perdidosSeguidos = 0): Promise<string | null> {
  if (!nativo) return null
  try {
    if (!(await permissoesOk())) return null
    const quando = new Date(c.quando)
    if (quando.getTime() <= Date.now()) return null
    return await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Corrida Leve',
        body: corpoLembrete(c, perdidosSeguidos),
      },
      trigger: { type: Notifications.SchedulableTriggerInputTypes.DATE, date: quando, channelId: CANAL },
    })
  } catch {
    return null
  }
}

export async function cancelarLembrete(id: string): Promise<void> {
  if (!nativo) return
  await Notifications.cancelScheduledNotificationAsync(id).catch(() => {})
}

/** Reengajamento ("você não abre o app há N dias"): agendado a cada abertura
 *  e reagendado na seguinte — dispara só se o praticante sumir. Nunca pede
 *  permissão (o boot não é o gesto de "Combinar": pedir aqui seria intrusivo);
 *  sem permissão já concedida, não agenda. E só com onboarding concluído:
 *  o "Apagar tudo" não pode reviver lembrete. */
export async function reagendarReengajamento(): Promise<void> {
  if (!nativo || !isOnboarded()) return
  try {
    if (!(await Notifications.getPermissionsAsync()).granted) return
    const agendadas = await Notifications.getAllScheduledNotificationsAsync()
    for (const n of agendadas) {
      if (n.content.data?.tipo === TIPO_REENGAJE) {
        await Notifications.cancelScheduledNotificationAsync(n.identifier).catch(() => {})
      }
    }
    await Notifications.scheduleNotificationAsync({
      content: {
        title: 'Corrida Leve',
        body: 'Senti sua falta por aqui. Quando quiser, a gente retoma de onde parou.',
        data: { tipo: TIPO_REENGAJE },
      },
      trigger: {
        type: Notifications.SchedulableTriggerInputTypes.DATE,
        date: new Date(Date.now() + REENGAJE_DIAS * 24 * 60 * 60 * 1000),
        channelId: CANAL,
      },
    })
  } catch {
    // mesmo espírito dos lembretes: falha alguma pode derrubar o app
  }
}

/** O "Apagar tudo" limpa o armazenamento, mas os lembretes já agendados
 *  continuam no sistema — sem isto eles disparariam órfãos. */
export async function cancelarTodosLembretes(): Promise<void> {
  if (!nativo) return
  await Notifications.cancelAllScheduledNotificationsAsync().catch(() => {})
}
