// Gráfico 1 de Progressão: linha do tempo das corridas (dia × hora).
// Porte fiel do progressao.ts do PWA.
//
//   eixo x (horizontal, rolável): dias do calendário, da 1ª corrida até hoje.
//     linha 1 — dia do mês
//     linha 2 — mês (faixa alinhada aos dias)
//     linha 3 — estação (faixa alinhada aos meses)
//   eixo y (fixo, à esquerda): hora do dia (0–24)
//   ponto = ícone do corredor: rua (verde) ou esteira (azul). Tempo e
//     distância só aparecem sob o corredor do dia selecionado (marcador).

import React, { useEffect, useMemo, useRef, useState } from 'react'
import {
  ScrollView,
  StyleSheet,
  Text,
  View,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
} from 'react-native'
import Svg, { Path, Rect } from 'react-native-svg'
import { type Corrida } from '../state'
import { theme } from '../theme'

type Estacao = 'verao' | 'outono' | 'inverno' | 'primavera'

const MESES = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez']
const ESTACAO_EMOJI: Record<Estacao, string> = {
  verao: '☀️',
  outono: '🍂',
  inverno: '❄️',
  primavera: '🌸',
}

const DAY_W = 30 // largura de cada dia (px)
const PLOT_H = 176 // altura da área de plotagem
const AXIS_H = 66 // 3 faixas × 22px: dia + mês + estação

// Janela padrão do eixo y (05h–22h). Se houver corrida fora dela, a janela
// se estende (com 1h de folga) até caber o ponto, no máximo 0h–24h.
const H_PADRAO_MIN = 5
const H_PADRAO_MAX = 22
const FOLGA_H = 1

function meiaNoite(iso: string): Date {
  const d = new Date(iso)
  d.setHours(0, 0, 0, 0)
  return d
}
function diasEntre(a: Date, b: Date): number {
  return Math.round((b.getTime() - a.getTime()) / 86400000)
}
function estacaoDe(mes: number): Estacao {
  if (mes === 11 || mes === 0 || mes === 1) return 'verao'
  if (mes >= 2 && mes <= 4) return 'outono'
  if (mes >= 5 && mes <= 7) return 'inverno'
  return 'primavera'
}

// Marcações do eixo y: múltiplos de um passo "redondo", mais as bordas da
// janela quando sobra espaço pra elas não colidirem com o vizinho.
function ticksDeHora(hMin: number, hMax: number): number[] {
  const span = hMax - hMin
  const passo = [1, 2, 3, 4, 6, 12].find((p) => span / p <= 5) ?? 12
  const ts: number[] = []
  for (let h = Math.ceil(hMin / passo) * passo; h <= hMax; h += passo) ts.push(h)
  if (ts.length === 0 || ts[0] - hMin >= passo / 2) ts.unshift(hMin)
  if (hMax - ts[ts.length - 1] >= passo / 2) ts.push(hMax)
  return ts
}

// Pictograma de corredor (estilo Material "directions_run"), preenchido.
const RUNNER =
  'M13.49 5.48c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm-3.6 13.9l1-4.4 2.1 2v6h2v-7.5l-2.1-2 .6-3c1.3 1.5 3.3 2.5 5.5 2.5v-2c-1.9 0-3.5-1-4.3-2.4l-1-1.6c-.4-.6-1-1-1.7-1-.3 0-.5.1-.8.1l-5.2 2.2v4.7h2v-3.4l1.8-.7-1.6 8.1-4.9-1-.4 2 7 1.4z'

function IconeCorredor({ local, cor }: { local: Corrida['local']; cor: string }): React.JSX.Element {
  return (
    <Svg viewBox="0 0 24 24" width={22} height={22} fill={cor} stroke="none">
      <Path d={RUNNER} />
      {local === 'esteira' ? <Rect x={2.5} y={20.2} width={19} height={3} rx={1.5} /> : null}
    </Svg>
  )
}

interface Dados {
  cs: Corrida[]
  xs: number[]
  canvasW: number
  y: (h: number) => number
  horasY: number[]
  dias: { d: number; left: number }[]
  bandasMes: { label: string; left: number; width: number }[]
  bandasEst: { emoji: string; left: number; width: number }[]
}

function preparar(corridas: Corrida[]): Dados | null {
  const cs = [...corridas].sort((a, b) => a.inicio.localeCompare(b.inicio))
  if (cs.length === 0) return null
  const inicio = meiaNoite(cs[0].inicio)
  const ultCorrida = meiaNoite(cs[cs.length - 1].inicio)
  const hoje = meiaNoite(new Date().toISOString())
  const fim = ultCorrida.getTime() > hoje.getTime() ? ultCorrida : hoje
  const nDias = diasEntre(inicio, fim) + 1
  const canvasW = nDias * DAY_W

  // Janela do eixo y a partir dos dados, ancorada no padrão 5h–22h.
  const horas = cs.map((c) => {
    const d = new Date(c.inicio)
    return d.getHours() + d.getMinutes() / 60
  })
  const hMin = Math.max(0, Math.min(H_PADRAO_MIN, Math.floor(Math.min(...horas) - FOLGA_H)))
  const hMax = Math.min(24, Math.max(H_PADRAO_MAX, Math.ceil(Math.max(...horas) + FOLGA_H)))
  const y = (h: number): number => ((hMax - h) / (hMax - hMin)) * PLOT_H

  const xs: number[] = []
  for (const c of cs) {
    const idx = diasEntre(inicio, meiaNoite(c.inicio))
    xs.push(idx * DAY_W + DAY_W / 2)
  }

  const dias: { d: number; left: number }[] = []
  const bandasMes: { mes: number; label: string; left: number; width: number }[] = []
  let chaveMes = -1
  for (let i = 0; i < nDias; i++) {
    const dt = new Date(inicio)
    dt.setDate(inicio.getDate() + i)
    dias.push({ d: dt.getDate(), left: i * DAY_W })
    const k = dt.getFullYear() * 12 + dt.getMonth()
    if (k !== chaveMes) {
      bandasMes.push({ mes: dt.getMonth(), label: MESES[dt.getMonth()], left: i * DAY_W, width: DAY_W })
      chaveMes = k
    } else {
      bandasMes[bandasMes.length - 1].width += DAY_W
    }
  }
  const bandasEst: { emoji: string; left: number; width: number }[] = []
  let chaveEst = ''
  for (const b of bandasMes) {
    const e = estacaoDe(b.mes)
    if (e !== chaveEst) {
      bandasEst.push({ emoji: ESTACAO_EMOJI[e], left: b.left, width: b.width })
      chaveEst = e
    } else {
      bandasEst[bandasEst.length - 1].width += b.width
    }
  }

  return { cs, xs, canvasW, y, horasY: ticksDeHora(hMin, hMax), dias, bandasMes, bandasEst }
}

/**
 * @param onSelecionar chamado com a corrida sob o marcador (a barra vertical
 *   que acompanha a rolagem) — no início e a cada rolagem.
 */
export function Progressao({
  corridas,
  onSelecionar,
}: {
  corridas: Corrida[]
  onSelecionar?: (c: Corrida | null) => void
}): React.JSX.Element {
  const dados = useMemo(() => preparar(corridas), [corridas])
  const [sel, setSel] = useState(-1)
  const [viewportW, setViewportW] = useState(0)
  const scrollXRef = useRef(0)
  const selRef = useRef(-1)
  const onSelecionarRef = useRef(onSelecionar)
  onSelecionarRef.current = onSelecionar

  // Seleção: um marcador percorre o gráfico junto com a rolagem. Ele parte da
  // borda esquerda, caminha até o centro da tela e fica lá enquanto se arrasta;
  // quando o fim do gráfico aparece, volta a andar até a borda direita — assim
  // o último dia também pode ser selecionado. A corrida escolhida é a mais
  // próxima do marcador, e a barra sombreada cai sobre o dia dela.
  const selecionar = (s: number, w: number): void => {
    if (!dados || w <= 0) return
    const max = Math.max(0, dados.canvasW - w)
    // Três fases: saindo da esquerda (2s), parado no centro (s + meia tela) e
    // indo pra direita. A mediana das três escolhe a fase certa sozinha.
    const x = [2 * s, s + w / 2, 2 * s - max + w].sort((a, b) => a - b)[1]
    let i = 0
    for (let k = 1; k < dados.xs.length; k++) {
      if (Math.abs(dados.xs[k] - x) < Math.abs(dados.xs[i] - x)) i = k
    }
    if (i === selRef.current) return
    selRef.current = i
    setSel(i)
    onSelecionarRef.current?.(dados.cs[i])
  }

  // Seleção inicial (o PWA chama selecionar() ao montar) e re-seleção quando
  // os dados mudam (a corrida sob o marcador pode ser outra).
  useEffect(() => {
    selRef.current = -1
    if (dados && viewportW > 0) selecionar(scrollXRef.current, viewportW)
    else if (!dados) onSelecionarRef.current?.(null)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dados, viewportW])

  const aoRolar = (e: NativeSyntheticEvent<NativeScrollEvent>): void => {
    scrollXRef.current = e.nativeEvent.contentOffset.x
    selecionar(scrollXRef.current, e.nativeEvent.layoutMeasurement.width)
  }

  if (!dados) {
    return <Text style={styles.vazio}>Sem corridas pra mostrar ainda.</Text>
  }

  return (
    <View style={styles.prog}>
      <View style={styles.eixoY}>
        {dados.horasY.map((h) => (
          <Text key={h} style={[styles.eixoYTxt, { top: dados.y(h) - 6 }]}>
            {h}h
          </Text>
        ))}
      </View>
      <ScrollView
        horizontal
        style={styles.scroll}
        showsHorizontalScrollIndicator={false}
        onScroll={aoRolar}
        scrollEventThrottle={16}
        onLayout={(e) => setViewportW(e.nativeEvent.layout.width)}
      >
        <View style={{ width: dados.canvasW, height: PLOT_H + AXIS_H }}>
          {/* grade */}
          {dados.horasY.map((h) => (
            <View key={h} style={[styles.gline, { top: dados.y(h) }]} />
          ))}
          {/* marcador do dia selecionado */}
          {sel >= 0 ? (
            <View
              pointerEvents="none"
              style={[styles.marca, { left: dados.xs[sel] - DAY_W / 2, width: DAY_W, height: PLOT_H + 22 }]}
            />
          ) : null}
          {/* pontos */}
          {dados.cs.map((c, i) => {
            const d = new Date(c.inicio)
            const hora = d.getHours() + d.getMinutes() / 60
            const selecionado = i === sel
            const cor = c.local === 'esteira' ? theme.blue : theme.green
            return (
              <View
                key={c.id}
                style={[
                  styles.pt,
                  {
                    left: dados.xs[i] - 11,
                    top: dados.y(hora) - 11,
                    transform: [{ scale: selecionado ? 1.25 : 1 }],
                  },
                ]}
              >
                <IconeCorredor local={c.local} cor={cor} />
                {selecionado ? (
                  <View style={styles.ptLab}>
                    <Text style={styles.plLinha}>
                      <Text style={[styles.plNum, { color: theme.tempo }]}>{c.duracaoMin}</Text>
                      <Text style={styles.plUn}> min</Text>
                    </Text>
                    {c.distanciaKm ? (
                      <Text style={styles.plLinha}>
                        <Text style={[styles.plNum, { color: theme.dist }]}>{c.distanciaKm.toFixed(1)}</Text>
                        <Text style={styles.plUn}> km</Text>
                      </Text>
                    ) : null}
                  </View>
                ) : null}
              </View>
            )
          })}
          {/* eixo x: dia + mês + estação */}
          <View style={[styles.axLinha, { top: PLOT_H }]}>
            {dados.dias.map((dd, i) => (
              <Text key={i} style={[styles.dnum, { left: dd.left, width: DAY_W }]}>
                {dd.d}
              </Text>
            ))}
          </View>
          <View style={[styles.axLinha, { top: PLOT_H + 22 }]}>
            {dados.bandasMes.map((b, i) => (
              <Text key={i} style={[styles.mband, { left: b.left, width: b.width }]}>
                {b.label}
              </Text>
            ))}
          </View>
          <View style={[styles.axLinha, { top: PLOT_H + 44 }]}>
            {dados.bandasEst.map((b, i) => (
              <Text key={i} style={[styles.eband, { left: b.left, width: b.width }]}>
                {b.emoji}
              </Text>
            ))}
          </View>
        </View>
      </ScrollView>
    </View>
  )
}

