// Decision Engine (milestone 3, set/2026): motor determinístico do Autopilot.
//
//   estado do usuário → capacidade → próximo nível → frequência → atividade
//                       → duração/intensidade
//
// Regras explícitas, sem LLM: funções puras que recebem o User Model completo
// e devolvem a próxima decisão. A camada conversacional (milestone 8) explica
// estas decisões, mas nunca as substitui. Limiares são heurísticas v1, a
// calibrar com uso real no alpha.

import { type AvaliacaoNivel, type Nivel } from './niveis'
import { type ModeloUsuario, type SinaisObservados, ultimoFeedback } from './usuario'

export type TipoAtividade = 'caminhada' | 'caminhada_rapida' | 'corrida_caminhada' | 'corrida'

/** Objetivo aspiracional da sessão (visão §6): 20 min de atividade ou 3 km.
 *  Não precisa ser cumprido; quando é, a sessão fecha a meta. */
export type MetaSessao = 'tempo' | 'distancia'

export const ROTULO_ATIVIDADE: Record<TipoAtividade, string> = {
  caminhada: 'Caminhada',
  caminhada_rapida: 'Caminhada rápida',
  corrida_caminhada: 'Corrida/caminhada',
  corrida: 'Corrida',
}

export interface Decisao {
  nivelAlvo: Nivel // para onde o plano está trabalhando (nível atual quando bloqueado)
  frequenciaSemanal: number // sessões por semana prescritas
  atividade: TipoAtividade
  duracaoMin: number
  intensidade: string
  metaSessao: MetaSessao // a meta do dia: 20 min (tempo) ou 3 km (distância, nível 2+)
  quandoRotulo: string // "Hoje", "Amanhã" ou o dia da semana da próxima sessão
  porQue: string // a explicação da decisão (o agente conversa a partir daqui)
  progressaoCongelada: boolean // true quando o plano mantém sem progredir
}

// --- Regras v1 por nível (heurísticas iniciais, a calibrar com dados reais) ---
interface RegraNivel {
  atividade: TipoAtividade
  frequencia: number
  duracaoMin: number
  intensidade: string
}

const REGRAS: RegraNivel[] = [
  // 0 — Sedentário: começar pequeno para criar o hábito
  { atividade: 'caminhada', frequencia: 2, duracaoMin: 15, intensidade: 'leve, dando para conversar' },
  // 1 — Caminha regularmente: alongar a sessão rumo aos 20 min
  { atividade: 'caminhada', frequencia: 2, duracaoMin: 20, intensidade: 'leve, dando para conversar' },
  // 2 — Sustenta 20 min: consolidar a duração com passo mais firme
  { atividade: 'caminhada_rapida', frequencia: 3, duracaoMin: 20, intensidade: 'moderada, respiração acelerada mas controlada' },
  // 3 — Alterna caminhada e corrida: introduzir trechos de corrida
  { atividade: 'corrida_caminhada', frequencia: 3, duracaoMin: 20, intensidade: 'moderada, alternando para recuperar' },
  // 4 — Corre 3 km em 20 min: transformar a linha de chegada em hábito
  { atividade: 'corrida', frequencia: 3, duracaoMin: 20, intensidade: 'moderada, ritmo confortável' },
  // 5 — Corre regularmente: manter a consistência. Único nível com sessões
  // acima de 20 min: é o "depois da linha de chegada" (voos mais altos ficam
  // a cargo do treinador — a escala do app termina aqui).
  { atividade: 'corrida', frequencia: 3, duracaoMin: 30, intensidade: 'moderada, ritmo confortável' },
]

const DURACAO_MINIMA_MIN = 10
const PASSO_DURACAO_MIN = 5

function arredondar(min: number): number {
  return Math.max(DURACAO_MINIMA_MIN, Math.round(min / PASSO_DURACAO_MIN) * PASSO_DURACAO_MIN)
}

/**
 * Decide a próxima prescrição a partir do User Model completo e da avaliação
 * de nível. Determinística: mesmo estado, mesma decisão.
 */
export function decidir(
  modelo: ModeloUsuario & { sinais: SinaisObservados },
  avaliacao: AvaliacaoNivel,
): Decisao {
  const feedback = ultimoFeedback(modelo)
  const nivelAlvo = avaliacao.bloqueado || avaliacao.proximo == null
    ? avaliacao.nivel
    : avaliacao.proximo
  const regra = REGRAS[avaliacao.nivel]

  // Frequência: a que a pessoa declarou conseguir — o app avança a partir
  // de onde ela já está (quem já caminha 5x não é jogado num plano de 2x).
  // A cautela da escada vive na duração/intensidade, não na frequência.
  const frequenciaSemanal = modelo.disponibilidade != null
    ? Math.min(7, Math.max(1, modelo.disponibilidade.sessoesPorSemana))
    : regra.frequencia

  // Duração base: regra do nível, limitada ao teto da disponibilidade declarada.
  let duracao = regra.duracaoMin
  if (modelo.disponibilidade != null) {
    duracao = Math.min(duracao, modelo.disponibilidade.minutosPorSessao)
  }

  const ajustes: string[] = []

  // Retomada após lacuna longa: sessão mais curta para voltar com segurança.
  if (modelo.sinais.diasSemAtividade != null && modelo.sinais.diasSemAtividade >= 14) {
    duracao *= 0.8
    ajustes.push('sessão mais curta para retomar com segurança')
  }

  // Progressão: sessões leves e plano livre para avançar ⇒ estica um passo,
  // sem passar da duração da regra do nível alvo.
  if (!avaliacao.bloqueado && feedback === 'leve' && avaliacao.proximo != null) {
    duracao = Math.min(duracao + PASSO_DURACAO_MIN, REGRAS[nivelAlvo].duracaoMin)
    ajustes.push('a última sessão foi leve — alongamos um pouco')
  }

  // Sessão difícil: recua um passo na duração.
  if (feedback === 'dificil') {
    duracao *= 0.8
    ajustes.push('a última sessão foi difícil — reduzimos para recuperar')
  }

  const duracaoMin = arredondar(duracao)

  // Meta da sessão: abaixo do nível 2, sempre os 20 min de atividade; do nível
  // 2 em diante o treinador escolhe por sessão entre 20 min e 3 km — distância
  // só quando o plano não está em recuperação e há distância sendo registrada.
  const emRecuperacao =
    feedback === 'dificil' ||
    (modelo.sinais.diasSemAtividade != null && modelo.sinais.diasSemAtividade >= 14)
  const metaSessao: MetaSessao =
    avaliacao.nivel >= 2 && !emRecuperacao && modelo.sinais.paceMedioMinKm != null ? 'distancia' : 'tempo'

  const porQue = avaliacao.bloqueado
    ? `Seu nível atual é ${avaliacao.nivel} e o plano está mantendo sem progredir: ${ajustes[0] ?? 'agora é hora de consolidar'}.`
    : avaliacao.proximo != null
      ? `Trabalhando para sair do nível ${avaliacao.nivel} para o nível ${avaliacao.proximo}.${ajustes.length > 0 ? ` ${ajustes[0][0].toUpperCase()}${ajustes[0].slice(1)}.` : ''}`
      : 'Você já é um corredor — o objetivo é manter a consistência e evoluir no seu ritmo.'

  return {
    nivelAlvo,
    frequenciaSemanal,
    atividade: regra.atividade,
    duracaoMin,
    intensidade: regra.intensidade,
    metaSessao,
    quandoRotulo: rotuloProximoDia(modelo.disponibilidade?.diasSemana ?? []),
    porQue,
    progressaoCongelada: avaliacao.bloqueado,
  }
}

const DIAS_NOME = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado']

/** "Hoje" se hoje é dia de sessão; senão "Amanhã" ou o próximo dia declarado. */
function rotuloProximoDia(dias: number[]): string {
  const hoje = new Date().getDay()
  if (dias.length === 0 || dias.includes(hoje)) return 'Hoje'
  let menor = 7
  for (const d of dias) {
    const dist = (d - hoje + 7) % 7
    if (dist > 0 && dist < menor) menor = dist
  }
  if (menor === 7) return 'Hoje' // defesa: só dá para ocorrer dentro de 7 dias
  if (menor === 1) return 'Amanhã'
  return DIAS_NOME[(hoje + menor) % 7]
}
