// Seletor numérico tipo roda, reutilizado no onboarding (cadastro e 1ª
// medição), na tela Perfil, no formulário pós-corrida, na edição do Histórico
// e na aba Saúde (marcadores). Porte do picker.ts do PWA:
// scroll com snap de ITEM_H, janela visível de 5 itens, frame de seleção
// central e fade nos itens distantes do centro.
//
// `onChange` dispara a cada mudança de valor enquanto a roda gira (necessário
// pro cálculo de idade ao vivo). `set` (via ref)
// reposiciona a roda de fora (necessário pro clamp de dia do mês).

import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react'
import {
  ScrollView,
  StyleSheet,
  Text,
  View,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
} from 'react-native'
import { theme } from '../theme'

export const ITEM_H = 36
const VISIVEIS = 5
const PAD_V = ((VISIVEIS - 1) / 2) * ITEM_H

export interface WheelPickerProps {
  min: number
  max: number
  step: number
  def: number
  /** Rótulo exibido no lugar do número (ex.: mês 3 -> "Mar"). */
  fmt?: (v: number) => string
  unit?: string
  label?: string
  onChange?: (v: number) => void
}

export interface WheelPickerHandle {
  /** Reposiciona a roda de fora. */
  set: (v: number, smooth?: boolean) => void
  /** Valor atualmente selecionado. */
  getValue: () => number
}

export const WheelPicker = forwardRef<WheelPickerHandle, WheelPickerProps>(
  function WheelPicker({ min, max, step, def, fmt, unit, label, onChange }, ref) {
    const valores = useMemo(() => {
      const vs: number[] = []
      for (let v = min; v <= max; v += step) vs.push(v)
      return vs
    }, [min, max, step])
    const last = valores.length - 1
    const clampIdx = (i: number): number => Math.min(last, Math.max(0, i))
    const idxDe = (v: number): number => clampIdx(Math.round((v - min) / step))

    const scrollRef = useRef<ScrollView>(null)
    const idxRef = useRef(idxDe(def))
    const [idx, setIdx] = useState(idxRef.current)
    const onChangeRef = useRef(onChange)
    onChangeRef.current = onChange

    // Posição inicial no valor padrão (equivalente ao toDef + rAF do PWA).
    useEffect(() => {
      const y = idxDe(def) * ITEM_H
      scrollRef.current?.scrollTo({ y, animated: false })
      const t = setTimeout(() => scrollRef.current?.scrollTo({ y, animated: false }), 50)
      return () => clearTimeout(t)
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [])

    const aplicarIdx = (i: number): void => {
      const c = clampIdx(i)
      if (c === idxRef.current) return
      idxRef.current = c
      setIdx(c)
      onChangeRef.current?.(min + c * step)
    }

    const aoRolar = (e: NativeSyntheticEvent<NativeScrollEvent>): void => {
      aplicarIdx(Math.round(e.nativeEvent.contentOffset.y / ITEM_H))
    }

    // Arraste lento que termina sem momentum não dispara onMomentumScrollEnd:
    // encaixa no item mais próximo ao soltar o dedo. Com velocidade residual,
    // o momentum vai rolar e o onMomentumScrollEnd cuida do encaixe.
    const aoSoltar = (e: NativeSyntheticEvent<NativeScrollEvent>): void => {
      const v = e.nativeEvent.velocity?.y ?? 0
      if (Math.abs(v) > 0.1) return
      const i = clampIdx(Math.round(e.nativeEvent.contentOffset.y / ITEM_H))
      scrollRef.current?.scrollTo({ y: i * ITEM_H, animated: true })
      aplicarIdx(i)
    }

    useImperativeHandle(ref, () => ({
      set: (v: number, smooth = true) => {
        const i = idxDe(v)
        aplicarIdx(i)
        scrollRef.current?.scrollTo({ y: i * ITEM_H, animated: smooth })
      },
      getValue: () => min + idxRef.current * step,
    }))

    return (
      <View style={styles.field}>
        {label ? <Text style={styles.label}>{label}</Text> : null}
        <View style={styles.picker}>
          <ScrollView
            ref={scrollRef}
            showsVerticalScrollIndicator={false}
            snapToInterval={ITEM_H}
            decelerationRate="fast"
            nestedScrollEnabled
            onScroll={aoRolar}
            onMomentumScrollEnd={aoRolar}
            onScrollEndDrag={aoSoltar}
            scrollEventThrottle={16}
            contentContainerStyle={{ paddingVertical: PAD_V }}
          >
            {valores.map((v, i) => {
              const dist = Math.abs(i - idx)
              return (
                <View key={v} style={styles.opt}>
                  <Text style={[styles.optTxt, { opacity: dist === 0 ? 1 : dist === 1 ? 0.45 : 0.18 }]}>
                    {fmt ? fmt(v) : v}
                  </Text>
                </View>
              )
            })}
          </ScrollView>
          <View pointerEvents="none" style={styles.frame} />
          {unit ? (
            <Text pointerEvents="none" style={styles.unit}>
              {unit}
            </Text>
          ) : null}
        </View>
      </View>
    )
  },
)

const styles = StyleSheet.create({
  field: {
    flexDirection: 'column',
    gap: 6,
  },
  label: {
    fontSize: 15,
    color: theme.label,
  },
  picker: {
    position: 'relative',
    height: ITEM_H * VISIVEIS,
    overflow: 'hidden',
    borderRadius: 12,
    backgroundColor: theme.bg,
    borderWidth: 1,
    borderColor: theme.separator,
  },
  opt: {
    height: ITEM_H,
    justifyContent: 'center',
    alignItems: 'center',
  },
  optTxt: {
    fontSize: 18,
    color: theme.label,
  },
  frame: {
    position: 'absolute',
    left: 8,
    right: 8,
    top: (ITEM_H * VISIVEIS - ITEM_H) / 2,
    height: ITEM_H,
    borderTopWidth: 1,
    borderBottomWidth: 1,
    borderColor: theme.separator,
  },
  unit: {
    position: 'absolute',
    right: 20,
    top: (ITEM_H * VISIVEIS - ITEM_H) / 2,
    height: ITEM_H,
    lineHeight: ITEM_H,
    color: theme.secondary,
    fontSize: 14,
  },
})
