// --- Limiares v1 (heurísticas iniciais, a calibrar com dados reais) ---
const SESSOES_MINIMAS_SEMANA = 2 // frequência mínima para os níveis 1+
const DURACAO_SUSTENTADA_MIN = 20 // nível 2: sustenta ~20 min
const DURACAO_SESSAO_CORRIDA_MIN = 20 // nível 3: sessões com trechos de corrida
const PACE_CAMINHADA_MAX_MIN_KM = 10 // abaixo disso já há trechos de corrida
const SEMANAS_CONSISTENTES_NIVEL_5 = 4
const GAP_INATIVIDADE_DIAS = 14 // 2+ semanas parado ⇒ não progredir; regressão

export interface AvaliacaoNivel {
  nivel: Nivel
  proximo: Nivel | null // null no topo da escala
  motivo: string // explicação do posicionamento (o "por quê")
  bloqueado: boolean // true quando o sistema não deve progredir agora
}

/** Situação declarada → piso de nível, usado quando ainda não há histórico. */
function nivelDeclarado(s: SituacaoAtual): Nivel {
  switch (s) {
    case 'sedentario':
    case 'caminha_as_vezes':
      return 0
    case 'caminha_regularmente':
      return 1
    case 'corre_as_vezes':
      return 3
    case 'corre_regularmente':
      return 4
  }
}

/** Posiciona o usuário na escala a partir dos sinais observados. */
export function posicionarNivel(
  sinais: SinaisObservados,
  declarada?: SituacaoAtual,
): Nivel {
  let observado: Nivel = 0
  if (sinais.sessoesPorSemana >= SESSOES_MINIMAS_SEMANA) {
    observado = 1
    if (sinais.maiorDuracaoMin >= DURACAO_SUSTENTADA_MIN) {
      observado = 2
      if (
        sinais.paceMedioMinKm != null &&
        sinais.paceMedioMinKm <= PACE_CAMINHADA_MAX_MIN_KM &&
        sinais.duracaoMedianaMin >= DURACAO_SESSAO_CORRIDA_MIN
      ) {
        observado = 3
      }
    }
    // A linha de chegada (3 km em 20 min) independe do pace médio da janela:
    // quem a completou já corre continuamente por definição. O nível 5 é o 4
    // com regularidade.
    if (sinais.completouObjetivo) {
      observado = 4
      if (sinais.semanasConsistentes >= SEMANAS_CONSISTENTES_NIVEL_5) {
        observado = 5
      }
    }
  }
  // A declaração é uma hipótese inicial; a observação a refina. Vale a maior.
  const piso = declarada != null ? nivelDeclarado(declarada) : 0
  return Math.max(observado, piso) as Nivel
}

/**
 * Avalia o nível atual combinando posicionamento, situações em que o sistema
 * não deve progredir (feedback difícil recente, lacuna de inatividade) e
 * regressão (2+ semanas sem atividade).
 */
export function avaliarNivel(
  sinais: SinaisObservados,
  feedbackRecente?: FeedbackSessao,
  declarada?: SituacaoAtual,
): AvaliacaoNivel {
  const base = posicionarNivel(sinais, declarada)
  const semHistorico = sinais.diasSemAtividade === null
  const gapLongo = !semHistorico && sinais.diasSemAtividade! >= GAP_INATIVIDADE_DIAS
  const bloqueado = gapLongo || feedbackRecente === 'dificil'

  // Regressão: lacuna longa de inatividade derruba um nível (sem passar de 0).
  let nivel = base
  let motivo: string
  if (gapLongo && base > 0) {
    nivel = (base - 1) as Nivel
    motivo = `Faz ${sinais.diasSemAtividade} dias sem atividade — voltamos um nível para retomar com segurança.`
  } else if (semHistorico && declarada != null) {
    motivo = 'Posicionamento inicial pela sua declaração — as próximas atividades vão refiná-lo.'
  } else if (semHistorico) {
    motivo = 'Ainda não há atividades registradas. O ponto de partida é o nível 0.'
  } else {
    const partes = [
      `Média de ${sinais.sessoesPorSemana.toFixed(1)} sessões por semana nas últimas 4 semanas`,
      `maior sessão de ${Math.round(sinais.maiorDuracaoMin)} min`,
    ]
    if (sinais.paceMedioMinKm != null) {
      partes.push(`pace médio de ${sinais.paceMedioMinKm.toFixed(1)} min/km`)
    }
    motivo = `${partes.join(', ')}.`
  }

  if (feedbackRecente === 'dificil' && !gapLongo) {
    motivo += ' A última sessão foi difícil — o plano não vai progredir por enquanto.'
  }

  return {
    nivel,
    proximo: nivel < 5 ? ((nivel + 1) as Nivel) : null,
    motivo,
    bloqueado,
  }
}

/** Rótulo curto do nível (ex.: "Nível 2 — Sustenta 20 minutos"). */
export function rotuloNivel(n: Nivel): string {
  return `Nível ${n} — ${NIVEIS[n].nome}`
}
