// Modelo local do treinador: Gemma 4 E2B (.litertlm) on-device via
// expo-litert-lm — o caminho validado no experimento
// (docs/experimento_llm_ondevice.md, seção A3). Este arquivo é o lado nativo;
// na web vale o stub modelo_local.web.ts e a conversa é sempre o DeepSeek
// remoto (llm.ts).
//
// Fluxo de fundo, iniciado no boot (iniciarModeloLocal):
//   inativo → aguardando_wifi → baixando → carregando → pronto
// O download (2,6 GB, uma única vez) só começa — e só prossegue — em Wi-Fi.
// Enquanto baixa ou carrega, a conversa segue no remoto; com 'pronto', o
// local assume (conversa.ts). Falha recuperável (rede, disco, carga) volta a
// 'inativo': a conversa fica no remoto e a próxima abertura tenta de novo.
//
// Proteção contra jetsam (iOS mata o processo por memória durante a carga):
// grava uma marcação ANTES de carregar. Processo morto = marcação sobrevive =
// este aparelho nunca mais tenta o modelo local ('bloqueado'). Exceção
// capturável não é quebra: limpa a marcação e permite nova tentativa.

import { Platform } from 'react-native'
import AsyncStorage from '@react-native-async-storage/async-storage'
import * as Rede from 'expo-network'
import RNBlobUtil from 'react-native-blob-util'
import {
  generateLiteRtResponse,
  isLiteRtAvailable,
  loadLiteRtModel,
  unloadLiteRtModel,
} from 'expo-litert-lm'
import { type MensagemLLM } from './llm'

export type FaseModelo =
  | 'inativo' // sem modelo: ainda não começou, sem suporte ou falhou nesta abertura
  | 'aguardando_wifi' // modelo ainda não baixado; o download espera Wi-Fi
  | 'baixando'
  | 'carregando'
  | 'pronto' // respondendo on-device
  | 'bloqueado' // o processo morreu numa carga anterior: nunca mais tenta

export interface EstadoModelo {
  fase: FaseModelo
  progresso: number // 0..1 — só faz sentido em 'baixando'
  erro?: string // motivo da última falha; a barra exibe para não falhar em silêncio
}

const URL_MODELO =
  'https://huggingface.co/litert-community/gemma-4-E2B-it-litert-lm/resolve/main/gemma-4-E2B-it.litertlm'
const TAMANHO_MODELO_BYTES = 2588147712
const LIMIAR_MEMORIA_MB = 900 // piso validado no spike: abaixo disso nem tenta
const CHAVE_TENTANDO = 'cl_modelo_tentando'
const TIMEOUT_RESPOSTA_MS = 60_000

const CAMINHO_MODELO = `${RNBlobUtil.fs.dirs.DocumentDir}/gemma-4-E2B-it.litertlm`
const CAMINHO_PARCIAL = `${CAMINHO_MODELO}.part` // baixa em andamento — retomável por Range

// --- Estado observável pela barra de status do shell ---

let estado: EstadoModelo = { fase: 'inativo', progresso: 0 }
const assinantes = new Set<() => void>()

export function estadoModeloLocal(): EstadoModelo {
  return estado
}

export function prontoParaLocal(): boolean {
  return estado.fase === 'pronto'
}

export function subscreverModeloLocal(fn: () => void): () => void {
  assinantes.add(fn)
  return () => {
    assinantes.delete(fn)
  }
}

function mudar(fase: FaseModelo, progresso = 0, erro?: string): void {
  estado = erro != null ? { fase, progresso, erro } : { fase, progresso }
  assinantes.forEach((fn) => fn())
}

// --- Fluxo de fundo ---

let iniciado = false

/** Chamar uma vez no boot. Nunca derruba o app: qualquer erro vira 'inativo'. */
export function iniciarModeloLocal(): void {
  if (iniciado) return
  iniciado = true
  void rodarFluxo()
}

async function rodarFluxo(): Promise<void> {
  try {
    // Marcação sobrevivendo a uma execução = o processo morreu no meio da
    // carga: aparelho bloqueado para o modelo local, para sempre.
    if ((await AsyncStorage.getItem(CHAVE_TENTANDO)) === '1') {
      mudar('bloqueado')
      return
    }
    if (!(await modeloBaixado())) {
      await baixarResumavel()
    }
    await carregar()
  } catch (erro) {
    // Falha recuperável: segue no remoto; a próxima abertura tenta de novo.
    // O motivo vai para a barra — falha silenciosa é bug invisível.
    mudar('inativo', 0, `download/carga falhou: ${String(erro).slice(0, 160)}`)
  }
}

/** Só prossegue quando a rede é Wi-Fi — o download de 2,6 GB é dela. */
async function esperarWifi(): Promise<void> {
  const rede = await Rede.getNetworkStateAsync()
  if (rede.type === Rede.NetworkStateType.WIFI) return
  mudar('aguardando_wifi')
  await new Promise<void>((resolver) => {
    const sub = Rede.addNetworkStateListener((s) => {
      if (s.type === Rede.NetworkStateType.WIFI) {
        sub.remove()
        resolver()
      }
    })
  })
}

async function tamanhoEm(caminho: string): Promise<number> {
  try {
    const st = await RNBlobUtil.fs.stat(caminho)
    return Number(st.size)
  } catch {
    return 0
  }
}

async function modeloBaixado(): Promise<boolean> {
  return (await tamanhoEm(CAMINHO_MODELO)) === TAMANHO_MODELO_BYTES
}

/**
 * Baixa resiliente: cada tentativa pede ao servidor só o que falta
 * (Range: bytes=N-) e anexa no `.part` — timeout, queda de rede ou troca
 * de rede continuam de onde pararam. A espera entre tentativas cresce até
 * 60 s e o Wi-Fi é aguardado, não exigido. Quando o `.part` completa,
 * é promovido ao nome final (o tamanho dele é a validação).
 */
async function baixarResumavel(): Promise<void> {
  let espera = 5_000
  for (;;) {
    await esperarWifi()
    let jaTem = await tamanhoEm(CAMINHO_PARCIAL)
    if (jaTem === 0) {
      // Legado: um parcial de build antigo no nome final é adotado como .part.
      const legado = await tamanhoEm(CAMINHO_MODELO)
      if (legado > 0 && legado < TAMANHO_MODELO_BYTES) {
        await RNBlobUtil.fs.mv(CAMINHO_MODELO, CAMINHO_PARCIAL).catch(() => {})
        jaTem = await tamanhoEm(CAMINHO_PARCIAL)
      }
    }
    if (jaTem >= TAMANHO_MODELO_BYTES) break // .part completo
    mudar('baixando', jaTem / TAMANHO_MODELO_BYTES)
    try {
      const cabecalhos: Record<string, string> = {}
      if (jaTem > 0) cabecalhos.Range = `bytes=${jaTem}-`
      // overwrite=false faz o trecho anexar ao .part na retomada.
      const tarefa = RNBlobUtil.config({
        path: CAMINHO_PARCIAL,
        overwrite: jaTem === 0,
      }).fetch('GET', URL_MODELO, cabecalhos)
      tarefa.progress((recebidos, total) => {
        const totalDoTrecho = Number(total)
        if (totalDoTrecho > 0) {
          mudar('baixando', Math.min(1, (jaTem + Number(recebidos)) / TAMANHO_MODELO_BYTES))
        }
      })
      const resposta = await tarefa
      const status = Number(resposta.respInfo.status)
      if (status === 206) continue // trecho anexado — o loop vê o novo tamanho
      if (status === 200 && jaTem === 0) continue // veio inteiro de primeira ✓
      // 200 com .part já grande = viria duplicado: descarta e recomeça.
      await RNBlobUtil.fs.unlink(CAMINHO_PARCIAL).catch(() => {})
    } catch {
      // Timeout, rede caiu, etc.: o `.part` guarda o progresso. Espera um
      // pouco (e a rede voltar) e continua de onde parou.
      await new Promise((r) => setTimeout(r, espera))
      espera = Math.min(espera * 2, 60_000)
    }
  }
  // Completo: promove o `.part`. Se o nome final já existir íntegro, só
  // descarta o excedente.
  if ((await tamanhoEm(CAMINHO_MODELO)) !== TAMANHO_MODELO_BYTES) {
    await RNBlobUtil.fs.mv(CAMINHO_PARCIAL, CAMINHO_MODELO)
  } else {
    await RNBlobUtil.fs.unlink(CAMINHO_PARCIAL).catch(() => {})
  }
}

async function carregar(): Promise<void> {
  mudar('carregando')
  if (!(await isLiteRtAvailable())) {
    mudar('inativo', 0, 'LiteRT-LM indisponível neste aparelho (requer iOS 17+)')
    return
  }
  const memoriaMB = await memoriaDisponivelMB()
  if (memoriaMB != null && memoriaMB < LIMIAR_MEMORIA_MB) {
    mudar('inativo', 0, `só ${memoriaMB} MB de memória livres (precisa de ~${LIMIAR_MEMORIA_MB} MB)`)
    return
  }
  // Marca ANTES de carregar: se o iOS encerrar o processo durante a carga,
  // a marcação sobrevive e o aparelho nunca mais tenta (rodarFluxo → bloqueado).
  await AsyncStorage.setItem(CHAVE_TENTANDO, '1')
  try {
    await loadLiteRtModel(CAMINHO_MODELO, { maxTokens: 2048 })
  } catch (erro) {
    // Exceção capturável não prova incompatibilidade: limpa a marca e libera
    // recursos para a próxima abertura tentar de novo.
    try {
      await unloadLiteRtModel()
    } catch {
      // Preserva o erro original da carga.
    }
    try {
      await AsyncStorage.removeItem(CHAVE_TENTANDO)
    } catch {
      // Preserva o erro original da carga.
    }
    throw erro
  }
  await AsyncStorage.removeItem(CHAVE_TENTANDO)
  mudar('pronto')
}

// modules/memoria (os_proc_available_memory) só existe no iOS: require
// preguiçoso para o Android não quebrar na importação. Sem o módulo, pula a
// verificação — a marcação anti-jetsam continua protegendo.
async function memoriaDisponivelMB(): Promise<number | null> {
  if (Platform.OS !== 'ios') return null
  try {
    const Memoria = require('../modules/memoria').default
    return await Memoria.disponivelMB()
  } catch {
    return null
  }
}

// --- Conversa ---

/** Mesma interface do DeepSeek remoto (llm.ts). O binding não expõe papel de
 *  sistema: system + fala vão juntos numa única mensagem de usuário — o
 *  formato validado no spike. */
export async function conversarLocal(mensagens: MensagemLLM[]): Promise<string> {
  const system = mensagens.find((m) => m.role === 'system')?.content ?? ''
  const fala = mensagens[mensagens.length - 1]?.content ?? ''
  return Promise.race([
    generateLiteRtResponse(`${system}\n\nPergunta do usuário: ${fala}`),
    new Promise<never>((_, reject) =>
      setTimeout(
        () => reject(new Error(`modelo local sem resposta em ${TIMEOUT_RESPOSTA_MS / 1000}s`)),
        TIMEOUT_RESPOSTA_MS,
      ),
    ),
  ])
}
