// Tela Ajuda: como funciona, objetivo da fase, dicas e apagar dados.
// A seção "Instalar no iPhone" do PWA não foi portada — app nativo já está
// instalado.

import React from 'react'
import { Alert, Platform, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native'
import { resetTudo, useStore, OBJETIVO } from '../state'
import { type Nav } from '../nav'
import { resetarModulo } from './Entradas'
import { cancelarTodosLembretes } from '../notifications'
import { theme } from '../theme'

export function Ajuda({ nav }: { nav: Nav }): React.JSX.Element {
  useStore()

  const confirmar = (): void => {
    resetarModulo() // rascunho/corrida em curso vivem em vars de módulo
    void cancelarTodosLembretes() // lembretes de compromisso ficam no sistema, fora do storage
    resetTudo()
    // cl_onboarded apagada -> o App volta pro onboarding (cadastro -> medição)
    nav.go('entradas')
  }

  const apagar = (): void => {
    const msg = 'Apagar perfil e corridas? Não dá pra desfazer.'
    // Alert.alert é no-op no react-native-web: na web a confirmação vai
    // pelo confirm do navegador.
    if (Platform.OS === 'web') {
      if (window.confirm(`Apagar tudo e recomeçar\n\n${msg}`)) confirmar()
      return
    }
    Alert.alert('Apagar tudo e recomeçar', msg, [
      { text: 'Cancelar', style: 'cancel' },
      { text: 'Apagar', style: 'destructive', onPress: confirmar },
    ])
  }

  return (
    <ScrollView contentContainerStyle={styles.centro}>
      <View style={styles.card}>
        <Text style={styles.section}>Como funciona</Text>
        <Text style={styles.p}>
          O objetivo desta fase: conseguir percorrer{' '}
          <Text style={styles.strong}>
            {OBJETIVO.distanciaKm} km em {OBJETIVO.duracaoMin} minutos
          </Text>
          , no seu ritmo — intercalando corrida e caminhada enquanto não consegue.
        </Text>
        <Text style={styles.p}>
          <Text style={styles.strong}>1.</Text> Registre cada treino em <Text style={styles.strong}>Entradas</Text>:
          toque <Text style={styles.italic}>Comecei</Text> ao sair e <Text style={styles.italic}>Parei</Text> ao
          terminar. A hora e o dia ficam anotados sozinhos.
        </Text>
        <Text style={styles.p}>
          <Text style={styles.strong}>2.</Text> Acompanhe em <Text style={styles.strong}>Resultados</Text>: sequência de
          dias, total e histórico.
        </Text>
        <Text style={styles.section}>Dicas leves</Text>
        <Text style={styles.li}>• O exercício mais natural do mundo: vá no seu ritmo.</Text>
        <Text style={styles.li}>• Intercale corrida e caminhada no começo — não tem problema.</Text>
        <Text style={styles.li}>
          • Constância vence intensidade. Melhor 3× por semana leve que 1× exaustiva.
        </Text>
        <Text style={styles.section}>Seus dados</Text>
        <Text style={styles.muted}>
          Treinos e medidas ficam só no seu aparelho. A conversa com o treinador é enviada a um
          serviço de IA (DeepSeek) para gerar as respostas.
        </Text>
        <Pressable style={({ pressed }) => [styles.ghost, pressed && styles.pressed]} onPress={apagar}>
          <Text style={styles.ghostDanger}>Apagar tudo e recomeçar</Text>
        </Pressable>
      </View>
    </ScrollView>
  )
}

const styles = StyleSheet.create({
  centro: {
    flexGrow: 1,
    justifyContent: 'center',
  },
  card: {
    backgroundColor: theme.card,
    borderRadius: 14,
    padding: 16,
    gap: 10,
  },
  section: {
    fontSize: 20,
    fontWeight: '600',
    marginTop: 10,
    marginBottom: 6,
    marginHorizontal: 4,
    color: theme.label,
  },
  p: {
    fontSize: 15,
    color: theme.label,
    lineHeight: 22,
  },
  li: {
    fontSize: 15,
    color: theme.label,
    lineHeight: 22,
  },
  strong: {
    fontWeight: '700',
  },
  italic: {
    fontStyle: 'italic',
  },
  muted: {
    fontSize: 15,
    color: theme.secondary,
  },
  ghost: {
    padding: 14,
    alignItems: 'center',
    alignSelf: 'stretch',
  },
  ghostDanger: {
    color: theme.red,
    fontSize: 17,
  },
  pressed: {
    opacity: 0.6,
  },
})
