// Corrida Leve — estado local (AsyncStorage). Sem backend por enquanto:
// sem coach, os dados são pessoais e ficam no aparelho.
//
// O PWA usava localStorage (síncrono); aqui um cache em memória é hidratado
// no boot (hydrate) e a API pública continua síncrona, com os mesmos nomes e
// assinaturas. As gravações no AsyncStorage são fire-and-forget. Mudanças
// notificam os assinantes (useStore) pra interface re-renderizar.

import AsyncStorage from '@react-native-async-storage/async-storage'
import { useSyncExternalStore } from 'react'
import { type ModeloUsuario, MODELO_USUARIO_VAZIO } from './usuario'
import { type EstadoAutopilot } from './autopilot'

export type Sexo = 'm' | 'f'
export type Local = 'externo' | 'esteira'

export interface Perfil {
  sexo: Sexo
  nome?: string // como o usuário quer ser chamado
  nascimento?: string // 'YYYY-MM-DD' — a idade é derivada daqui
  idade?: number // legado: perfis salvos antes de guardarmos a data de nascimento
  altura: number // cm
  foto?: string // data URI (base64) — substitui o ícone 👤 da topbar
  fotoPet?: string // data URI (base64) — aparece na topbar, à direita da foto do usuário
  // legado: perfis salvos antes dos marcadores trazem `peso` — ignorado (o
  // peso agora mora nos marcadores); regravar o perfil apaga o campo
}

export interface Corrida {
  id: string
  inicio: string // ISO
  fim: string // ISO
  duracaoMin: number
  distanciaKm?: number
  meta?: 'distancia' | 'tempo'
  peso?: number // legado: kg registrados por sessão antes dos marcadores
  local: Local
}

export interface Marcador {
  id: string
  quando: string // ISO da medição
  peso: number // kg (obrigatório)
  glicemia?: number // mg/dL — ausente = não informado
  pressaoSis?: number // mmHg — ausente = não informado
  pressaoDia?: number
}

/** Corrida em andamento — persistida para o cronômetro e a distância GPS
 *  sobreviverem a fechar o app. */
export interface CorridaEmCurso {
  inicio: number // epoch ms
  duracaoAlvoMin?: number // duração prescrita pelo Autopilot no início; teto do cronômetro
  distanciaKm?: number // distância GPS acumulada até o último ponto recebido
  metaSessao?: 'tempo' | 'distancia' // a meta do dia (decisao.ts): 20 min ou 3 km
}

/** Uma mensagem da conversa com o treinador (milestone 8). */
export interface MensagemConversa {
  id: string
  autor: 'treinador' | 'usuario'
  texto: string
  quando: string // ISO
}

// Objetivo fixo desta fase do protótipo: percorrer 3 km em 20 min.
export const OBJETIVO = { distanciaKm: 3, duracaoMin: 20 } as const

const K = {
  perfil: 'cl_perfil',
  corridas: 'cl_corridas',
  marcadores: 'cl_marcadores',
  onboarded: 'cl_onboarded',
  gpsDecidido: 'cl_gps_decidido',
  emCurso: 'cl_em_curso',
  rascunho: 'cl_rascunho',
  modeloUsuario: 'cl_modelo_usuario',
  autopilot: 'cl_autopilot',
  conversa: 'cl_conversa',
  avisoTreinador: 'cl_aviso_treinador',
  onboarding: 'cl_onboarding',
} as const

// --- Cache em memória + assinantes ---
const cache: Record<string, string | null> = {}
let hydrated = false
let version = 0
const listeners = new Set<() => void>()

function emit(): void {
  version++
  listeners.forEach((l) => l())
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => {
    listeners.delete(fn)
  }
}

function getVersion(): number {
  return version
}

/** Re-renderiza o componente a cada mudança de estado (equivalente ao
 *  re-render global que o PWA fazia a cada navegação/ação). */
export function useStore(): number {
  return useSyncExternalStore(subscribe, getVersion)
}

/** Lê todas as chaves do AsyncStorage pro cache. Chamar uma vez, no boot. */
export async function hydrate(): Promise<void> {
  const keys = Object.values(K) as string[]
  const pairs = await AsyncStorage.multiGet(keys)
  for (const [k, v] of pairs) cache[k] = v
  hydrated = true
  emit()
}

export function isHydrated(): boolean {
  return hydrated
}

function read<T>(key: string, fallback: T): T {
  try {
    const v = cache[key]
    return v ? (JSON.parse(v) as T) : fallback
  } catch {
    return fallback
  }
}

function write<T>(key: string, val: T): void {
  const s = JSON.stringify(val)
  cache[key] = s
  emit()
  AsyncStorage.setItem(key, s).catch(() => {})
}

function remove(key: string): void {
  cache[key] = null
  emit()
  AsyncStorage.removeItem(key).catch(() => {})
}

export function uid(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
}

// --- Perfil / onboarding ---
export function getPerfil(): Perfil | null {
  return read<Perfil | null>(K.perfil, null)
}
export function setPerfil(p: Perfil): void {
  write(K.perfil, p)
}
// O flag de onboarding concluído é separado do perfil: o Onboarding grava os
// dados assim que a conversa fecha e só conclui (libera o shell) no "Começar"
// da despedida — fechar o app nesse meio-tempo não perde nada.
export function setOnboarded(): void {
  write(K.onboarded, true)
}
export function isOnboarded(): boolean {
  return read<boolean>(K.onboarded, false)
}
// O aviso pré-permissão do GPS aparece uma única vez (na 1ª abertura do app);
// quem toca "Agora não" não é perguntado de novo — resta o link na tela Entradas.
export function getGpsDecidido(): boolean {
  return read<boolean>(K.gpsDecidido, false)
}
export function setGpsDecidido(): void {
  write(K.gpsDecidido, true)
}
export function resetTudo(): void {
  const keys = Object.values(K) as string[]
  keys.forEach((k) => {
    cache[k] = null
  })
  emit()
  AsyncStorage.multiRemove(keys).catch(() => {})
}

// --- User Model (parte declarada; os sinais observados são derivados em usuario.ts) ---
export function getModeloUsuario(): ModeloUsuario {
  return read<ModeloUsuario>(K.modeloUsuario, MODELO_USUARIO_VAZIO)
}
export function setModeloUsuario(m: ModeloUsuario): void {
  write(K.modeloUsuario, m)
}

// --- Autopilot State (fotografia do ciclo de decisão; quem calcula é autopilot.ts) ---
export function getAutopilot(): EstadoAutopilot | null {
  return read<EstadoAutopilot | null>(K.autopilot, null)
}
export function setAutopilot(e: EstadoAutopilot): void {
  write(K.autopilot, e)
}

// --- Conversa com o treinador (milestone 8; quem pensa é conversa.ts) ---
// Teto de mensagens: a conversa é recorte recente do relacionamento, não
// arquivo histórico — as mais antigas são descartadas.
const CONVERSA_MAX = 100
export function getConversa(): MensagemConversa[] {
  return read<MensagemConversa[]>(K.conversa, [])
}
export function addMensagemConversa(m: MensagemConversa): void {
  write(K.conversa, [...getConversa(), m].slice(-CONVERSA_MAX))
}

// --- Aviso do treinador: sinal de que ele tem assunto novo na conversa ---
// Gravado pelos gatilhos (onboarding concluído, compromisso perdido/cumprido,
// plano mudou); o shell avisa o usuário (diálogo) e a aba Treinador consome
// o aviso ao abrir a conversa com a abertura correspondente.
export type AvisoTreinador = 'inicio' | 'perdido' | 'cumprido' | 'plano' | 'meta'
export function getAvisoTreinador(): AvisoTreinador | null {
  return read<AvisoTreinador | null>(K.avisoTreinador, null)
}
export function setAvisoTreinador(a: AvisoTreinador): void {
  write(K.avisoTreinador, a)
}
export function clearAvisoTreinador(): void {
  remove(K.avisoTreinador)
}

// --- Corridas ---
export function getCorridas(): Corrida[] {
  return read<Corrida[]>(K.corridas, [])
}
export function addCorrida(c: Corrida): void {
  write(K.corridas, [...getCorridas(), c])
}
// Edição/exclusão pelo Histórico. No patch, uma chave com valor `undefined`
// some no JSON.stringify — é assim que se limpa um opcional (ex.: distanciaKm).
export function updateCorrida(id: string, patch: Partial<Corrida>): void {
  write(
    K.corridas,
    getCorridas().map((c) => (c.id === id ? { ...c, ...patch, id } : c)),
  )
}
export function removeCorrida(id: string): void {
  write(
    K.corridas,
    getCorridas().filter((c) => c.id !== id),
  )
}

// --- Marcadores (peso, glicemia, pressão) ---
export function getMarcadores(): Marcador[] {
  return read<Marcador[]>(K.marcadores, [])
}
export function addMarcador(m: Marcador): void {
  write(K.marcadores, [...getMarcadores(), m])
}
// Mesmo truque do updateCorrida: no patch, uma chave com valor `undefined`
// some no JSON.stringify — é assim que se limpa um opcional (ex.: glicemia).
export function updateMarcador(id: string, patch: Partial<Marcador>): void {
  write(
    K.marcadores,
    getMarcadores().map((m) => (m.id === id ? { ...m, ...patch, id } : m)),
  )
}
export function removeMarcador(id: string): void {
  write(
    K.marcadores,
    getMarcadores().filter((m) => m.id !== id),
  )
}
/** Medição mais recente (por `quando`) — base do pré-preenchimento do formulário. */
export function ultimoMarcador(): Marcador | null {
  const ms = getMarcadores()
  if (ms.length === 0) return null
  return ms.reduce((a, b) => (a.quando > b.quando ? a : b))
}

// --- Corrida em andamento ---
export function getCorridaEmCurso(): CorridaEmCurso | null {
  const c = read<CorridaEmCurso | null>(K.emCurso, null)
  return c && typeof c.inicio === 'number' ? c : null
}
export function setCorridaEmCurso(c: CorridaEmCurso): void {
  write(K.emCurso, c)
}
export function clearCorridaEmCurso(): void {
  remove(K.emCurso)
}

// --- Rascunho do onboarding: a conversa (falas + histórico LLM) persiste a
// cada fala — fechar o app no meio do questionário retoma de onde parou.
// `despedida` marca que os dados já foram gravados e falta só o "Começar";
// o rascunho só é limpo aí.
export interface RascunhoOnboarding {
  falas: { id: string; autor: 'treinador' | 'usuario'; texto: string }[]
  historico: { role: 'system' | 'user' | 'assistant'; content: string }[]
  conversaFechada: boolean
  despedida: boolean
}
export function getRascunhoOnboarding(): RascunhoOnboarding | null {
  const r = read<RascunhoOnboarding | null>(K.onboarding, null)
  return r && Array.isArray(r.falas) && Array.isArray(r.historico) ? r : null
}
export function setRascunhoOnboarding(r: RascunhoOnboarding): void {
  write(K.onboarding, r)
}
export function clearRascunhoOnboarding(): void {
  remove(K.onboarding)
}

// --- Rascunho: corrida encerrada, aguardando o formulário ---
// Persistido para que fechar o app com o formulário aberto não perca a corrida.
export function getRascunho(): Partial<Corrida> | null {
  const d = read<Partial<Corrida> | null>(K.rascunho, null)
  return d && typeof d.id === 'string' && typeof d.inicio === 'string' ? d : null
}
export function setRascunho(d: Partial<Corrida>): void {
  write(K.rascunho, d)
}
export function clearRascunho(): void {
  remove(K.rascunho)
}

// --- Derivados ---
// total de dias distintos com pelo menos uma corrida (duas no mesmo dia contam 1)
export function diasTreinados(corridas: Corrida[] = getCorridas()): number {
  return new Set(corridas.map((c) => c.inicio.slice(0, 10))).size
}

// --- Objetivo (3 km em 20 min): progresso visível pro usuário ---
// Diferente do `completouObjetivo` de usuario.ts (janela de 4 semanas, usado
// pela escala de níveis), aqui vale o histórico todo: atingir é uma vez na vida.

/** A primeira sessão que fecha o objetivo, em ordem cronológica. */
export function atingiuObjetivo(corridas: Corrida[] = getCorridas()): Corrida | null {
  const ord = [...corridas].sort((a, b) => a.inicio.localeCompare(b.inicio))
  return (
    ord.find(
      (c) => (c.distanciaKm ?? 0) >= OBJETIVO.distanciaKm && c.duracaoMin <= OBJETIVO.duracaoMin,
    ) ?? null
  )
}

export interface ProgressoObjetivo {
  sustenta20Min: boolean // etapa 1: alguma sessão com a duração do objetivo
  melhorKm: number | null // etapa 2: melhor distância dentro da duração do objetivo
}

/** Etapa 2 conta só sessões de até 20 min: uma sessão mais longa teve tempo
 *  extra pra somar distância, não é comparável com a linha de chegada. */
export function progressoObjetivo(corridas: Corrida[] = getCorridas()): ProgressoObjetivo {
  const sustenta20Min = corridas.some((c) => c.duracaoMin >= OBJETIVO.duracaoMin)
  const dentroDos20 = corridas.filter(
    (c) => c.duracaoMin <= OBJETIVO.duracaoMin && (c.distanciaKm ?? 0) > 0,
  )
  const melhorKm =
    dentroDos20.length > 0 ? Math.max(...dentroDos20.map((c) => c.distanciaKm!)) : null
  return { sustenta20Min, melhorKm }
}

// --- Idade ---
export function diasNoMes(ano: number, mes: number): number {
  return new Date(ano, mes, 0).getDate() // dia 0 do mês seguinte = último deste
}

/** Idade completa em anos numa data 'YYYY-MM-DD'. */
export function idadeEm(nascimento: string, hoje: Date = new Date()): number {
  const [a, m, d] = nascimento.split('-').map(Number)
  const passou = hoje.getMonth() + 1 > m || (hoje.getMonth() + 1 === m && hoje.getDate() >= d)
  return hoje.getFullYear() - a - (passou ? 0 : 1)
}

export function idadeDe(p: Perfil): number {
  return p.nascimento ? idadeEm(p.nascimento) : (p.idade ?? 40)
}
