// Cliente LLM: chama o proxy no Cloudflare Workers (server/), que injeta a
// chave real da DeepSeek e aplica os controles anti-abuso. O app conhece
// apenas a URL do Worker e o token compartilhado, que ficam em
// src/config.local.ts (não commitado — ver .gitignore e server/README.md).

import { LLM_API_KEY, LLM_BASE_URL, LLM_MODEL } from './config.local';

export interface MensagemLLM {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

const TIMEOUT_MS = 20_000;

export async function conversar(mensagens: MensagemLLM[]): Promise<string> {
  const chamada = (async () => {
    const resp = await fetch(`${LLM_BASE_URL}/chat/completions`, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${LLM_API_KEY}`,
      },
      body: JSON.stringify({ model: LLM_MODEL, messages: mensagens, stream: false }),
    });
    if (!resp.ok) {
      throw new Error(`LLM ${resp.status}: ${await resp.text()}`);
    }
    const data = await resp.json();
    return (data.choices?.[0]?.message?.content ?? '') as string;
  })();
  // Promise.race em vez de AbortSignal.timeout: ausente em parte dos runtimes RN.
  return Promise.race([
    chamada,
    new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error(`LLM sem resposta em ${TIMEOUT_MS / 1000}s`)), TIMEOUT_MS),
    ),
  ]);
}
