// Formatadores de data/hora compartilhados entre telas.

export function fmtData(iso: string): string {
  return new Date(iso).toLocaleDateString('pt-BR', { weekday: 'short', day: '2-digit', month: '2-digit' })
}

export function fmtDataHora(iso: string): string {
  const d = new Date(iso)
  return `${fmtData(iso)} · ${d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`
}

export function fmtElapsed(ms: number): string {
  const s = Math.floor(ms / 1000)
  const m = Math.floor(s / 60)
  const r = s % 60
  return `${String(m).padStart(2, '0')}:${String(r).padStart(2, '0')}`
}

/** Horário de compromisso por extenso: "hoje às 18:00", "amanhã às 18:00"
 *  ou a data completa quando mais distante. */
export function fmtCompromisso(iso: string): string {
  const d = new Date(iso)
  const hora = d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })
  const amanha = new Date()
  amanha.setDate(amanha.getDate() + 1)
  if (d.toDateString() === new Date().toDateString()) return `hoje às ${hora}`
  if (d.toDateString() === amanha.toDateString()) return `amanhã às ${hora}`
  return fmtDataHora(iso)
}
