import PostHog from 'posthog-react-native'
import type { PostHogEventProperties } from '@posthog/core'
import type { TipoAtividade } from './decisao'
import type { FeedbackSessao } from './usuario'

// Só em produção e com chave configurada (EXPO_PUBLIC_POSTHOG_KEY /
// EXPO_PUBLIC_POSTHOG_HOST); sem elas, tudo vira no-op.
const KEY = process.env.EXPO_PUBLIC_POSTHOG_KEY
const HOST = process.env.EXPO_PUBLIC_POSTHOG_HOST
const telemetryEnabled = !__DEV__ && !!KEY

let posthog: PostHog | null = null

function capture(event: string, properties?: PostHogEventProperties): void {
  if (!telemetryEnabled || !posthog) return
  posthog.capture(event, properties)
}

export const telemetry = {
  init() {
    if (!telemetryEnabled) return
    try {
      posthog = new PostHog(KEY as string, {
        host: HOST,
        captureAppLifecycleEvents: false,
      })
    } catch {
      // Telemetria não pode derrubar o app: se a init falhar, fica no-op.
      posthog = null
    }
  },

  appOpened() {
    capture('app_opened')
  },

  onboardingCompleted() {
    capture('onboarding_completed')
  },

  runStarted(atividade: TipoAtividade, duracaoMin: number) {
    capture('run_started', { atividade, duracao_min: duracaoMin })
  },

  runFinished(durationSeconds: number) {
    capture('run_finished', {
      duration_seconds: durationSeconds,
    })
  },

  runSaved() {
    capture('run_saved')
  },

  feedbackRecorded(feedback: FeedbackSessao) {
    capture('feedback_recorded', { feedback })
  },

  compromissoCombinado(atividade: string) {
    capture('commitment_accepted', { atividade })
  },

  compromissoCumprido() {
    capture('commitment_fulfilled')
  },

  compromissoPerdido() {
    capture('commitment_missed')
  },

  treinadorMensagem(intent: string) {
    capture('coach_message', { intent })
  },

  treinadorAbertura() {
    capture('coach_proactive')
  },

  markerSaved() {
    capture('marker_saved')
  },

  resultsViewed() {
    capture('results_viewed')
  },
}
