// Gráfico de marcadores (aba Saúde): linha valor × data — peso, glicemia ou
// pressão. Visual copiado da Progressao:
//
//   eixo x (horizontal, rolável): dias do calendário, da 1ª medição até hoje.
//     linha 1 — dia do mês
//     linha 2 — mês (faixa alinhada aos dias)
//   eixo y (fixo, à esquerda): janela min–max dos valores, com folga
//   linha em SVG (Polyline), um ponto por medição; 1 ou 2 séries (pressão
//     desenha sistólica e diastólica juntas)
//
// Somente leitura: sem marcador de seleção — a lista abaixo mostra os valores.

import React, { useMemo } from 'react'
import { ScrollView, StyleSheet, Text, View } from 'react-native'
import Svg, { Circle, Polyline } from 'react-native-svg'
import { theme } from '../theme'

export interface PontoMarcador {
  id: string
  quando: string // ISO da medição
  valores: (number | null)[] // um por série; null = não informado naquele dia
}

const MESES = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez']

const DAY_W = 30 // largura de cada dia (px)
const PLOT_H = 176 // altura da área de plotagem
const AXIS_H = 44 // 2 faixas × 22px: dia + mês

function meiaNoite(iso: string): Date {
  const d = new Date(iso)
  d.setHours(0, 0, 0, 0)
  return d
}
function diasEntre(a: Date, b: Date): number {
  return Math.round((b.getTime() - a.getTime()) / 86400000)
}

// Marcações do eixo y: múltiplos de um passo "redondo", escolhido pra ficar
// com 3–5 ticks dentro da janela.
function ticksDeValor(vMin: number, vMax: number): number[] {
  const span = vMax - vMin
  const passo = [1, 2, 5, 10, 20, 25, 50].find((p) => span / p <= 4) ?? 100
  const ts: number[] = []
  for (let v = Math.ceil(vMin / passo) * passo; v <= vMax; v += passo) ts.push(v)
  return ts
}

interface Dados {
  xs: number[]
  series: (number | null)[][] // series[s][i] = valor da série s no ponto i
  canvasW: number
  y: (v: number) => number
  ticksY: number[]
  dias: { d: number; left: number }[]
  bandasMes: { label: string; left: number; width: number }[]
}

function preparar(pontos: PontoMarcador[]): Dados | null {
  const ps = [...pontos].sort((a, b) => a.quando.localeCompare(b.quando))
  if (ps.length === 0) return null
  const inicio = meiaNoite(ps[0].quando)
  const ultMedicao = meiaNoite(ps[ps.length - 1].quando)
  const hoje = meiaNoite(new Date().toISOString())
  const fim = ultMedicao.getTime() > hoje.getTime() ? ultMedicao : hoje
  const nDias = diasEntre(inicio, fim) + 1
  const canvasW = nDias * DAY_W

  // Janela do eixo y a partir dos dados, com folga nas duas pontas.
  const valores = ps.flatMap((p) => p.valores).filter((v): v is number => v != null)
  if (valores.length === 0) return null
  let vMin = Math.min(...valores)
  let vMax = Math.max(...valores)
  if (vMax - vMin < 1) {
    vMin -= 1 // medições iguais: abre uma janela pra linha não colar na borda
    vMax += 1
  }
  const folga = (vMax - vMin) * 0.1
  vMin = Math.floor(vMin - folga)
  vMax = Math.ceil(vMax + folga)
  const y = (v: number): number => ((vMax - v) / (vMax - vMin)) * PLOT_H

  const xs: number[] = []
  for (const p of ps) {
    const idx = diasEntre(inicio, meiaNoite(p.quando))
    xs.push(idx * DAY_W + DAY_W / 2)
  }
  const nSeries = Math.max(...ps.map((p) => p.valores.length))
  const series: (number | null)[][] = []
  for (let s = 0; s < nSeries; s++) series.push(ps.map((p) => p.valores[s] ?? null))

  const dias: { d: number; left: number }[] = []
  const bandasMes: { label: string; left: number; width: number }[] = []
  let chaveMes = -1
  for (let i = 0; i < nDias; i++) {
    const dt = new Date(inicio)
    dt.setDate(inicio.getDate() + i)
    dias.push({ d: dt.getDate(), left: i * DAY_W })
    const k = dt.getFullYear() * 12 + dt.getMonth()
    if (k !== chaveMes) {
      bandasMes.push({ label: MESES[dt.getMonth()], left: i * DAY_W, width: DAY_W })
      chaveMes = k
    } else {
      bandasMes[bandasMes.length - 1].width += DAY_W
    }
  }

  return { xs, series, canvasW, y, ticksY: ticksDeValor(vMin, vMax), dias, bandasMes }
}

/**
 * @param pontos medições com valor, em qualquer ordem (são ordenadas aqui)
 * @param cores  uma por série (pressão: sistólica, diastólica)
 * @param unidade sufixo dos ticks do eixo y (kg, mg/dL, mmHg)
 */
export function GraficoMarcador({
  pontos,
  cores,
  unidade,
}: {
  pontos: PontoMarcador[]
  cores: string[]
  unidade: string
}): React.JSX.Element {
  const dados = useMemo(() => preparar(pontos), [pontos])

  if (!dados) {
    return <Text style={styles.vazio}>Sem medições pra mostrar ainda.</Text>
  }

  return (
    <View style={styles.graf}>
      <View style={styles.eixoY}>
        {dados.ticksY.map((v) => (
          <Text key={v} style={[styles.eixoYTxt, { top: dados.y(v) - 6 }]}>
            {v}
            <Text style={styles.eixoYUn}> {unidade}</Text>
          </Text>
        ))}
      </View>
      <ScrollView horizontal style={styles.scroll} showsHorizontalScrollIndicator={false}>
        <View style={{ width: dados.canvasW, height: PLOT_H + AXIS_H }}>
          {/* grade */}
          {dados.ticksY.map((v) => (
            <View key={v} style={[styles.gline, { top: dados.y(v) }]} />
          ))}
          {/* linhas e pontos */}
          <Svg width={dados.canvasW} height={PLOT_H}>
            {dados.series.map((vals, s) => {
              const cor = cores[s] ?? theme.blue
              const trecho = vals
                .map((v, i) => (v != null ? `${dados.xs[i]},${dados.y(v)}` : null))
                .filter((p): p is string => p != null)
                .join(' ')
              return (
                <React.Fragment key={s}>
                  {trecho ? (
                    <Polyline
                      points={trecho}
                      fill="none"
                      stroke={cor}
                      strokeWidth={2}
                      strokeLinejoin="round"
                      strokeLinecap="round"
                    />
                  ) : null}
                  {vals.map((v, i) =>
                    v != null ? (
                      <Circle key={i} cx={dados.xs[i]} cy={dados.y(v)} r={3.5} fill={cor} />
                    ) : null,
                  )}
                </React.Fragment>
              )
            })}
          </Svg>
          {/* eixo x: dia + mês */}
          <View style={[styles.axLinha, { top: PLOT_H }]}>
            {dados.dias.map((dd, i) => (
              <Text key={i} style={[styles.dnum, { left: dd.left, width: DAY_W }]}>
                {dd.d}
              </Text>
            ))}
          </View>
          <View style={[styles.axLinha, { top: PLOT_H + 22 }]}>
            {dados.bandasMes.map((b, i) => (
              <Text key={i} style={[styles.mband, { left: b.left, width: b.width }]}>
                {b.label}
              </Text>
            ))}
          </View>
        </View>
      </ScrollView>
    </View>
  )
}

const styles = StyleSheet.create({
  vazio: {
    color: theme.secondary,
    fontSize: 15,
  },
  graf: {
    flexDirection: 'row',
    gap: 6,
  },
  eixoY: {
    width: 44,
    height: PLOT_H,
  },
  eixoYTxt: {
    position: 'absolute',
    right: 0,
    fontSize: 10,
    color: theme.secondary,
  },
  eixoYUn: {
    fontSize: 8,
  },
  scroll: {
    flex: 1,
  },
  gline: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 1,
    backgroundColor: theme.separator,
  },
  axLinha: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 22,
  },
  dnum: {
    position: 'absolute',
    textAlign: 'center',
    fontSize: 10,
    color: theme.secondary,
    lineHeight: 22,
  },
  mband: {
    position: 'absolute',
    textAlign: 'center',
    fontSize: 11,
    color: theme.label,
    lineHeight: 22,
    borderLeftWidth: 1,
    borderLeftColor: theme.separator,
  },
})
