// Tela Perfil: edição do cadastro (nome, sexo, data de nascimento, altura e
// fotos — a do usuário substitui o 👤 da topbar; a do seu amor aparece ao lado).
// Mesmas rodas do onboarding, já posicionadas nos valores salvos. O peso não
// mora mais aqui — virou marcador na aba Saúde. Salvar regrava o perfil
// inteiro: os campos legados `peso` e `idade` (perfis de antes dos marcadores
// e da data de nascimento) somem junto.

import React, { useCallback, useEffect, useRef, useState } from 'react'
import { Alert, Image, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native'
import * as ImagePicker from 'expo-image-picker'
import { type Sexo, getPerfil, setPerfil, idadeEm, diasNoMes, useStore } from '../state'
import { type Nav } from '../nav'
import { WheelPicker, type WheelPickerHandle } from '../components/WheelPicker'
import { CartaoNivel } from '../components/CartaoNivel'
import { theme } from '../theme'

const MESES = ['Jan', 'Fev', 'Mar', 'Abr', 'Mai', 'Jun', 'Jul', 'Ago', 'Set', 'Out', 'Nov', 'Dez']
const pad = (n: number): string => String(n).padStart(2, '0')
const iso = (a: number, m: number, d: number): string => `${a}-${pad(m)}-${pad(d)}`

export function Perfil({ nav }: { nav: Nav }): React.JSX.Element {
  useStore()
  const perfil = getPerfil()
  const anoAtual = new Date().getFullYear()

  const [nome, setNome] = useState(perfil?.nome ?? '')
  const [sexo, setSexo] = useState<Sexo | null>(perfil?.sexo ?? null)
  const [idadeTxt, setIdadeTxt] = useState('—')
  // Fotos em data URI (base64): o perfil inteiro mora no AsyncStorage.
  const [foto, setFoto] = useState(perfil?.foto)
  const [fotoPet, setFotoPet] = useState(perfil?.fotoPet)

  // Foto se grava na hora (não espera o "Alterar"): a topbar lê do store.
  const gravarFoto = (campo: 'foto' | 'fotoPet', uri: string | undefined): void => {
    const p = getPerfil()
    if (p) setPerfil({ ...p, [campo]: uri })
  }

  // Recorte quadrado e qualidade baixa: a foto vira um avatar pequeno na topbar.
  const escolherFoto = (campo: 'foto' | 'fotoPet', aplicar: (uri: string | undefined) => void) => async (): Promise<void> => {
    const r = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ['images'],
      allowsEditing: true,
      aspect: [1, 1],
      quality: 0.3,
      base64: true,
    })
    const asset = r.canceled ? null : r.assets[0]
    if (asset?.base64) {
      const uri = `data:image/jpeg;base64,${asset.base64}`
      aplicar(uri)
      gravarFoto(campo, uri)
    }
  }

  const removerFoto = (campo: 'foto' | 'fotoPet', aplicar: (uri: string | undefined) => void) => (): void => {
    aplicar(undefined)
    gravarFoto(campo, undefined)
  }

  const diaRef = useRef<WheelPickerHandle>(null)
  const mesRef = useRef<WheelPickerHandle>(null)
  const anoRef = useRef<WheelPickerHandle>(null)
  const alturaRef = useRef<WheelPickerHandle>(null)

  // Defaults das rodas: data salva; perfil legado (só `idade`) vira 1º de janeiro
  // do ano correspondente; sem nada, os mesmos defaults do onboarding.
  const [anoSalvo, mesSalvo, diaSalvo] = perfil?.nascimento?.split('-').map(Number) ?? []
  const defAno = anoSalvo ?? (perfil?.idade != null ? anoAtual - perfil.idade : anoAtual - 40)
  const defMes = mesSalvo ?? 1
  const defDia = diaSalvo ?? 1

  // Recalcula a idade a cada giro das rodas da data; mês curto puxa o dia de volta.
  const recalc = useCallback((): void => {
    const ano = anoRef.current?.getValue() ?? defAno
    const mes = mesRef.current?.getValue() ?? defMes
    const dia = diaRef.current?.getValue() ?? defDia
    const ultimo = diasNoMes(ano, mes)
    if (dia > ultimo) {
      diaRef.current?.set(ultimo) // dispara recalc de novo, já com o dia válido
      return
    }
    const anos = idadeEm(iso(ano, mes, dia))
    setIdadeTxt(`${anos} ${anos === 1 ? 'ano' : 'anos'}`)
  }, [defAno, defMes, defDia])

  // Idade inicial (equivalente ao recalc() pós-mount do onboarding).
  useEffect(() => {
    recalc()
  }, [recalc])

  if (!perfil) return <View style={styles.tela} />

  const salvar = (): void => {
    if (!sexo) {
      Alert.alert('Selecione o sexo.')
      return
    }
    const ano = anoRef.current!.getValue()
    const mes = mesRef.current!.getValue()
    const dia = Math.min(diaRef.current!.getValue(), diasNoMes(ano, mes))
    setPerfil({
      nome: nome.trim() || undefined,
      sexo,
      nascimento: iso(ano, mes, dia),
      altura: alturaRef.current!.getValue(),
      foto,
      fotoPet,
    })
    nav.go('entradas')
  }

  return (
    <ScrollView keyboardShouldPersistTaps="handled">
      <View style={styles.card}>
        <Text style={styles.muted}>
          Usados pra calcular a zona de frequência cardíaca e acompanhar sua evolução.
        </Text>

        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Nome</Text>
          <TextInput
            style={styles.input}
            value={nome}
            onChangeText={setNome}
            placeholder="Como você quer ser chamado"
            placeholderTextColor={theme.secondary}
            autoCapitalize="words"
            returnKeyType="done"
          />
        </View>

        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Fotos</Text>
          <View style={styles.fotosRow}>
            <View style={styles.fotoCell}>
              <View>
                <Pressable
                  style={({ pressed }) => pressed && styles.pressed}
                  onPress={escolherFoto('foto', setFoto)}
                  accessibilityLabel={foto ? 'Trocar sua foto' : 'Escolher sua foto'}
                >
                  {foto ? (
                    <Image source={{ uri: foto }} style={styles.fotoImg} />
                  ) : (
                    <View style={[styles.fotoImg, styles.fotoVazia]}>
                      <Text style={styles.fotoPlaceholder}>👤</Text>
                    </View>
                  )}
                </Pressable>
                {foto ? (
                  <Pressable
                    style={({ pressed }) => [styles.fotoBadge, pressed && styles.pressed]}
                    onPress={removerFoto('foto', setFoto)}
                    accessibilityLabel="Remover sua foto"
                  >
                    <Text style={styles.fotoBadgeTxt}>✕</Text>
                  </Pressable>
                ) : null}
              </View>
              <Text style={styles.fotoLabel}>Eu</Text>
            </View>
            <View style={styles.fotoCoracaoBox}>
              <Text style={styles.fotoCoracao}>🤍</Text>
            </View>
            <View style={styles.fotoCell}>
              <View>
                <Pressable
                  style={({ pressed }) => pressed && styles.pressed}
                  onPress={escolherFoto('fotoPet', setFotoPet)}
                  accessibilityLabel={fotoPet ? 'Trocar a foto do seu amor' : 'Escolher a foto do seu amor'}
                >
                  {fotoPet ? (
                    <Image source={{ uri: fotoPet }} style={styles.fotoImg} />
                  ) : (
                    <View style={[styles.fotoImg, styles.fotoVazia]}>
                      <Text style={styles.fotoPlaceholder}>❤️</Text>
                    </View>
                  )}
                </Pressable>
                {fotoPet ? (
                  <Pressable
                    style={({ pressed }) => [styles.fotoBadge, pressed && styles.pressed]}
                    onPress={removerFoto('fotoPet', setFotoPet)}
                    accessibilityLabel="Remover a foto do seu amor"
                  >
                    <Text style={styles.fotoBadgeTxt}>✕</Text>
                  </Pressable>
                ) : null}
              </View>
              <Text style={styles.fotoLabel}>Meu amor</Text>
            </View>
          </View>
          <Text style={styles.muted}>Clique nos ícones/fotos para adicionar/trocar as fotos.</Text>
        </View>

        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Sexo</Text>
          <View style={styles.seg}>
            <Pressable style={[styles.segBtn, sexo === 'm' && styles.segBtnOn]} onPress={() => setSexo('m')}>
              <Text style={[styles.segTxt, sexo === 'm' && styles.segTxtOn]}>Masculino</Text>
            </Pressable>
            <Pressable style={[styles.segBtn, sexo === 'f' && styles.segBtnOn]} onPress={() => setSexo('f')}>
              <Text style={[styles.segTxt, sexo === 'f' && styles.segTxtOn]}>Feminino</Text>
            </Pressable>
          </View>
        </View>

        <View style={styles.field}>
          <Text style={styles.fieldLabel}>Data de nascimento</Text>
          <View style={styles.pickerRow}>
            <View style={styles.pickerCell}>
              <WheelPicker ref={diaRef} min={1} max={31} step={1} def={defDia} label="Dia" onChange={recalc} />
            </View>
            <View style={styles.pickerCell}>
              <WheelPicker
                ref={mesRef}
                min={1}
                max={12}
                step={1}
                def={defMes}
                label="Mês"
                fmt={(v) => MESES[v - 1]}
                onChange={recalc}
              />
            </View>
            <View style={styles.pickerCell}>
              <WheelPicker
                ref={anoRef}
                min={anoAtual - 100}
                max={anoAtual - 5}
                step={1}
                def={defAno}
                label="Ano"
                onChange={recalc}
              />
            </View>
          </View>
          <Text style={styles.idadeCalc}>
            Idade: <Text style={styles.idadeValor}>{idadeTxt}</Text>
          </Text>
        </View>

        <WheelPicker ref={alturaRef} min={120} max={210} step={1} def={perfil.altura} label="Altura" unit="cm" />

        <View style={styles.actions}>
          <Pressable
            style={({ pressed }) => [styles.ghostBtn, pressed && styles.pressed]}
            onPress={() => nav.go('entradas')}
          >
            <Text style={styles.ghostTxt}>Cancelar</Text>
          </Pressable>
          <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={salvar}>
            <Text style={styles.primaryTxt}>Alterar</Text>
          </Pressable>
        </View>
      </View>

      <CartaoNivel />
    </ScrollView>
  )
}

