// Tela de onboarding (milestone 10): a primeira conversa treinador–aluno.
// O LLM conduz a descoberta (quem pensa é onboardingLLM.ts); esta tela cuida
// dos balões e da extração dos dados ao final. A conversa persiste a cada
// fala (state.ts: rascunho do onboarding) — fechar o app no meio retoma de
// onde parou. Quando a extração fecha sem faltantes, os dados são gravados
// na hora (perfil, primeiro marcador, parte declarada do User Model) e a
// despedida avisa que tudo se ajusta no perfil — sem resumo de confirmação.
// Tela cheia, fora do shell — o App só mostra as abas depois.
// Sem conexão o treinador não responde: o onboarding do alpha exige internet.

import React, { useEffect, useRef, useState } from 'react'
import {
  KeyboardAvoidingView,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  TextInput,
  View,
} from 'react-native'
import {
  addMarcador,
  clearRascunhoOnboarding,
  getModeloUsuario,
  getPerfil,
  getRascunhoOnboarding,
  setAvisoTreinador,
  setModeloUsuario,
  setOnboarded,
  setPerfil,
  setRascunhoOnboarding,
  uid,
} from '../state'
import { recalcularAutopilot } from '../autopilot'
import { type MensagemLLM } from '../llm'
import * as Speech from 'expo-speech'
import { ExpoSpeechRecognitionModule, useSpeechRecognitionEvent } from 'expo-speech-recognition'
import { MicIcon } from '../components/MicIcon'
import { SpeakerIcon } from '../components/SpeakerIcon'
import {
  type Extraido,
  FRASE_DELEGACAO,
  TOKEN_FIM,
  conversarOnboarding,
  extrairDados,
  faltantes,
  semToken,
} from '../onboardingLLM'
import { telemetry } from '../telemetry'
import { theme } from '../theme'

interface Fala {
  id: string
  autor: 'treinador' | 'usuario'
  texto: string
}

// Abertura fixa: economiza uma chamada e garante o primeiro passo da conversa.
// Já declara o contrato do app: saúde com caminhada/corrida leve no ritmo do
// dia a dia — não performance (visão §1).
const ABERTURA =
  'Oi! Eu sou o treinador do Corrida Leve. Meu trabalho é te ajudar a cuidar da saúde com caminhada e corrida leve, num ritmo que caiba no seu dia a dia — aqui não é app de atleta nem de competição. Pra começar: como você quer ser chamado?'

const FALA_DE_CONEXAO = 'Tive uma falha de conexão — eu preciso de internet para conversar. Pode repetir?'

export function Onboarding({ fonteMarca }: { fonteMarca: string | null }): React.JSX.Element {
  // Rascunho persistido (a loja já está hidratada — o App espera o hydrate):
  // reabrir o app no meio do questionário retoma a conversa de onde parou.
  const [rascunho0] = useState(getRascunhoOnboarding)
  const [falas, setFalas] = useState<Fala[]>(
    rascunho0?.falas ?? [{ id: uid(), autor: 'treinador', texto: ABERTURA }],
  )
  const [entrada, setEntrada] = useState('')
  const [aguardando, setAguardando] = useState(false)
  const [conversaFechada, setConversaFechada] = useState(rascunho0?.conversaFechada ?? false)
  const [despedida, setDespedida] = useState(rascunho0?.despedida ?? false)
  const [ouvindo, setOuvindo] = useState(false)
  const [falandoId, setFalandoId] = useState<string | null>(null)
  // Histórico no formato OpenAI, espelhando as falas (a abertura entra como
  // fala do assistente). Fica em ref: não precisa re-renderizar.
  const historico = useRef<MensagemLLM[]>(
    rascunho0?.historico ?? [{ role: 'assistant', content: ABERTURA }],
  )
  const scrollRef = useRef<ScrollView>(null)
  // Envio no meio da ditagem: aborta o reconhecimento e ignora resultados
  // atrasados, senão a transcrição repõe no campo o texto recém-enviado.
  const ignorarTranscricao = useRef(false)
  const entradaRef = useRef<TextInput>(null)
  // Android: se a palavra enviada estava em composição (sublinhada pelo
  // corretor — o caso da ortografia correta), o teclado a "comita" DEPOIS do
  // clear e o campo repovoaria. O eco chega como onChangeText com exatamente
  // o texto recém-enviado: ignora o estado e limpa o nativo de verdade.
  const recemEnviado = useRef<string | null>(null)

  const onChangeEntrada = (t: string): void => {
    if (recemEnviado.current != null && t === recemEnviado.current) {
      recemEnviado.current = null
      entradaRef.current?.clear()
      return
    }
    recemEnviado.current = null
    setEntrada(t)
  }

  useEffect(() => {
    scrollRef.current?.scrollToEnd({ animated: true })
  }, [falas.length, aguardando])

  // A conversa persiste a cada fala. O rascunho só é limpo no "Começar" da
  // despedida: fechar o app em qualquer ponto retoma exatamente de onde parou.
  useEffect(() => {
    setRascunhoOnboarding({ falas, historico: historico.current, conversaFechada, despedida })
  }, [falas, conversaFechada, despedida])

  const falaTreinador = (texto: string): void => {
    setFalas((f) => [...f, { id: uid(), autor: 'treinador', texto }])
  }

  // Voz no onboarding: ditar as respostas (reconhecimento da Apple) — o
  // texto cai no campo para revisão antes de enviar.
  useSpeechRecognitionEvent('result', (e) => {
    if (ignorarTranscricao.current) return
    const transcricao = e.results[e.results.length - 1]?.transcript
    if (transcricao != null) setEntrada(transcricao)
  })
  useSpeechRecognitionEvent('end', () => setOuvindo(false))
  useSpeechRecognitionEvent('error', () => setOuvindo(false))

  const alternarVoz = async (): Promise<void> => {
    if (ouvindo) {
      ExpoSpeechRecognitionModule.stop()
      return
    }
    const permissoes = await ExpoSpeechRecognitionModule.requestPermissionsAsync()
    if (!permissoes.granted) return
    ignorarTranscricao.current = false
    setEntrada('')
    setOuvindo(true)
    ExpoSpeechRecognitionModule.start({ lang: 'pt-BR', interimResults: true })
  }

  const ouvirMensagem = (f: Fala): void => {
    if (falandoId === f.id) {
      Speech.stop()
      setFalandoId(null)
      return
    }
    Speech.stop()
    setFalandoId(f.id)
    Speech.speak(f.texto, {
      language: 'pt-BR',
      rate: 1.0,
      onDone: () => setFalandoId((atual) => (atual === f.id ? null : atual)),
      onStopped: () => setFalandoId((atual) => (atual === f.id ? null : atual)),
      onError: () => setFalandoId((atual) => (atual === f.id ? null : atual)),
    })
  }

  // Extrai os dados da conversa. Se faltar campo obrigatório, devolve a lista
  // ao treinador (mensagem de sistema) e a conversa continua; se faltar de
  // novo, a próxima extração acontece no próximo PLANO_PRONTO ou no Concluir.
  // Sem faltantes: grava na hora e cai na despedida — sem confirmação.
  const extrair = async (): Promise<void> => {
    const e = await extrairDados(historico.current)
    if (e == null) {
      falaTreinador(FALA_DE_CONEXAO)
      return
    }
    const falta = faltantes(e)
    if (falta.length === 0) {
      gravar(e)
      return
    }
    historico.current.push({
      role: 'user',
      content: `[sistema] Ainda faltam estas informações: ${falta.join(', ')}. Pergunte-as de forma natural. Quando tiver tudo, repita a despedida com ${TOKEN_FIM}.`,
    })
    const resp = await conversarOnboarding(historico.current)
    historico.current.push({ role: 'assistant', content: semToken(resp) })
    falaTreinador(semToken(resp))
    if (resp.includes(TOKEN_FIM)) {
      setConversaFechada(true)
      await extrair()
    } else {
      setConversaFechada(false) // a conversa reabriu para completar dados
    }
  }

  const enviar = (texto: string): void => {
    const limpo = texto.trim()
    if (limpo === '' || aguardando) return
    if (ouvindo) {
      ignorarTranscricao.current = true
      ExpoSpeechRecognitionModule.abort()
    }
    setFalas((f) => [...f, { id: uid(), autor: 'usuario', texto: limpo }])
    historico.current.push({ role: 'user', content: limpo })
    recemEnviado.current = texto
    setEntrada('')
    setAguardando(true)
    void conversarOnboarding(historico.current)
      .then(async (resp) => {
        historico.current.push({ role: 'assistant', content: semToken(resp) })
        falaTreinador(semToken(resp))
        if (resp.includes(TOKEN_FIM)) {
          setConversaFechada(true)
          await extrair()
        }
      })
      .catch(() => {
        historico.current.pop() // a fala não chegou ao LLM — não corrompe o contexto
        falaTreinador(FALA_DE_CONEXAO)
      })
      .finally(() => setAguardando(false))
  }

  // A conversa fechou com tudo: grava perfil, primeiro marcador e a parte
  // declarada do User Model na hora — sem confirmação (sexo, nascimento,
  // altura, peso, situação e disponibilidade foram validados em faltantes()).
  // A despedida avisa que qualquer ajuste depois é no perfil.
  const gravar = (e: Extraido): void => {
    setPerfil({
      nome: e.nome?.trim() || undefined,
      sexo: e.sexo!,
      nascimento: e.nascimento!,
      altura: e.alturaCm!,
    })
    addMarcador({ id: uid(), quando: new Date().toISOString(), peso: e.pesoKg! })
    setModeloUsuario({
      ...getModeloUsuario(), // preserva feedbacks e compromissos, se houver
      situacaoDeclarada: e.situacao!,
      objetivo: e.objetivo?.trim() || undefined,
      disponibilidade: {
        sessoesPorSemana: e.sessoesPorSemana!,
        minutosPorSessao: e.minutosPorSessao!,
        diasSemana: e.diasSemana ?? [],
        ...(e.horaPreferida != null ? { horaPreferida: e.horaPreferida } : {}),
      },
    })
    recalcularAutopilot() // o plano já nasce da disponibilidade declarada
    setDespedida(true) // persiste via efeito: fechar o app aqui volta à despedida
  }

  const comecar = (): void => {
    clearRascunhoOnboarding()
    setAvisoTreinador('inicio') // o shell cai na aba Treinador: 1º combinado é na conversa
    telemetry.onboardingCompleted()
    setOnboarded() // emite pro store: o App percebe isOnboarded() e mostra o shell
  }

  // Despedida: os dados já estão gravados — não há o que confirmar. Só a
  // delegação e o aviso de que tudo se ajusta depois no perfil (👤).
  if (despedida) {
    const nome = getPerfil()?.nome
    return (
      <View style={[styles.tela, styles.conteudo, styles.centrado]}>
        <Text style={styles.lead}>
          {FRASE_DELEGACAO.replace('Certo.', nome != null ? `Certo, ${nome}.` : 'Certo.')}
        </Text>
        <Text style={styles.despedidaNota}>
          Já anotei tudo. Se algo mudar — peso, disponibilidade, como você quer ser chamado — ajuste
          no seu perfil: toque no 👤, lá em cima.
        </Text>
        <Pressable style={({ pressed }) => [styles.primary, pressed && styles.pressed]} onPress={comecar}>
          <Text style={styles.primaryTxt}>Começar</Text>
        </Pressable>
      </View>
    )
  }

  return (
    // 'padding' nas duas plataformas: no Android o edge-to-edge obrigatório
    // quebra o adjustResize nativo, e o teclado cobria a caixa de entrada.
    <KeyboardAvoidingView style={styles.tela} behavior="padding">
      <ScrollView
        ref={scrollRef}
        contentContainerStyle={styles.conteudo}
        keyboardShouldPersistTaps="handled"
      >
        <View style={styles.brand}>
          <Text style={styles.brandSmall}>corrida</Text>
          <Text style={[styles.brandScript, fonteMarca ? { fontFamily: fonteMarca } : null]}>leve</Text>
        </View>
        {falas.map((f) =>
          f.autor === 'treinador' ? (
            <View key={f.id} style={styles.linhaTreinador}>
              <View style={[styles.balao, styles.balaoTreinador]}>
                <Text style={styles.balaoTxt}>{f.texto}</Text>
              </View>
              <Pressable
                style={({ pressed }) => [
                  styles.ouvir,
                  (falandoId === f.id || pressed) && styles.ouvirAtivo,
                ]}
                onPress={() => ouvirMensagem(f)}
                accessibilityLabel={
                  falandoId === f.id ? 'Parar de ouvir' : 'Ouvir mensagem do treinador'
                }
              >
                <SpeakerIcon
                  tamanho={16}
                  cor={falandoId === f.id ? theme.blue : theme.label}
                  tocando={falandoId === f.id}
                />
              </Pressable>
            </View>
          ) : (
            <View key={f.id} style={[styles.balao, styles.balaoUsuario]}>
              <Text style={[styles.balaoTxt, styles.balaoTxtUsuario]}>{f.texto}</Text>
            </View>
          ),
        )}
        {aguardando ? (
          <View style={[styles.balao, styles.balaoTreinador]}>
            <Text style={styles.balaoTxt}>…</Text>
          </View>
        ) : null}
      </ScrollView>
      <View style={styles.rodape}>
        {conversaFechada ? (
          <Pressable
            style={({ pressed }) => [styles.primary, pressed && styles.pressed]}
            onPress={() => {
              if (aguardando) return
              setAguardando(true)
              void extrair()
                .catch(() => falaTreinador(FALA_DE_CONEXAO))
                .finally(() => setAguardando(false))
            }}
          >
            <Text style={styles.primaryTxt}>{aguardando ? 'Extraindo…' : 'Concluir'}</Text>
          </Pressable>
        ) : (
          <View style={styles.entradaRow}>
            <TextInput
              ref={entradaRef}
              style={styles.entrada}
              value={entrada}
              onChangeText={onChangeEntrada}
              placeholder={ouvindo ? 'Ouvindo… fale agora' : 'Escreva pro treinador…'}
              placeholderTextColor={theme.secondary}
              returnKeyType="send"
              onSubmitEditing={() => enviar(entrada)}
            />
            <Pressable
              style={({ pressed }) => [styles.voz, (ouvindo || pressed) && styles.vozAtiva]}
              onPress={() => void alternarVoz()}
              accessibilityLabel={ouvindo ? 'Parar de ouvir' : 'Falar com o treinador'}
            >
              <MicIcon tamanho={20} cor={ouvindo ? theme.red : theme.label} gravando={ouvindo} />
            </Pressable>
            <Pressable
              style={({ pressed }) => [styles.enviar, pressed && styles.pressed]}
              onPress={() => enviar(entrada)}
            >
              <Text style={styles.enviarTxt}>Enviar</Text>
            </Pressable>
          </View>
        )}
      </View>
    </KeyboardAvoidingView>
  )
}

